/* ⛔ GENERATED by kit/build.mjs from i18n/uk.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["uk"] = {"hero.headline":"<span class=\"hl-muted\">Одна сесія.</span> <span class=\"hl-bright\">Четверо продюсерів.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Без сервера.</span>","hero.cycle":"Без сервера.|Без облікового запису.|Без ШІ.","hero.tagline":"DAW, у якій четверо продюсерів працюють в одній сесії водночас.","what.title":"Що це","what.p1":"Будь-яка DAW — програма для однієї людини. Зробити запис із кимось із іншої країни досі означає експортувати стеми, завантажити їх, чекати, імпортувати назад і загубити нитку — а через пів року ніхто вже не пам'ятає, хто написав басову лінію.","what.p2":"Oscillate — повноцінна DAW, побудована на протилежному припущенні. Ви вставляєте код кімнати в чат, і до трьох інших продюсерів заходять у вашу сесію: ви бачите їхні камери, чуєте їх, їхні курсори рухаються вашою стрічкою часу, а наприкінці програма друкує спліт-шит, у якому сказано, хто що написав.","what.p3":"Сьогодні це безкоштовно, і позаду немає сервера. Код кімнати і є пропозицією з'єднання: перший вставляє код, а далі кімната передає зв'язок усім іншим. Нічого підтримувати, нічого оплачувати, нічого, що хтось міг би вимкнути.","features.title":"Що всередині","features.room.title":"Кімната","features.room.body":"До чотирьох продюсерів, напряму один до одного, без облікового запису й без сервера. Живі курсори, чат, голос, плитки камер і демонстрація екрана. Ваше скасування повертає вашу правку й ніколи чужу.","features.arrangement.title":"Аранжування","features.arrangement.body":"Необмежена кількість аудіо- та MIDI-доріжок, кліпи, намальовані з власного вмісту, доріжки автоматизації, компінг, групи, маркери, карта темпу й розміру. Будь-яка правка скасовується одним натисканням, скількох би кліпів вона не торкнулася.","features.pianoRoll.title":"Piano roll","features.pianoRoll.body":"Близько дев'яноста ладів із підсвічуванням, прив'язкою та згортанням, ноти-привиди з будь-якого іншого кліпу, доріжка велосіті з ручкою на кожній ноті та грабельна клавіатура, де одна клавіша грає цілий акорд.","features.plugins.title":"Хостинг плагінів","features.plugins.body":"VST3 і CLAP, кожен у власному процесі — плагін, що впав, гасить один пристрій, а не забирає з собою сесію. Компенсація затримки по всьому графу, доведена нульовим тестом, а не заявлена.","features.devices.title":"Власні інструменти","features.devices.body":"Шістдесят дев'ять інструментів і ефектів, панелі яких намальовані з опису самого пристрою — число на ручці це те число, з яким працює звук, виміряне з точністю до десятої децибела.","features.cut.title":"Розріз","features.cut.body":"Проведіть лезом по аранжуванню, і воно розріже кожен кліп, який перетне; кут штриха задає крутизну кросфейду. Це мова руху, на якій побудовано весь інтерфейс.","features.kumite.title":"Кумітe і спліт-шит","features.kumite.body":"Режим битви бітів, де кожен хід володіє власними тактами, і реєстр авторства, виведений із журналу правок, із відрахованою роботою, яку хтось скасував.","features.free.title":"Безкоштовно, і без ШІ","features.free.body":"Ніяких рівнів, пробних періодів, облікових записів і ліцензійних ключів. Ні моделі, ні висновування, нічого «розумного» — і це забезпечує складальна перевірка, яка падає, щойно у граф залежностей потрапляє будь-яке середовище машинного навчання, а не лишається обіцянкою.","ladder.title":"Дорога до 1.0","ladder.intro":"Один рядок на щабель. Це та сама драбина, якої дотримується внутрішній план — якщо зсувається один, зсуваються обидва, і складальна перевірка їх звіряє.","ladder.rung.v0.0.1":"Фундамент, хребет CI, ліцензія та EULA — і порожнє вікно, яке вже встановлюється на трьох операційних системах.","ladder.rung.v0.1.0":"Оболонка й аудіорушій. Має вигляд Oscillate і видає звук.","ladder.rung.v0.2.0":"Проєкт і вигляд аранжування. Це DAW.","ladder.rung.v0.2.5":"Редактори — piano roll, барабанна сітка, автоматизація, компінг, Розріз, Ката, Перемотування сесії.","ladder.rung.v0.3.0":"Хостинг плагінів і вбудовані пристрої — VST3 і CLAP поза процесом, а також шістдесят дев'ять власних.","ladder.rung.v0.4.0":"Інструменти для написання — Файловий браузер, «Стеми в генератори» і шлях експорту.","ladder.rung.v0.4.5":"Рішення «так/ні» щодо вебзастосунку, кидання на стрічку часу, власне обличчя кожного пристрою і монопольний звук.","ladder.rung.v0.5.0":"Кімната, ядро — з'єднання без сервера, присутність, синхронізація й чат.","ladder.rung.v0.5.5":"Кімната, наживо — голос, відео, демонстрація екрана, Передавання, Куміте і спліт-шит.","ladder.rung.v0.6.0":"Ідентичність — доріжка тексту, Таймлапс сесії, картки сесій і сторінка подяк.","ladder.rung.v0.6.5":"Спільний вигляд родини, однаковий у кожному застосунку Freally: ручки, фейдери й кнопки, відрендерені в Blender, п’ять скінів у світлому й темному варіантах, звуки інтерфейсу та темний рядок заголовка, — і одна бібліотека інструментів, спільна з Freally MIDI Master.","ladder.rung.v1.0.0b":"Публічна бета, автооновлювач, цей сайт та ілюстрований посібник. На цій сторінці завантажень немає.","ladder.rung.v1.0.0RC":"Зміцнення, оптимізація й повний прохід огляду — туди, куди вкажуть знахідки бети.","ladder.rung.v1.0.0":"Стабільна версія. І перші завантаження, які будь-коли існували.","ladder.note":"Готовий щабель зібрано і він лежить у гілці розробки. Це не завантаження: їх немає й не буде до 1.0.0.","honest.title":"Те, що більшість сайтів ховає в самий низ","honest.peers.title":"Четверо продюсерів, а не п'ятеро","honest.peers.body":"У кімнаті вміщається четверо. Сервера, що пересилає звук, немає, тож кожен надсилає кожному, і п'яте з'єднання — це місце, де звичайний домашній вихідний канал вичерпується. Чотири — число, яке працює, а не число, яке гарно звучало.","honest.failure.title":"Приблизно одне з'єднання з десяти не встановиться","honest.failure.body":"Деякі мережі видають кожному вихідному з'єднанню нову адресу, і два таких не знайдуть одне одного без ретранслятора посередині. Ретранслятор назавжди коштує трафіку — це постійний рахунок, який безкоштовній програмі не потягнути, тому Oscillate постачається без нього й дає вписати свій у налаштуваннях. Коли з'єднання не вдається, програма називає, яка з дев'яти причин це була.","honest.code.title":"Що насправді містить код кімнати","honest.code.body":"Це сама пропозиція з'єднання, і в ній є публічна адреса вашого комп'ютера. Ставтеся до нього як до пароля: надсилайте лише тим, з ким працюєте. Застосунок каже про це в мить, коли ви його копіюєте.","honest.downloads.title":"До 1.0.0 завантажень немає","honest.downloads.body":"На цій сторінці немає бети, немає попередньої збірки, немає раннього доступу. DAW, яка працює наполовину, гірша за ту, якої ще немає.","honest.ai.title":"Жодного ШІ — і як це забезпечено","honest.ai.body":"Складальна перевірка обходить граф залежностей і падає на будь-якому середовищі висновування, будь-якому файлі моделі та будь-якій бібліотеці аналітики чи звітів про збої. Це властивість збірки, а не фраза на сайті.","honest.updater.title":"Єдине з'єднання, яке робить застосунок","honest.updater.body":"Перевірка оновлень, і лише коли ви натиснули кнопку або ввімкнули перевірку під час запуску — типово вона вимкнена. Вона запитує один статичний файл і не надсилає нічого про вас чи вашу машину, кожне оновлення підписане, і жодне не встановлюється без вашого вибору.","site.tagline":"DAW, у якій четверо продюсерів працюють в одній сесії водночас.","footer.licence":"Пропрієтарне ПЗ — усі права захищено. © Mike Weaver. Наразі безкоштовне для використання; майбутні версії можуть продаватися. Не з відкритим кодом.","footer.yours":"Те, що ви створите з його допомогою, належить вам. Автор Oscillate не претендує на проєкти, MIDI, звук і зведення, які ви в ньому робите.","features.7ffdfbe91dc1":"Повноцінна DAW із кімнатою всередині: до чотирьох продюсерів в одній сесії, наживо, без облікового запису й без сервера.","features.02a7818a6ee0":"Ця сторінка описує Freally Oscillate таким, яким він буде у версії 1.0 — на щаблі, яким закінчується драбина, — і нічого з того, що заплановано після неї.","features.b4a6bff8b8c9":"Кожне число — це підрахунок того, що містить версія 1.0. Нічого не оцінено приблизно й нічого не округлено вгору. Freally Secretarium звучить із тієї самої бібліотеки інструментів, що й Freally MIDI Master: одна бібліотека, закріплена в обох, а не дві копії, які поступово розходяться.","features.7ec427c672a2":"продюсери в одній кімнаті","features.d6f79cef6f38":"власних інструментів і ефектів","features.3a6743460cf9":"інструментів у Freally Secretarium","features.18c9c4777852":"ладів у piano roll","features.7241e8c55883":"наборів ударних","features.79067e736ea9":"скінів, кожен у світлому й темному варіантах","features.9bb4817f8251":"мов, включно з письмом справа наліво","features.09b3154dfa60":"облікових записів, які треба створити","features.35b8cb8439d7":"моделей ШІ","features.38055402e560":"ціна сьогодні","features.da9afac0d7b7":"Сьогодні це безкоштовно. Усе цілком.","features.f997324cb19b":"Кожна функція — для всіх. Жодного платного рівня, жодного пробного періоду, що закінчується, жодного ліцензійного ключа, жодного облікового запису й жодних покупок у застосунку.","features.22f1bb054323":"Те, що ви створите з його допомогою, належить вам. Автор Oscillate не претендує на проєкти, MIDI, звук і зведення, які ви в ньому робите, і не просить ні відрахувань, ні згадки.","features.c74ea9dc9cd2":"Що він робить","features.45a1b4ecfbf5":"Кімната, за якою немає сервера","features.c3ea64baf32c":"Надішліть код кімнати тим, з ким працюєте, і до трьох інших продюсерів зможуть приєднатися до вашої сесії: їхні курсори на вашій стрічці часу, чат, голос, плитки камер і демонстрація екрана. Напряму один до одного, без облікового запису й без сервера посередині.","features.225507990407":"Ваше скасування — тільки ваше","features.cb2c6359ccf6":"<kbd>Ctrl</kbd>+<kbd>Z</kbd> скасовує вашу останню зміну й ніколи чужу, навіть поки надходять чужі правки. Журнал правок, що стоїть за цим, — це також синхронізація кімнати, Перемотування сесії та спліт-шит.","features.056c3540052c":"Передавання","features.be31856f2db7":"Передайте одну доріжку співавторові й заберіть її однією клавішею. Поки доріжка в нього, лише він може її змінювати — навіть ви ні, — і це забезпечується там, де перевіряються правки, а не лише в інтерфейсі.","features.f4d5f7765113":"Куміте","features.d3a91a73c5cc":"Режим біт-батлу, у якому кожен хід володіє власними тактами. Зворотний відлік — це лише відлік; правило — такти, тож два комп'ютери ніколи не розійдуться в тому, чия правка була законною.","features.6ed23a3037fc":"Спліт-шит","features.68481398e863":"Хто що написав — виведено з журналу правок, а роботу, яку хтось скасував, вирахувано. Відправна точка для розмови про авторство, а не юридичний документ, — і він прямо про це каже.","features.6ffb37f5c47d":"Дублі передаються, семпли — ніколи","features.2dc43d70f9ea":"Дубль, записаний у кімнаті, з'являється на стрічці часу в кожного. Куплений вами семпл не надсилається ніколи: кімната передає посилання на нього, а співавторові без цього семпл-паку повідомляють, які семпли йому потрібні.","features.2e5511855cbc":"Аранжування","features.b9277cfd1dc1":"Необмежена кількість аудіо- та MIDI-доріжок, кліпи, намальовані з того, чим вони є, автоматизація кожного фейдера, панорами й регулятора пристрою, компінг, групи, маркери, карти темпу й розміру. Патерн, розміщений десять разів, — це один патерн: змініть його один раз — і зміниться кожне розміщення, доки ви не зробите одне з них унікальним.","features.3933d56d65a8":"Розріз і Перемотування сесії","features.7e57d69f84a4":"Проведіть лезом штрих по аранжуванню, і він розріже кожен кліп, який перетне, а кут штриха задасть кросфейд. Прокручуйте історію сесії, як відео, і відгалужуйтеся від будь-якої її точки.","features.dac11b27d868":"Piano roll","features.8b5fc8a25fa8":"Близько дев'яноста ладів із підсвічуванням, прив'язкою та згортанням, примарні ноти з будь-якого іншого кліпу, доріжка велосіті з ручкою на кожній ноті, доріжки для того, як часто звучить кожна нота і наскільки далеко відхиляється її велосіті, і клавіатура, де одна клавіша може грати цілий акорд.","features.a4592301df0c":"Запис і компінг","features.3b56c85ac1f3":"Запис аудіо й апаратна MIDI-клавіатура в Windows, macOS і Linux. Дублі складаються один під одним, ви вибираєте потрібні частини, а дублі, які ви не вибрали, ніколи не видаляються. Аудіо записується на диск у міру надходження, тож збій коштує останнього блока, а не дубля.","features.0baacdf5d6c4":"Ваші плагіни, кожен у власному процесі","features.5fab46c33502":"VST3 і CLAP. Плагін, що впав, робить сірим свій пристрій, а сесія працює далі. Компенсація затримки діє на весь граф і доведена нульовим тестом, а плагін, якого на цій машині немає, стає іменованою заглушкою, тож проєкт, відкритий деінде, лишається в часі.","features.74ed3ebdb3f9":"Власні інструменти й ефекти","features.07e3bfdc40c6":"Шістдесят дев'ять пристроїв, серед них Freally Secretarium і його 1 648 інструментів. Кожна панель малюється з власного опису пристрою, тож число на ручці — це те число, яке використовує звук, а налаштування пристрою копіюються одним рядком, який можна вставити в чат.","features.afc35db2da83":"Пристрої, що читають аранжування","features.8d6419ade018":"Шість пристроїв роблять те, чого не може плагін, бо плагін не бачить пісні, в якій стоїть: компресор, що вже тримає приспів, коли той починається, гейт, що відкривається для удару ще до того, як він пролунає, дилей, що спорожняється до тактової риски. Жоден із шести не додає затримки.","features.bdb597b1232d":"Мікшер","features.4d7f4826526b":"Лінійка на кожну доріжку з фейдером, панорамою, глушінням, соло, стійкою пристроїв та індикатором рівня, що малюється зі звуку, який справді видав рушій. Радар маскування називає дві доріжки, що борються за ту саму смугу, і саму частоту; панель гучності показує інтегровану й короткочасну гучність у LUFS, діапазон та істинний пік порівняно з цільовими рівнями кожного стримінгового сервісу.","features.787726eabc9d":"Доріжка тексту","features.7d820a1cb209":"Текст пісні як доріжка на стрічці часу, прив'язана до курсора відтворення й розбита на склади, імпортована з <code>.txt</code> або <code>.lrc</code> і скопійована в проєкт, — шрифтом, розрахованим на те, щоб співати з іншого кінця кімнати.","features.c01fa2f5481f":"Картки сесій і Таймлапс сесії","features.ef0a07e0d7a5":"Одне клавіатурне скорочення рендерить зображення сесії 1200×630 для публікації. Таймлапс сесії відтворює всю сесію з її журналу правок як анімоване зображення з розділами — навіть сесію, яку ніхто не здогадався записати.","features.8b8dc99cf84d":"Ваша сесія відкривається без Oscillate","features.3ab5583a8c27":"У супровідну теку записуються стеми й MIDI, які відкриє будь-яка інша DAW, — вирівняні по такту 1, у вибраних вами форматі, частоті дискретизації та розрядності.","features.d91ad4caafa2":"Сімейний вигляд","features.d65f870603be":"Ручки, фейдери й кнопки, відрендерені в Blender, п'ять скінів у світлому й темному варіантах поряд з обома темами, короткі звуки інтерфейсу, які можна вимкнути, і вісімнадцять мов зі справжнім письмом справа наліво — однаковий вигляд у кожному застосунку Freally.","features.c87ebc921598":"Жодних «дзвінків додому»","features.1c72614b8ea2":"Ні облікового запису, ні телеметрії. Мережу він використовує лише в трьох випадках: кімната, яку ви відкрили або до якої приєдналися, визначення адреси, поки ця кімната встановлюється, і перевірка оновлень, вимкнена, доки ви її не ввімкнете. Звіти про збої лишаються на вашому диску, якщо ви не вирішите надіслати один із них.","features.ae2bbaa95738":"Жодного ШІ — це гарантує збірка","features.db3a0428cdec":"Ні моделі, ні висновування, нічого генеративного. Складальна перевірка обходить граф залежностей і падає на будь-якому середовищі висновування чи файлі моделі, тож це властивість збірки, а не фраза на сайті.","features.389cb06662bc":"У порівнянні з провідними DAW","features.1b20c8037295":"Freally Oscillate таким, яким він буде у версії 1.0, поруч із сімома комерційними продуктами в тому вигляді, в якому вони продаються на 1 жовтня 2026 року, — за їхніми власними сторінками продуктів, магазинами, посібниками й статтями підтримки. Ціни — прейскурантні, у доларах США.","features.dbdcc26cbc1a":"Freally Oscillate 1.0 і сім комерційних DAW, можливість за можливістю","features.0c4e9f0c201a":"Freally Oscillate 1.0","features.2088ae055e42":"FL Studio 2026","features.c2373bf58922":"Ableton Live 12","features.89d4cb070d7f":"Logic Pro","features.dec97310271f":"Bitwig Studio 6","features.41e8da85de51":"Cubase Pro 15","features.9a8405135cab":"Pro Tools","features.4da4dbb45aea":"Soundtrap","features.a6a1efe40897":"Ціна на 1 жовтня 2026 року, у доларах США","features.4ade5154bd22":"Сьогодні безкоштовно","features.20f8fb981865":"$99–$449, одноразово","features.566c95f474af":"$99–$749, одноразово","features.19be45f9b5eb":"$199.99 одноразово або $12.99 на місяць","features.5e5b2a65eaea":"$99–$399, одноразово","features.7113d664c5d8":"$579.99, одноразово","features.9a1ba45b0bfd":"Intro безкоштовно; $99–$599 на рік","features.385bc90ff4a3":"Безкоштовний тариф; $11.99–$20.99 на місяць","features.40cbef707220":"Працює в Windows, macOS і Linux","features.85a39ab345d6":"Так","features.deb0147a950c":"Частково","features.1abbc130b8d9":"Windows, macOS","features.1ea442a134b2":"Ні","features.3f2f41cd023d":"лише macOS","features.d48bbcde1043":"застосунки для Windows і macOS; Linux у браузері","features.3cb6a5ed0829":"Працює як хост для плагінів VST3","features.6bba86a6bb28":"лише Audio Units","features.7d13d66c4393":"лише AAX","features.0c8436827b99":"лише ефекти, на найвищому тарифі","features.dcbac1a42d75":"Працює як хост для плагінів CLAP","features.3592cc9add20":"Плагін, що впав, не зупиняє сесію","features.b37c33f4180d":"кожен плагін, завжди","features.4c8d11154068":"за бажанням, лише VST","features.2089380a1ba9":"на Apple silicon","features.151339072593":"Не перевірено","features.fc8d60587699":"Можна користуватися взагалі без облікового запису","features.b7d5af4a8c98":"Кілька продюсерів працюють в одній сесії одночасно","features.7e6677e2efad":"до чотирьох, наживо","features.ba260ef541c6":"запис одного віддаленого виконавця","features.c7514e6ebfe8":"доріжка за доріжкою, через хмару","features.36bd8f7a0c2d":"наживо, у своїй хмарі","features.956234fe74b6":"Вбудовані голос і камера для спілкування зі співавторами","features.62f1fa1162e0":"із цим виконавцем","features.c870c00fa541":"лише текстовий чат","features.9f3893904d3d":"Спільна робота без сервера й облікового запису посередині","features.b5db35f851fe":"напряму, від вузла до вузла","features.4c5f872abb2f":"Передати доріжку співавторові, а потім забрати її","features.f28162be8d9f":"володіння доріжкою, на запит","features.c3b01984557c":"Режим біт-батлу","features.1d662dd62590":"Спліт-шит, виведений з того, хто що редагував","features.e6195e7cff54":"Жодних функцій ШІ чи машинного навчання","features.f0774f2a34b1":"гарантовано складальною перевіркою","features.7a210d79eda9":"жодних не заявлено","features.e5498b8a441d":"<strong>Коротко:</strong> кожен інший продукт у цій таблиці вимагає облікового запису, і кожен просить грошей за повний набір можливостей. Два з них дають кільком людям редагувати один проєкт: Pro Tools — доріжка за доріжкою через свою хмару, Soundtrap — наживо у власній хмарі. Oscillate збирає чотирьох продюсерів в одному аранжуванні наживо, напряму один до одного, без облікового запису, і сьогодні він безкоштовний.","features.52242b315ce6":"Складено 1 жовтня 2026 року. «Ні» біля можливості означає, що її немає у власних списках можливостей, примітках до випусків чи посібнику цього продукту на ту дату. Продукти змінюються, і ця таблиця описує їх такими, якими вони були тоді. Назви продуктів — торговельні марки їхніх власників.","features.6977b748edc2":"Чому він побудований саме так","features.662d60837a2d":"Немає сервера — отже, нічого вимикати","features.85567c225aa3":"Код кімнати — це сама пропозиція з'єднання. Без сервера нічого підтримувати в роботі, нічого оплачувати й нічого, що хтось міг би вимкнути, — і саме тому в кімнаті вміщається четверо продюсерів, а не сорок: кожен учасник надсилає кожному.","features.16275f3a5af9":"Один журнал, чотири застосування","features.d2a4cd186952":"Кожна правка — операція в одному журналі. Скасування, синхронізація кімнати, Перемотування сесії та спліт-шит — чотири прочитання цього журналу, тому ваше скасування може бути лише вашим, а авторство можна вивести, а не вписувати вручну.","features.af0df7623348":"Збій — це один пристрій, а не вся сесія","features.600105cd00bc":"Кожен плагін у хості працює у власному процесі, а сам застосунок навіть не може його завантажити. Плагін, що впав, робить сірим свій пристрій, а транспорт грає далі.","features.908ec1ae94d2":"Число, яке ви бачите, — це число в звуці","features.b6fc9acbd76d":"Індикатори малюються з того, що видав рушій, значення на ручці — з величини, яку використовує DSP, а вимір, що не встигав, про це каже. Ніщо на екрані не є прогнозом.","features.944f018d9f74":"Усе лишається на вашій машині","features.70a55e97f377":"Ваші проєкти, звук і MIDI залишають ваш комп'ютер, лише коли ви з кимось у кімнаті, — і тоді вони йдуть напряму до її учасників, а не через чиюсь хмару.","features.bd873b549bc7":"Що ще попереду","features.735112899b1c":"Сказано прямо, бо список можливостей, який ховає свої прогалини, не варто читати. Усе, що вище, — це те, що заплановано для версії 1.0, а ось що ще стоїть між сьогоденням і нею.","features.d9d391384838":"Чого 1.0 робити не буде","features.7d48e18b39c1":"<strong>Працювати як хост для плагінів AU чи VST2.</strong> Він працює як хост для VST3 і CLAP.","features.a1eea7d00cdd":"<strong>Використовувати ASIO.</strong> У Windows шлях із низькою затримкою — монопольний режим WASAPI, і Oscillate каже, який режим ви насправді отримали.","features.1bcf2a5c1071":"<strong>Збирати в кімнаті понад чотирьох продюсерів.</strong> П'яте з'єднання — це місце, де звичайний домашній вихідний канал вичерпується.","features.37e6fd7fe6f5":"<strong>Ретранслювати з'єднання, яке інакше не встановиться.</strong> Приблизно одне з десяти не встановиться без ретранслятора посередині; Oscillate називає причину, а в Налаштуваннях можна вказати власний ретранслятор.","features.d32646eadd7e":"<strong>Демонструвати екран із macOS.</strong> Демонстрація екрана — лише Windows і Linux; у macOS кнопки немає, а замість неї пояснено чому.","features.5590fbf60cd6":"<strong>Передавати pitch bend, колесо модуляції чи тиск з апаратної клавіатури.</strong> Ноти, велосіті й педаль сустейну передаються.","features.3b50036d04c0":"На цій сторінці немає бети, немає попередньої збірки, немає раннього доступу. До 1.0.0 чесна відповідь на питання «де це взяти» — <em>поки ніде</em>.","docs.lede":"Посібник: кожна панель, кожен редактор, кімната, плагіни й обмеження.","docs.831d0f72d242":"Початок роботи","docs.365101815fb2":"Вікно та його панелі","docs.2e5511855cbc":"Аранжування","docs.dac11b27d868":"Piano roll","docs.a232ac37bd92":"Барабанна сітка","docs.d909750b1bbb":"Автоматизація","docs.a4592301df0c":"Запис і компінг","docs.bdb597b1232d":"Мікшер","docs.9514b7ff4860":"Плагіни","docs.c80fbc216c04":"Вбудовані пристрої","docs.4854ad4c206c":"Провідник файлів","docs.542aa51c9ff9":"Кімната","docs.ba5e0c669f84":"Куміте і спліт-шит","docs.787726eabc9d":"Доріжка тексту","docs.3664895579f0":"Експорт","docs.74a883a037bc":"Налаштування","docs.22e2bada8f1c":"Оновлення","docs.46e978d0c193":"Гарячі клавіші","docs.69bd78234ffb":"Приватність і мережа","docs.8e388ee7590d":"Обмеження, сказані прямо","docs.c3af076f92c5":"Усунення несправностей","docs.05df7711cd6c":"Oscillate встановлюється, як будь-яка інша настільна програма, і працює офлайн. Під час першого запуску вам покажуть угоду: її треба прийняти, перш ніж програма відкриється, а переглянути знову можна будь-коли в <strong>Налаштування ▸ Про програму ▸ Переглянути угоду</strong>.","docs.fb63caf27515":"Після цього ви опиняєтеся в сесії під назвою <em>Новий проєкт</em>. Нічого ніде не зберігається, доки ви не збережете, — крім журналу збоїв, який записує кожну зміну в ту мить, коли ви її робите, тож збій не коштує вам нічого, а не пів дня роботи.","docs.shot.start":"Вікно Oscillate під час першого запуску: ліворуч Провідник файлів, посередині аранжування, а внизу — елементи керування транспортом у червоній рамці.","docs.9edf9ef77c9f":"Вікно під час першого запуску. Смуга в рамці — це транспорт: відтворення, зупинка, запис, темп і метроном.","docs.a8522c985343":"Натисніть <kbd>Space</kbd>, щоб запустити й зупинити відтворення. Перетягніть звук із Провідника файлів на доріжку або двічі клацніть порожнє місце MIDI-доріжки, щоб створити кліп і почати писати.","docs.d5e9c2dcb12a":"Вікно не має рамки, і Oscillate сам малює кнопки згортання, розгортання й закриття. Чотири панелі вмикаються й вимикаються з рядка заголовка або клавішею:","docs.99a52df3ff3d":"Клавіша","docs.d0d91173008b":"Панель","docs.1f36becc3aa7":"Що це","docs.d6f6a04891cc":"Провідник файлів","docs.495763c88db7":"Ваші звуки, ваші плагіни й власні пристрої Oscillate — з попереднім прослуховуванням.","docs.936a161c3931":"Редактор","docs.05db484cdeb8":"Piano roll, барабанна сітка, автоматизація й редактор хвильової форми.","docs.8ae012d51747":"Мікшер","docs.f1972360c8eb":"Фейдери, індикатори рівня, Радар маскування й панель гучності.","docs.911ea89c43d9":"Кімната","docs.42546267e696":"Коди кімнат, список учасників, чат, голос, камери й демонстрація екрана.","docs.78b8c8386cc9":"На macOS кожен <kbd>Ctrl</kbd> нижче — це <kbd>Cmd</kbd>. Будь-яку панель можна витягти в окреме вікно, і воно працює й на другому моніторі.","docs.2ae2bf6b8884":"Щоб змінити розмір двох панелей, перетягніть роздільник між ними. Якщо ширина менша за 1280 пікселів, бічні панелі згортаються самі, бо аранжування стає непридатним раніше за них.","docs.226516acde25":"Стрічка часу з лінійкою тактів і долей, сітка, що підлаштовується під масштаб, заголовки доріжок збоку й кліпи, намальовані з того, чим вони є насправді: справжня хвильова форма для аудіо, справжні ноти для патерна.","docs.78d11d4d5db9":"Редагування кліпів","docs.0bfc00f5a7ca":"Перетягніть кліп, щоб перемістити його; утримуйте <kbd>Alt</kbd> під час перетягування, щоб скопіювати.","docs.bb5fc5708305":"Перетягніть будь-який край, щоб обрізати; перетягніть верхній кут, щоб зробити фейд.","docs.c379e75c7075":"Перетягніть ручку циклу на правому краї, щоб повторити кліп.","docs.196e45387bc2":"<kbd>Ctrl</kbd>+<kbd>Z</kbd> скасовує весь жест — скільки б кліпів він не зачепив, одним натисканням.","docs.65ca08c3ec91":"Розріз","docs.6cbcada86f4d":"Натисніть <kbd>B</kbd>, щоб узяти лезо, і проведіть штрих по аранжуванню. Кожен кліп, який перетне штрих, розрізається в місці перетину, а кут штриха задає довжину кросфейду: вертикальний штрих — різкий розріз, пологий — довге змішування. Натисніть <kbd>V</kbd>, щоб повернутися до вказівника.","docs.102bcc2b6fcb":"Перетворення кліпу на інший тип","docs.e6513c30872c":"Клацніть правою кнопкою MIDI-кліп і виберіть <strong>Відрендерити в аудіо</strong>; клацніть правою кнопкою аудіокліп і виберіть <strong>Перетворити на MIDI</strong>. В обох випадках результат з'являється <em>поряд</em> з оригіналом, а не поверх нього, і одне натискання скасування повертає все як було.","docs.04d699e071c9":"Патерн рендериться через усе, що стоїть на цій доріжці: інструмент у його слоті, а потім кожен аудіоефект після нього. Вимкненого пристрою в рендері немає. Власних фейдера й панорами доріжки там навмисно теж немає — новий кліп грає через них, тож запекти їх означало б застосувати їх двічі.","docs.8d98a4cb90a8":"Перетворення аудіо на MIDI неідеальне й чесно це визнає: воно каже, зі скількох ударів не вдалося прочитати висоту. Барабанний луп не перетворюється ні на що — і це чесна відповідь.","docs.33738bb248c5":"Двічі клацніть MIDI-кліп, щоб відкрити його. Малюйте ноти олівцем (<kbd>P</kbd>) або двічі клацайте в сітці. Клавіатура вздовж лівого краю грає інструментом доріжки, а одну клавішу можна налаштувати так, щоб вона грала цілий акорд.","docs.42a0052bf1b6":"Лади","docs.ddbef0217d41":"Близько дев'яноста ладів. Вибраний лад підсвічує свої ноти, а <kbd>Ctrl</kbd>+<kbd>K</kbd> переносить на нього все виділене. Згортання ховає кожен рядок, якого немає в ладі, і хроматична сітка стає читабельною.","docs.2cafc9e7c3b3":"Операції з нотами","docs.c74ea9dc9cd2":"Що робить","docs.0baf2bf51650":"Квантування — прив'язати виділені ноти до сітки","docs.ea07e2f557fe":"Олюднення — трохи зсунути їх із сітки назад","docs.0ab966bf90ea":"Легато — розтягнути кожну ноту до наступної","docs.6a31f294ca42":"Обернути порядок виділених нот","docs.4cde53316a6e":"Перенести їх у лад кліпу","docs.16aac93d1c5b":"Дублювати на місці","docs.6e14c1f152dd":"Дублювати після — звичайний спосіб будувати партію","docs.3acb04d66cdb":"Зсунути на одну поділку сітки","docs.22667e7b7cca":"Зсунути на півтон; із <kbd>Shift</kbd> — на октаву","docs.af2e3ba89e9f":"Доріжка велосіті під сіткою має ручку для кожної ноти. Примарні ноти з будь-якого іншого кліпу можна показати позаду того, який ви редагуєте, — так пишуть басову лінію під акордову партію, не перемикаючись туди й назад.","docs.27e0332d2463":"Той самий кліп, але з рядком на кожен барабан замість рядка на кожну висоту. Клацніть клітинку, щоб поставити удар, протягніть по клітинках, щоб заповнити їх, і перетягніть удар угору чи вниз у його рядку, щоб змінити велосіті. Усе з таблиці piano roll вище працює й тут — під ними ті самі ноти.","docs.2195edf6dd56":"Автоматизувати можна кожен фейдер, панораму й регулятор пристрою. Відкрийте доріжку автоматизації, виберіть ціль і малюйте. Точки прив'язуються до сітки; утримуйте <kbd>Alt</kbd>, щоб поставити точку вільно. Криву між двома точками можна вигнути, перетягнувши її середину.","docs.f82da0230788":"<strong>Ката</strong> — це форми автоматизації, які ви малюєте один раз і ставите де завгодно: наростання, розгортка фільтра, провал у формі сайдчейну, — тож вдалий жест можна використовувати знову, а не перемальовувати.","docs.1a01d11683c6":"Підготуйте доріжку до запису, натисніть запис, грайте. Аудіо записується на диск у міру надходження, а не тримається в пам'яті, тож збій коштує вам останнього блока, а не дубля.","docs.91afc456637e":"Запишіть ті самі такти ще раз — і отримаєте другий дубль під першим. Виберіть потрібні частини з кожного, і Oscillate збере комп. <strong>Дублі, які ви не вибрали, ніколи не видаляються</strong> — саме це й означають тіньові дублі, і тому передумати через тиждень нічого не коштує.","docs.cebcc1706c05":"Відлік налаштовується в <strong>Налаштування ▸ Запис</strong>. За замовчуванням його вимкнено.","docs.6904fda84081":"<kbd>Ctrl</kbd>+<kbd>3</kbd>. Лінійка на кожну доріжку з фейдером, панорамою, глушінням, соло, стійкою пристроїв та індикатором рівня, який малюється зі звуку, що його справді видав рушій, — ніколи не з прогнозу.","docs.8eaced166021":"Радар маскування","docs.bea60461bd8b":"Натисніть <strong>Радар</strong>, і Oscillate стежитиме за парами доріжок, що борються за ту саму смугу, — бас і бочка, вокал і пед, — і назве пару й частоту. Поки радар увімкнений, він навантажує процесор, і підказка про це каже.","docs.6f550e9b860d":"Пара, якої ще не було чути, показує <strong>Ще не почуто</strong>, а не «чисто». Якщо в сесії більше доріжок, ніж стежить радар, він теж про це каже, а не мовчки показує лише частину.","docs.e0b651a4ea3c":"Гучність та істинний пік","docs.5a27169c5088":"Натисніть <strong>Гучність</strong>, щоб побачити інтегровані LUFS, короткочасну гучність, діапазон та істинний пік, а також таблицю цільових рівнів кожного стримінгового сервісу й того, що він зробив би з вашим мастером. Кожна ціль має дату останньої перевірки.","docs.bfc4dfe30bdc":"Якщо вимірювач під навантаженням колись не встигав, він про це каже — <em>«вимірювач не встигав, тому частину звуку не було виміряно»</em>. Число без попередження поруч означає повний вимір.","docs.24653cacd405":"Oscillate працює як хост для <strong>VST3 і CLAP</strong>, і кожен плагін працює у власному процесі. Плагін, що впав, робить сірим лише свій пристрій, а сесія працює далі.","docs.4c2bf768921f":"Ваші плагіни з'являються в Провіднику файлів у розділі <em>Плагіни</em>. Перетягніть плагін на доріжку або виберіть доріжку й клацніть його. Власний редактор плагіна відкривається зі стійки пристроїв — це справжній інтерфейс, який ви купили, а не список повзунків, — і після закриття та повторного відкриття він повертається того самого розміру.","docs.657f210c6f73":"Компенсація затримки діє на весь граф і доведена нульовим тестом: той самий сигнал через пристрій, що повідомляє про затримку, і в обхід нього взаємно гаситься до тиші. Плагін, якого на цій машині немає, стає іменованою заглушкою, яка все одно вносить свою затримку в семплах, тож проєкт, відкритий деінде, лишається в часі.","docs.fe9d907d6c9f":"Разом з Oscillate постачаються шістдесят дев'ять інструментів та ефектів, зокрема <strong>Freally Secretarium</strong>. Кожна панель малюється з власного опису пристрою, тож значення на ручці — це те число, яке використовує DSP, а не інше, яке здебільшого з ним збігається.","docs.57ba00ce7687":"Дисплеї","docs.4ce795582ea6":"Пристрій показує, що він робить, а не лише як його налаштовано: компресор малює своє зниження підсилення, еквалайзер — свою характеристику, стереопристрій — своє стереополе.","docs.5396457a7321":"<strong>Деякі дисплеї навмисно порожні.</strong> Передавальна крива, спектр і осцилограф потребують виміру, якого ще немає, а намалювати правдоподібну форму з регуляторів означало б намалювати ніщо. Вони лишатимуться порожніми, доки вимір не стане справжнім.","docs.6a4181898f49":"Рядки-рецепти","docs.3c86c1f5f519":"Налаштування пристрою копіюються одним рядком, який можна вставити в чат. Цілу стійку — вбудовані пристрої разом із плагінами в хості — можна зберегти як файл і відновити на будь-якій доріжці за один крок скасування, навіть на машині, де бракує одного з її плагінів.","docs.afc35db2da83":"Пристрої, що читають аранжування","docs.6a537022e329":"Шість із них роблять те, чого не може жоден плагін, бо плагін не бачить аранжування, всередині якого стоїть. Компресор, що вже тримає приспів, коли той починається; гейт, що відкривається для удару, про який знає за два такти наперед; дилей, що спорожняється <em>до</em> тактової риски, тож хвіст згасає, а не обривається. Читати аудіо на два такти вперед — це затримка, і платять за неї всі; читати структуру не коштує нічого, і всі вони оголошують нульову затримку.","docs.0d2dfd82f8ee":"<kbd>Ctrl</kbd>+<kbd>1</kbd>. Головний екран із розділами — <em>Інструменти</em>, <em>Аудіоефекти</em>, <em>MIDI-ефекти</em>, <em>Плагіни</em>, — у які можна заходити, кнопка <strong>Вибрати теку</strong> і додані вами теки, перелічені за назвою.","docs.efab24503279":"Фільтр шукає не лише за назвою пристрою, а й за тим, чим він <em>є</em>, тож якщо ввести <code>compressor</code>, знайдеться <code>Vise</code>.","docs.00254cbab0ed":"Попереднє прослуховування","docs.3475ee704644":"Клацніть пристрій — і почуєте його власну демонстрацію (нота й тривалість підібрані для кожного інструмента) з хвильовою формою, курсором відтворення, циклом і клавішами <kbd>←</kbd>/<kbd>→</kbd>, щоб переходити назад чи вперед. Укажіть власну теку — і так само прослуховуватимете свої семпли. П'ять інструментів — семплери, і вони так і кажуть, а не грають тишу: вони не звучать, доки ви не завантажите файл.","docs.5a8b10fcbead":"Перетягування файлу","docs.b40583c5f830":"Перетягніть <code>.wav</code> або <code>.mid</code> просто з Провідника Windows чи Finder на такт в аранжуванні — і файл ляже <strong>туди, куди ви його кинули</strong>. MIDI потрапляє на MIDI-доріжки, аудіо — на аудіодоріжки, а невідповідний тип відхиляється з поясненням, а не отримує окрему доріжку.","docs.5d740606fafb":"Перетягнутий файл <strong>копіюється в проєкт</strong>, а не підключається за посиланням. Киньте щось із тимчасової теки, видаліть оригінал — і кліп однаково гратиме.","docs.f735a1d5bc49":"<kbd>Ctrl</kbd>+<kbd>4</kbd>. Натисніть <strong>Створити код кімнати</strong>, дочекайтеся коду й надішліть його тому, з ким працюєте. Ваш співрозмовник вставляє його й надсилає вам свій, ви вставляєте той у <strong>Впустити</strong> — і ви в одній сесії.","docs.shot.room":"Панель «Кімната»: кнопка «Створити код кімнати» в червоній рамці з номером 1 і кнопка «Впустити» — куди вставляють код, який вам надіслали, — у рамці з номером 2.","docs.0548c5c7cd35":"1 створює ваш код. 2 — місце для їхнього коду. ⚠ Щойно код з'явився, найважливіше — речення поруч із ним: ставтеся до коду як до пароля, бо він містить публічну адресу вашого комп'ютера.","docs.41a1acbef296":"Що ви отримуєте","docs.4e795a73e99f":"Список учасників, у кожного свій колір, і їхні курсори, що рухаються вашим аранжуванням.","docs.e2168f0fe102":"Чат. Він живе, доки існує кімната, і нічого не записується на диск.","docs.83623938eb6f":"Голос, плитки камер і демонстрація екрана — усе вимкнено, доки ви щось не натиснете.","docs.5161add1f5a4":"<strong>Ваше скасування — тільки ваше.</strong> <kbd>Ctrl</kbd>+<kbd>Z</kbd> скасовує вашу останню зміну й ніколи чужу, навіть поки надходять чужі правки.","docs.ab67452f2acf":"<strong>Передавання</strong> — віддайте одну доріжку комусь і заберіть її однією клавішею. Поки доріжка в нього, лише він може її змінювати — навіть ви ні.","docs.6a62a97df77a":"Що ніколи не передається","docs.c61d0ae17869":"<strong>Записаний вами дубль передається. Куплений вами семпл — ніколи.</strong> Коли хтось приєднується до сесії, де використано семпл-пак, якого в нього немає, він отримує список під назвою <em>Семпли, яких вам бракує</em> і пояснення: Oscillate ніколи не пересилає семпли між комп'ютерами. Побайтові копії — це те, що породжує піратство, і цей продукт не стане для нього шляхом.","docs.0cce48095d62":"Коли не вдається з'єднатися","docs.7a85d27236d6":"Приблизно одне з'єднання з десяти не встановиться, і Oscillate називає, яка з дев'яти причин це була, — від <em>мережу не знайдено</em> до <em>ваша мережа дає кожному серверу іншу адресу</em>. Для останньої потрібен ретранслятор посередині; поле для власного є в <strong>Налаштування ▸ Спільна робота</strong>.","docs.3dddae9cbb86":"<strong>Куміте</strong> — режим біт-батлу, у якому кожен хід володіє власними тактами. Зворотний відлік — це лише відлік, а правило — такти, тож два комп'ютери ніколи не розійдуться в тому, чия правка була законною.","docs.aa8f79385db8":"<strong>Спліт-шит</strong> показує, хто що написав: його виведено з журналу правок, а роботу, яку хтось скасував, вирахувано. Це відправна точка для розмови про авторство, а не юридичний документ, і він прямо про це каже.","docs.9129cdbc7eff":"Виберіть вокальну доріжку й натисніть <strong>Текст пісні</strong>. З'явиться доріжка зі словами, прив'язана до курсора відтворення. Додавайте рядки, зсувайте рядок на такт раніше чи пізніше, розбивайте рядок на склади й прив'язуйте записаний дубль до слів, яким він належить.","docs.64413b5bc744":"Імпортуйте файл <code>.txt</code> або <code>.lrc</code>, і слова <strong>скопіюються в проєкт</strong> — перемістіть потім файл, і слова все одно лишаться.","docs.f935e3c9c7fe":"Шрифт розрахований на те, щоб співати з іншого кінця кімнати, а не читати, нахилившись до екрана. Кожна правка тексту — це операція, тож <kbd>Ctrl</kbd>+<kbd>Z</kbd> скасовує її, як і все інше.","docs.b3307da67465":"<strong>Файл ▸ Експортувати супровідну теку…</strong> записує стеми й MIDI, які відкриє будь-яка інша DAW. Стеми вирівняно по такту 1, тож імпорт деінде не означає підсовувати на місце тридцять файлів.","docs.271287d739a7":"Формат, частота дискретизації, розрядність, дизеринг і місце збереження — у <strong>Налаштування ▸ Експорт</strong>.","docs.1419f63cf3ba":"<strong>Картки сесій.</strong> <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>C</kbd> або <strong>Файл ▸ Картка сесії…</strong> рендерить зображення сесії 1200×630 для публікації — темп, тональність, кількість доріжок і кліпів, тривалість і форму аранжування. Код кімнати туди потрапити не може: він займає кілобайти й містить вашу публічну адресу, тож такий параметр є, але вимкнений, і пояснює чому.","docs.5371ad5444f6":"<kbd>Ctrl</kbd>+<kbd>,</kbd>. Кожна зміна застосовується одразу й зберігається для цієї машини. Кнопки <em>Застосувати</em> немає, бо діалог налаштувань із нею — це діалог, який може помилятися щодо того, що зараз діє.","docs.bc1b88907d3b":"Звук","docs.40710b1c4ea7":"Виберіть вихід і те, скільки пристрою зайняти. У Windows можна попросити <strong>Монопольний</strong> режим — він дає найменшу затримку, на яку здатне обладнання, і глушить усі інші програми. Oscillate каже, <strong>який режим ви насправді отримали і чому</strong>: або <em>потік відкрито монопольно</em>, або <em>ця машина не відкрила монопольний потік, пристрій лишається спільним</em>. Ніколи жодного мовчазного пониження.","docs.dfe87d5e5bba":"Оформлення й мова","docs.74a5371eede6":"Обидві теми, вісімнадцять мов, і ваш вибір під час наступного запуску переважає вибір системи. Письмо справа наліво — справжнє, а не просто вирівнювання тексту.","docs.56205fc54fb3":"<strong>Налаштування ▸ Оновлення.</strong> Oscillate шукає оновлення <strong>лише</strong> тоді, коли ви натискаєте <em>Перевірити оновлення</em>, або під час запуску, якщо ви це ввімкнули, — а це <strong>типово вимкнено</strong>.","docs.shot.updates":"Налаштування з вибраним розділом «Оновлення»: кнопка «Перевірити оновлення» в червоній рамці з номером 1 і перемикач «Перевіряти під час запуску Oscillate» у рамці з номером 2, у вимкненому положенні.","docs.983c1169fe58":"1 перевіряє один раз, зараз. 2 — перевірка під час запуску, і вона вимкнена, доки ви її не ввімкнете. Панель показує точну адресу, до якої було б звернення, і коли звернення востаннє справді відбулося.","docs.3ce9192c8c94":"Перевірка запитує один статичний файл і нічого не надсилає ні про вас, ні про цю машину, ні про ваші проєкти. Коли оновлення знайдено, вам показують версію, дату, список змін і розмір, і вибір за вами. Кожен артефакт підписано; артефакт, підпис якого не проходить перевірку, відхиляється з помилкою, а не встановлюється.","docs.eb0eedb56328":"Якщо перевірку під час запуску вимкнено, жодних звернень немає, і панель не показує жодного результату — <em>Остання перевірка</em> лишається <em>Ніколи</em>. Вона ніколи не пише «у вас остання версія» про перевірку, якої не було, бо це різні факти й правдивим був би лише один.","docs.855dbb09047b":"Кожну з них можна змінити в <strong>Налаштування ▸ Клавіатурні скорочення</strong>, а вже зайнята комбінація каже, якій дії вона належить. На macOS читайте <kbd>Ctrl</kbd> як <kbd>Cmd</kbd>.","docs.456bb0100878":"Комбінація","docs.64cff1319d2f":"Дія","docs.a78afaff2fda":"Відтворити або призупинити","docs.a41eb2bf7245":"Новий проєкт","docs.c4c61e4f9081":"Відкрити проєкт","docs.1509f561f241":"Зберегти","docs.60af8a30e5e6":"Зберегти як","docs.c0d170d865e7":"Скасувати — завжди лише ваше","docs.74273989b096":"Повторити","docs.26c31b40dc4c":"Картка сесії","docs.e91f3b2dc496":"Показати або сховати Провідник файлів","docs.3f21190f1ed3":"Перемкнути центр між аранжуванням і реком патернів","docs.56f9e52baa67":"Показати або сховати панель — Редактор, Мікшер, Кімната","docs.0bb673ee3069":"Лезо / вказівник","docs.998aaff2fcf7":"Режим малювання (олівець)","docs.63195e7ab017":"Такт 1 / кінець аранжування","docs.308ea67cd57c":"Виділити все","docs.ef8b2814c03b":"Зняти виділення","docs.3eea5fab03b2":"Видалити виділене","docs.324d77bb489d":"Квантувати","docs.caa2871b6c07":"Олюднити","docs.c9b32288f886":"Легато","docs.2e5b4c5eaf16":"Обернути ноти","docs.349dbacd897e":"Перенести ноти в лад","docs.dee3dab5b567":"Дублювати після","docs.a5239b85e5fb":"Зсунути","docs.f87e04909851":"На півтон; із <kbd>Shift</kbd> — на октаву","docs.715210114589":"Згорнути piano roll до ладу","docs.71d26d2e1ebf":"Примарні ноти — решта патерна позаду цих","docs.c4b80c8b8af1":"Доріжка велосіті","docs.6bea7121b291":"Доріжка ймовірності — як часто звучить кожна нота","docs.12beabce3af4":"Доріжка розкиду сили — наскільки далеко відхиляється кожна нота","docs.72f1e2b86c3c":"Oscillate не потребує облікового запису, не збирає телеметрію й ніколи нікуди не надсилає ваші проєкти, ваш звук чи будь-що про вас або вашу машину. Запис, редагування, генерація, відтворення, зведення й експорт відбуваються повністю локально.","docs.ac2de81c2bb6":"Мережу він використовує рівно в трьох випадках:","docs.7b291aa666a0":"<strong>Сесія спільної роботи, яку ви відкрили або до якої приєдналися.</strong> Напряму до інших її учасників, від вузла до вузла, без сервера посередині.","docs.19e4e946fae3":"<strong>Запит STUN</strong> — лише поки кімната встановлюється, щоб дізнатися вашу публічну адресу. Сервер, до якого відбувається звернення, показано в Налаштуваннях, і його можна замінити власним — або зовсім вимкнути, і тоді кімната ні до кого не звертається.","docs.e19cbd5438b8":"<strong>Перевірка оновлень</strong> — лише коли ви натискаєте кнопку або вмикаєте перевірку під час запуску. Типово вимкнено. Див. <a href=\"#updates\">Оновлення</a>.","docs.0d97a43de208":"Це гарантує складальна перевірка, а не обіцянка: жоден HTTP-клієнт не досяжний із жодної частини Oscillate, крім названих вище компонентів спільної роботи й оновлення, і перевірка доводить це обходом графа залежностей, а не пошуком назв. Звіти про збої записуються на ваш диск, показуються вам повністю й залишають машину, лише якщо ви вирішите надіслати звіт.","docs.c474edeb7ac4":"<strong>Четверо продюсерів у кімнаті</strong>, бо кожен учасник надсилає кожному, і п'яте з'єднання — це місце, де звичайний домашній вихідний канал вичерпується.","docs.d92b90c2dcd3":"<strong>Приблизно одне з'єднання з десяти не встановиться</strong> без ретранслятора, а Oscillate його не постачає — ретранслятор назавжди коштує трафіку, а це постійний рахунок, якого безкоштовній програмі не потягнути.","docs.97cfbf95503a":"<strong>Той, хто приєднується, не отримує ваш проєкт.</strong> Щоб правки означали те саме, обидві машини мають спершу відкрити той самий файл.","docs.12e311704eeb":"<strong>Семпли ніколи не передаються мережею.</strong> Записаний вами дубль — передається; куплений семпл — ні.","docs.c281636fd984":"<strong>Шість пристроїв названо й показано сірими без регуляторів</strong>, кожен — із записаною причиною, а не з байдужим знизуванням плечима. Аналізатор і графік зниження підсилення не працюють наживо.","docs.1c94409d901d":"<strong>Семплер поки не можна відрендерити в аудіо.</strong> Перетворення патерна на доріжці семплера відхиляється з прямим поясненням, а не повертається тишею.","docs.9596113825be":"<strong>Демонстрація екрана — лише Windows і Linux.</strong> У macOS немає способу захопити екран із вбудованого webview, який не потребував би приватного API в нотаризованому бінарнику, тож кнопки там немає, а замість неї пояснено чому.","docs.00cc76804476":"<strong>Учасник, що відпав, поки не визначається.</strong> Якщо в когось зникає мережа, список учасників і далі його показує.","docs.c8fe28a31074":"Немає звуку","docs.90409e8554a3":"Спершу перевірте <strong>Налаштування ▸ Звук</strong>: пристрій і режим, який ви насправді отримали. Якщо інша програма тримає аудіоінтерфейс у монопольному режимі, Oscillate не може його відкрити й каже про це. Доріжка, яка мовчить, коли інші звучать, зазвичай заглушена соло на іншій доріжці, заглушена сама або має порожній слот інструмента.","docs.15d94cccd4a0":"Плагін не з'являється","docs.b2298073a265":"<strong>Налаштування ▸ Плагіни</strong> показують теки, що скануються, і що в них знайдено. Плагін, який не вдалося завантажити, позначено як заблокований із причиною, і його можна розблокувати, щоб спробувати знову. Oscillate працює як хост для VST3 і CLAP; VST2 і AU він не підтримує.","docs.2ac89ed8e9e1":"Кімната не з'єднується","docs.dde8792e71cd":"Прочитайте причину, яку вона називає, — їх дев'ять, і це різні проблеми. <em>Ваша мережа дає кожному серверу іншу адресу</em> означає, що потрібен ретранслятор, а його вказують у <strong>Налаштування ▸ Спільна робота</strong>. Перевірте, що вставили код повністю: коди довгі, і чат-клієнт, який переніс код на новий рядок, його зламав.","docs.79993d75b6ac":"Щось упало","docs.f6ceafb1fe98":"Звіт автоматично записується на вашу машину. <strong>Налаштування ▸ Загальні</strong> називають найсвіжіший і відкривають теку. Звіт містить версію, операційну систему, аудіопристрій і список плагінів за назвами — ніколи ваш проєкт, ніколи шлях із вашого диска, ніколи код кімнати. Він залишає ваш комп'ютер, лише якщо ви вирішите його надіслати.","docs.9031c748abd6":"Панель спорожніла, але музика грає далі","docs.0f28d0790cf5":"Це інша несправність, ніж збій, і саме про неї більшість людей не повідомляє. Аудіопотік не виконує жодного коду інтерфейсу, тож відтворення триває, а ваш проєкт цілий. Звіт однаково записано; Налаштування його назвуть.","kit.skip":"Перейти до вмісту","kit.nav.site":"Сайт","kit.nav.home":"Головна","kit.nav.features":"Можливості","kit.nav.documentation":"Документація","kit.nav.changelog":"Журнал змін","kit.nav.language":"Мова","kit.nav.allApps":"Усі застосунки Freally","kit.badge.progress":"v0.5.5 готова · далі v0.6.0","kit.cta.features":"Усі можливості","kit.cta.docs":"Читати документацію","kit.price":"Freally Oscillate зараз безкоштовний, але може не залишитися безкоштовним назавжди: майбутні версії можуть продаватися.","kit.noDownloads":"Завантажень поки немає, а вихідний код закритий.","kit.label.overview":"Огляд","kit.label.inside":"Усередині","kit.label.roadmap":"Дорожня карта","kit.ladder.done":"Готово","kit.ladder.planned":"Заплановано","kit.ladder.goal":"Мета","kit.label.honesty":"Чесно","kit.family.label":"Родина Freally","kit.family.title":"<span class=\"hl-muted\">Одна родина.</span> <span class=\"hl-bright\">Вісім застосунків.</span>","kit.cta.label":"Що змінилося","kit.cta.title":"<span class=\"hl-muted\">Кожна версія</span> <span class=\"hl-bright\">записана.</span>","kit.cta.lede":"У журналі змін перелічено все, що змінювалося в Freally Oscillate, версія за версією, усіма вісімнадцятьма мовами.","kit.cta.changelog":"Читати журнал змін","kit.footer.thisApp":"Цей застосунок","kit.footer.family":"Родина Freally","kit.status.devVersion":"У розробці · v0.5.5","kit.head.features":"<span class=\"hl-muted\">Усе, що воно вміє,</span> <span class=\"hl-bright\">у порівнянні.</span>","kit.label.numbers":"У цифрах","kit.label.free":"Зараз безкоштовно","kit.label.compare":"Порівняння","kit.label.principles":"Принципи","kit.label.limits":"Обмеження","kit.states.title":"Що означають стани","kit.states.done":"зібрана й позначена тегом, але не завантажується з цього сайту","kit.states.planned":"ще треба зробити","kit.states.goal":"версія, до якої веде цей шлях","kit.states.ladder":"Переглянути всі щаблі шляху","kit.head.documentation":"<span class=\"hl-muted\">Як це працює,</span> <span class=\"hl-bright\">крок за кроком.</span>","kit.search.placeholder":"Пошук у документації","kit.docs.contents":"Зміст","kit.head.changelog":"<span class=\"hl-muted\">Кожна зміна,</span> <span class=\"hl-bright\">версія за версією.</span>","kit.changelog.lede":"Спочатку нове: усе, що змінювалося в Freally Oscillate, кожною мовою цього сайту.","kit.changelog.versions":"Версії","kit.search.none":"На цьому сайті немає нічого, що відповідає запиту.","changelog.7ba875906742":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0-rc</span><time class=\"release__date\" datetime=\"2026-09-25\">2026-09-25</time></span>","changelog.508d2f7ec832":"<strong>Огляд реліз-кандидата 24–25 вересня 2026 року</strong> — нагорі: одна нова функція, дефекти, які знайшов огляд, і те, що тепер звучить інакше у збереженому проєкті. Нижче — виправлення від 19 вересня, далі <strong>механіка бети</strong> (фаза 11), потім <strong>обличчя, голоси, ходи й авторство</strong> (фаза 9.5), потім <strong>кімната</strong> (фаза 9), потім <strong>інструменти для написання</strong> (фаза 8), <strong>власні пристрої Oscillate</strong> (фаза 7), <strong>хостинг плагінів</strong> (фаза 6), <strong>редактори</strong> (фаза 5) і <strong>вигляд аранжування та проєкт під ним</strong> (фази 3 і 4, увесь щабель <code>v0.2.0</code>).","changelog.7a5d4f56ddd0":"Додано — апаратна MIDI-клавіатура грає і записує","changelog.e63d48df6d81":"⛔⛔ <strong>Досі ніщо в Oscillate жодного разу не відкривало MIDI-порт.</strong> Код драйвера був зібраний і протестований, але ніщо його не викликало, тоді як README, дорожня карта й сценарій першого запуску в один голос казали <em>«зіграй на MIDI-клавіатурі → звук»</em>, а Налаштування ▸ MIDI повідомляли, що цієї функції ще немає. Тепер вона є.","changelog.dcc8ae17c873":"<strong>Налаштування ▸ MIDI показують ваші входи. Виберіть один</strong> — і він грає на доріжці, підготовленій до запису, точно так само, як екранна клавіатура, і так само записує в дублі. Коли надходять ноти, світиться крапка, а якщо жодну доріжку не підготовлено до запису, розділ про це каже.","changelog.fdebbbb5e13c":"<strong>Що передається:</strong> ноти з їхньою велосіті, педаль сустейну та повідомлення паніки (<em>All Notes Off</em> і <em>All Sound Off</em>), тож кнопка паніки на клавіатурі зупиняє все.","changelog.fe2865a6e325":"⚠ <strong>Педаль утримує Oscillate, а не інструмент.</strong> Жоден інструмент тут не читає педаль, тож Oscillate затримує note-off, доки педаль не відпущено. Це однаково працює з будь-яким інструментом, а записаний дубль зберігає кожну ноту такою довгою, якою вона звучала, а не лише доки клавіша була натиснута.","changelog.c6abb9b19ac3":"⛔ <strong>Поки не передається — і не імітується:</strong> пітч-бенд, колесо модуляції та інші контролери, канальний тиск, поліфонічний афтертач і зміна програми. Інструменти вміють приймати бенд і тиск, а живий шлях від клавіатури до них — поки ні. Пітч-бенд, колесо модуляції й тиск з'являться після 1.0.","changelog.f17d5e0822ce":"<strong>Від'єднайте її посеред ноти — і нота зупиниться.</strong> MIDI-бібліотека не повідомляє про під'єднання чи від'єднання, тож, поки порт вибрано, Oscillate перевіряє раз на секунду: клавіатура, що зникла, відпускає всі ноти, які утримувала, а розділ показує <em>не під'єднано</em>. Під'єднайте її знову — і вона перепід'єднається за назвою.","changelog.4e160f9c55ef":"<strong>Вибір запам'ятовується</strong> в <code>midi.json</code>, поряд з <code>audio.json</code>, а порт знову відкривається під час запуску, ще до появи вікна. Якщо під час запуску клавіатуру не під'єднано, Oscillate відкривається як звичайно й повідомляє про це.","changelog.315f68af9cc8":"<strong>Порт, який утримує інша програма, так і каже</strong> — <em>не вдалося відкрити</em> — із власною причиною драйвера, і під'єднується, щойно порт звільниться.","changelog.34f38d764f89":"⚠ <strong>Відоме обмеження:</strong> якщо від'єднати й знову під'єднати клавіатуру в межах однієї секундної перевірки, порт може показувати <em>під'єднано</em>, хоча нічого не звучить. Повторний вибір порту це виправляє.","changelog.942c6cb85fad":"<strong>Два дефекти екранної клавіатури, виправлені попутно</strong>, бо обидва види клавіатури тепер ідуть одним шляхом:","changelog.d2f0b8c7936a":"<strong>Якщо підготувати до запису іншу доріжку, утримуючи клавішу, відпускання надходило на нову доріжку</strong>, тож нота на старій звучала, доки Oscillate не перезапускали. Тепер нота відпускається на тій доріжці, де її зіграли.","changelog.7634f305d478":"***All notes off<em> очищало всю чергу нот</em>*, викидаючи разом із нею й відкладені відпускання нот іншої клавіатури.","changelog.19562cee5d4a":"Виправлено — огляд реліз-кандидата","changelog.9705daf96914":"▶ <strong><code>/simplify</code>, <code>/code-review</code> і <code>/security-review</code> ще раз по всьому дереву, а потім близько дюжини проходів виправлень.</strong> Виправлено сотні дефектів, кожен — із тестом, який спершу бачили червоним, де це дозволяли інструменти. Найгірші — першими. <em>Змінено</em>, нижче, перелічує, що тепер звучить або поводиться інакше в уже наявному проєкті.","changelog.9cfb8a7fe85a":"<strong>Найгірше</strong>","changelog.c3b3b0310b60":"⛔⛔ <strong>У встановлюваній програмі кліпи аранжування, MIDI-кліпи й автоматизація ніколи не доходили до рушія — і так було від 27 серпня.</strong> <code>main.rs</code> викликав <code>Builder::setup</code> з Tauri двічі, а другий виклик <strong>замінює</strong> перший, а не доповнює його. Перший запускав потік відтворення, Радар маскування та вимірювач гучності, тож жоден із трьох не працював. Усі тести проходили, бо жоден тест не запускав builder. Тепер setup один, а перевірка (<code>the_builder_has_one_setup.rs</code>) відхиляє другий.","changelog.57f0db8ea734":"⛔⛔ <strong>Кожен експорт відтворював лише ноти на самому початку пісні.</strong> Офлайн-рендер ніколи не рухав власний транспорт. Експорт у супровідну теку ніс ноти на першому тіку без note-off, із застиглою автоматизацією гучності та синхронізованими з темпом пристроями, що працювали на 120. Тепер експорт відтворює всю пісню з її картою темпу та автоматизацією гучності, а аудіокліпи більше не обриваються посередині.","changelog.88021b53a47d":"⛔⛔ <strong>Після повторного відкриття проєкту всі плагіни VST 3 і CLAP мовчали, а власні налаштування плагіна взагалі ніколи не зберігалися.</strong> Плагіни в хості завантажувалися, лише коли ви додавали плагін або відкривали його вікно. Тепер вони завантажуються після кожного відкриття, скасування, повтору, завантаження пресета ланцюжка й оновлення від учасника. Стан кожного плагіна фіксується перед кожним збереженням і відновлюється, коли проєкт відкривається.","changelog.cc2f0645818b":"⛔ <strong>Ефекти перезапускалися п'ятдесят разів на секунду, поки працював транспорт.</strong> Потік відтворення перебудовував увесь план рендерингу кожні 20 мс, незалежно від того, чи щось змінилося, і кожна перебудова скидала всі вбудовані пристрої. Хвости реверберації обривалися, компресори починали спочатку, утримувані голоси зникали, а кожен пристрій плавно повертався від своїх типових налаштувань. Тепер план перебудовується, лише коли в ньому щось змінилося, а перебудова переносить працюючі пристрої, замість того щоб їх замінювати.","changelog.b8a809519ca1":"⛔ <strong>Ділянка циклу ніколи не зациклювалася.</strong> Лінійка її малювала, проєкт її зберігав, але транспорту ніхто про неї не казав. Тепер відтворення повертається на початок у кінці циклу, а звук кліпів більше не заходить за кінець циклу, щоб потім прозвучати із запізненням.","changelog.8e4359696cb2":"⛔ <strong>Скасування, повтор, відкриття проєкту й правка учасника не перемальовували інші вікна.</strong> Piano roll, аудіоредактор, відкрита панель пристрою і кожне відокремлене вікно й далі показували попередній стан, а друга обрізка, обчислена із застарілого вигляду, могла перезаписати першу. Тепер кожна зміна зсуває один лічильник, який слухають усі вікна.","changelog.991a518ad40a":"⛔ <strong>Після Файл ▸ Відкрити пропозиція відновлення після збою так і не з'являлася, а наступне збереження видаляло журнал, який вона мала б запропонувати.</strong> Тепер її пропонують щоразу, коли відкривається проєкт, а збереження тримає журнал, доки ви не відповісте.","changelog.72fcf1110d6e":"⛔ <strong>Діри в безпеці</strong> — далі.","changelog.bbc74b04e065":"<strong>Безпека</strong>","changelog.1b1ab848b297":"<strong>Жива правка учасника могла вказати на файл на вашому комп'ютері</strong>, і Oscillate його відкривав. Знімки від учасника очищувалися на вході, а окремі правки — ні. Тепер із кожної вхідної правки вилучаються шляхи до файлів і стан плагінів — точно так, як завжди робилося з вихідними.","changelog.db067cb38cfa":"<strong>Мережевий шлях у файлі проєкту чи в правці учасника міг видати хеш вашого входу у Windows</strong>, коли ви відкривали кімнату або читали дубль, бо Windows сама входить на мережевий ресурс. Тепер кожен читач <strong>до</strong> будь-якого звернення до файлової системи перевіряє, що шлях веде до файлу на локальному диску, а мережеві ресурси й шляхи пристроїв відхиляє одразу.","changelog.a26ae554ba1a":"<strong>Учасник кімнати міг привласнити особу іншого учасника</strong>, переславши пропозицію з'єднання від його імені, — а з нею його авторство, передані йому доріжки та його такти в Куміте. Тепер це відхиляється на сторінці й ще раз у процесі кімнати.","changelog.2819dc6c2317":"<strong>Відкритий проєкт або знімок від учасника потрапляли в аудіопотік без перевірки.</strong> Значення автоматизації 1000 давало +60 дБ, а підсилення 1000 дБ ставало нескінченністю. Тепер обидва перевіряються на вході. Пошкодження, які не можна виправити, відхиляються, числа поза діапазоном обмежуються, а вам повідомляють, що змінено.","changelog.52903827c85e":"<strong>Тепер кожен учасник представляється напряму</strong>, щойно відкривається з'єднання, — саме це дає змогу батлу розсадити всіх. Це представлення прив'язує з'єднання один раз, ніколи його не перейменовує і не може заявити про когось, від імені кого вже говорить інше з'єднання.","changelog.caedde91f452":"<strong>Pull request із форку більше не запускається на власній машині збирання під Windows</strong>, на якій зберігається ключ підпису оновлювача.","changelog.bb6bf121bbd4":"<strong>Відтворення і рушій</strong>","changelog.b8040300e667":"<strong>Завислі ноти після зупинки, стрибка курсора відтворення і на повороті циклу.</strong> Тепер у кожному з цих випадків відпускаються всі ноти, а барабанна доріжка, заглушена під час звучання ноти, більше не лишає її утримуваною.","changelog.60710aea2474":"<strong>Власна затримка нотного пристрою не компенсувалася</strong>, тож партія, що проходила через Tread, звучала із запізненням саме на цю затримку.","changelog.af5806634af3":"<strong>Курсор відтворення розходився зі звуком на плавній зміні темпу</strong>, яку обчислювали на один сегмент пізніше. Коротке переміщення курсора зсувало курсор, а звук лишало на місці.","changelog.6c68d7fa128a":"<strong>Кліпи зі зміненою висотою клацали</strong> там, де файл читався частинами. <strong>Реверсовані кліпи заїкалися</strong> за кінцем свого файлу. Згасання неправильно вимірювалося через зміну темпу. Обрізка перед тактом 1 або на кліпі зі зміненою висотою читала не ту частину файлу, а хвіст розрізаного кліпу читався з початку дубля.","changelog.6187aee593ac":"<strong>Повторно використаний слот мікшера відтворював залишки попередньої доріжки.</strong>","changelog.7f42837dfb17":"<strong>Індикатори рівня й гучність читали лише лівий канал.</strong> Доріжка, повністю панорамована праворуч, не показувала нічого, а показники гучності ігнорували правий бік. Тепер вимірюються обидва.","changelog.75dc4a3bc8cb":"<strong>Денормалізовані числа тепер обнуляються</strong> в потоках, що рендерять, наживо й офлайн, тож довге згасання до тиші більше не може спричинити стрибок навантаження на процесор. ⚠ Для цього знадобилося одне нове місце <code>unsafe</code> — <code>denormal.rs</code>, — переглянуте й схвалене власником; його перелічено в <code>SECURITY.md</code>.","changelog.3b1cc767fb75":"<strong>Друге прослуховування могло початися з середини або не початися зовсім.</strong>","changelog.2e44dc9f2c04":"<strong>Експорт</strong>","changelog.aa4e4757d0fd":"<strong>Заглушені доріжки просочувалися в мастер-мікс.</strong>","changelog.dca6958b82dc":"<strong>Після видалення чи перестановки доріжки експортовані партії потрапляли не в ті канали.</strong>","changelog.0c77d58d7aa5":"<strong>Експорт заважав живому відтворенню.</strong> Він використовував аудіопотоки самої сесії, тож у стеми міг потрапити живий звук, а відтворення потім починалося не з того місця. Тепер експорт рендерить із власних потоків.","changelog.927038d08ab5":"<strong>Вибрана частота дискретизації ігнорувалася.</strong> Усе рендерилося й записувалося на 48 кГц; тепер рендер іде на вибраній частоті.","changelog.7a5894bfd40f":"<strong>Файли AIFF заявляли подвійну частоту дискретизації</strong>, тож інші програми відтворювали їх на октаву вище. Файли AIFF-C із плаваючою комою тепер мають повний заголовок.","changelog.b85e29446f98":"<strong>24-бітний FLAC неправильно масштабувався і дизерувався.</strong>","changelog.81c39a6550b6":"<strong>Експортовані файли <code>.mid</code> обрізали повторювані ноти в інших DAW.</strong> Початок ноти записувався раніше за кінець попередньої ноти на тому самому тіку.","changelog.f92853678a37":"⚠ <strong>Експорт досі рендериться без плагінів VST 3 і CLAP.</strong> Див. <em>Ще не вирішено</em>.","changelog.cdb5aaa35ee1":"<strong>Запис</strong>","changelog.cd64252ce063":"<strong>Вхід 44.1 кГц при виході 48 кГц записувався з пропусками</strong> — близько 8% дубля було тишею. Тепер вхід відкривається на частоті виходу або конвертується.","changelog.0c4683ccfd2e":"<strong>Затримка дубля залежала</strong> від того, як довго був відкритий вхід.","changelog.18dc0df95ce2":"<strong>Дублі з відліком і панч-дублі лягали із запізненням аж до одного буфера</strong>, а блок на панч-ауті губився. MIDI-панч зберігав ноти, зіграні до панч-іну.","changelog.b39ca3f1ef37":"**Перетягнутий файл, копіювання якого не вдалося, лишав неповний файл в <em>Imports</em>.**","changelog.f489fa7c6c3b":"Мінімальний проміжок між нотами під час виявлення атак був на один крок аналізу задовгим.","changelog.585177b8005b":"<strong>Плагіни</strong>","changelog.9ea91ef0792f":"<strong>Повороти ручок у власному вікні плагіна VST 3 ніколи не доходили до звуку</strong>, а зміни параметрів понад 512 в одному блоці губилися.","changelog.27e989498bde":"<strong>Скасування видалення пристрою повертає його звук таким, яким він був.</strong>","changelog.27732aa68c31":"<strong>Видалення доріжки закриває процеси її плагінів</strong>, а новий чи відкритий проєкт звільняє процеси попереднього.","changelog.3db09f2ff76a":"<strong>Плагін, що впав або завис, міг заморозити програму.</strong> Тепер несправний плагін зупиняється, перш ніж Oscillate почне на нього чекати, а під час запуску плагіна не утримується жодне блокування. Про збій у керувальному з'єднанні плагіна тепер повідомляється.","changelog.d5b5750c16ca":"<strong>Плагін, знайдений вручну, так і не потрапляв до індексу</strong>, а повторне сканування скасовувало розблокування й знайдені плагіни, додані під час його роботи.","changelog.8d834fbea6c9":"<strong>Плагін, що змінює власну затримку</strong>, тепер отримує новий, компенсований план.","changelog.750a21151bde":"<strong>Файлові діалоги працювали в головному потоці</strong> (відкриття, збереження, «зберегти як», пресети ланцюжків, <em>Знайти…</em>, додавання теки плагінів, вибір теки для прослуховування, імпорт тексту пісні й аудіо) і могли заблокувати вікно. Тепер усі вони працюють поза ним.","changelog.78ee198e26b6":"<strong>Редактори</strong>","changelog.2b57535746ad":"<strong>Перетягування кінцевого краю ноти тепер змінює її довжину</strong>, а перетягування початку зсуває початок і зберігає кінець — одним кроком скасування.","changelog.eb080b94fcd5":"<strong>Діагональне перетягування ноти й діагональне перетягування з копіюванням — кожне один крок скасування</strong>, а перетягування з <code>Ctrl</code>/<code>Alt</code> копіює замість переміщення.","changelog.33cf4310ae9b":"<strong>Доріжка автоматизації під кліпом, що стоїть не на такті 1, малювала й записувала свої точки на такті 1.</strong> Тепер вона працює там, де кліп справді стоїть. Під барабанним набором вона більше не стежить за прокручуванням прихованого piano roll, а <em>Зберегти як кату</em> і <em>Штамп</em> охоплюють власний проміжок кліпу.","changelog.a75d2252b98e":"<strong>Заглушення проміжку всередині тихої обвідної підсилення роздувало звук довкола нього.</strong> Розділення, вирізання чи обрізка зліва тепер лишають обвідну підсилення кліпу там, де звук.","changelog.b4c012d3b380":"<strong>Маркери транзієнтів на розділеному чи обрізаному кліпі показували удари, яких кліп не відтворює.</strong> Обрізка з аудіоредактора зберігає зсув попередньої обрізки — і у відокремленому вікні редактора теж. Аудіоредактор більше не малює застарілий фрагмент після масштабування, а реверсований кліп — у прямому напрямку при масштабі до семплів.","changelog.14e60b4dae34":"<strong>В аранжуванні</strong> виділений кліп, прокручений за межі видимості, під час переміщення чи копіювання опинявся не там, а обрізка зліва могла зайти за початок звуку й зсунути його раніше. Обрізка чи фейд показували попередній вигляд для всього виділення, хоча змінювався лише захоплений кліп; тепер попередній вигляд показує саме те, що зробить відпускання. Жест, скасований операційною системою, застосовувався, а не відкидався.","changelog.3e8ed6000a39":"<strong>Клацання з протягуванням у барабанній сітці працювало лише в тестовому браузері</strong>, а правий клік більше не перемикає клітинку.","changelog.c83a3388d770":"<strong>Введення значення в ручку</strong>: 6 дБ тепер означає 6 дБ, а не повний хід, а 50 у полі панорами більше не означає R100.","changelog.ca7b3b7fb67d":"<strong>Екранна клавіатура й гаряча клавіша на тій самій літері спрацьовували обидві.</strong> Клавіші зі стрілками в списку браузера й на лінійці провалювалися далі й зсували аранжування.","changelog.4ecad0ceceaa":"<strong>Транспорт ▸ Home, End, Вказівник і Лезо нічого не робили.</strong>","changelog.8872f6e3c7a1":"<strong>Вихід із рядка тексту клавішею Tab стирав таймінг його складів.</strong> Рядок тексту, кинутий точно на початок іншого рядка, більше не відхиляється.","changelog.c967a14cb0d7":"<strong>Рек патернів</strong> оновлюється після скасування, повтору й правки учасника, а вибір патерна відкривається на поточному патерні.","changelog.9b72ff0fe3e8":"<strong>Арабська</strong>: смуга прокручування, роздільник, доріжка тексту й картка сесії віддзеркалювалися неправильно.","changelog.0af10661d846":"<strong>Кожне речення з числом має форми множини</strong> в усіх вісімнадцяти мовах.","changelog.b58312a40a18":"<strong>Дрібніші:</strong> курсор відтворення в прослуховуванні <code>.mid</code> біг із подвійною швидкістю; перетягнутий <code>.mid</code>, перша нота якого стоїть на нулі, лягав на один тік пізніше; протягування в доріжці CC виходило зигзагом; ручку фейду нульової довжини не можна було захопити; перетягування висоти доріжки лишалося зміщеним після відмови; 32-бітні цілочислові WAV і 24-бітне аудіо в 32-бітному контейнері малювалися й звучали як шум на повну шкалу.","changelog.ea7aa3c36986":"<strong>Пристрої та інструменти</strong>","changelog.d838f5d0cc47":"<strong>Поворот ручки на заводському інструменті (Cello, Sub Bass та інших) перетворював його на типовий синтезатор Wavetable</strong>, і скасування не повертало його назад. Тепер заводські інструменти відкривають панель, показують свій ряд ручок звуку й копіюють рецепт, у якому названо саме їх.","changelog.618828dda056":"<strong>Chamber і Vault були нестабільними з типовими налаштуваннями.</strong> Їхній регулятор «Загасання низьких» міг змусити реверберацію наростати без меж. <em>Заморозка</em> тепер не згасає й не наростає.","changelog.96ae9147c9a5":"<strong>Деесер Quench працював постійно</strong>, а не лише на свистячих.","changelog.a33e5317a331":"<strong>Повтори Relay з кожним відлунням зсувалися дедалі пізніше</strong>, Sparks клацав із типовими налаштуваннями, Gild клацав між блоками, а Ceiling задавав одне підсилення на блок. Спільний оверсемплер давав збої на межах блоків при типовому розмірі буфера, що зачіпало кожен драйв, підсилювач і сатуратор.","changelog.0b69c04327da":"<strong>Зворотний зв'язок міг піти врознос</strong> у Shoal і Relay та заклинити доріжку в тиші.","changelog.c9fc79327515":"<strong>Регулятори, які нічого не робили, тепер працюють:</strong> «Зміщення сітки» в Guard, «Дифузія» у Vault, «Натяг» у Coil у всьому діапазоні, «Положення динаміка» у Foil, «Середній» у Wear і «Передискретизація» в Ceiling.","changelog.f73ae6f614ed":"<strong>Також виправлено:</strong> Halve і Flush у Lantern, Rein за нульового чи змінного часу відлуння, Comb при переході через нуль, поріг Strand, а також сухий сигнал у Cleave і Strand, який не затримувався відповідно до обробленого.","changelog.d3d9ad692654":"<strong>Більше жодних завислих нот</strong> від Scatter, Turn, Hone, Stack, Approach, Hold, Tread, Runner чи Revoice, а нотні пристрої тепер грають однаково за будь-якого розміру аудіобуфера.","changelog.039ca12ebc31":"<strong>Hammer</strong> звучить при «Утриманні» 0 і більше не подвоює рівень при повторному запуску; <strong>перехоплений голос семплера згасає</strong>, а не клацає; клеп у Skin реагує на велосіті; «Зворотний зв'язок» у Sideband працює на всіх восьми алгоритмах; Armory більше не падає на нотах вище 127. Плавні переходи в кожному інструменті тепер рівні за будь-якого розміру буфера.","changelog.bf11fb10bbc6":"<strong>Криві на картках пристроїв</strong> вимірювалися, поки пристрій ще плавно переходив до значень, тож були неправильними.","changelog.74b1e2eb3733":"<strong>Кімнати й сесії</strong>","changelog.a0322da52ba0":"<strong>Батл Куміте існував лише на машині, де натиснули «Почати».</strong> Кліпи учасників у їхніх власних тактах мовчки відкидалися, а порядок ходів міг різнитися між машинами. Тепер батл — частина проєкту, його запускає й зупиняє хост, і він однаковий на кожній машині.","changelog.221c7bfd4bd2":"<strong>Дублі:</strong> дубль, який у вас уже є, більше не зараховується проти хоста; дублі, що надходять одночасно, більше не губляться; передавання більше не спричиняє випадінь звуку; напівзаписаний файл дубля видаляється.","changelog.ca86740f15d8":"<strong>Кожне повідомлення в з'єднанні, яке запропонувала ця машина, оброблялося двічі.</strong>","changelog.97e5f228e6ba":"<strong>Мікрофон міг лишатися ввімкненим, хоча його кнопка показувала, що він вимкнений</strong>, — після зупинки іншого захоплення. А режим «натисни й говори» спрацьовував, коли ви друкували в текстовому полі.","changelog.4a064c4a34ce":"<strong>Перемотування сесії</strong> заморожувало програму під час відтворення історії. <em>Скасувати досюди</em> скасовувало один крок, а тепер скасовує до вибраної точки; <em>Повернутися в теперішнє</em> відновлює живе аранжування; невдале відгалуження про це повідомляє.","changelog.3d5138762144":"<strong>Розподіл авторства</strong> позначає ваш власний рядок, оновлюється, коли приєднується інший учасник, і більше нікому не приписує каркас шаблону.","changelog.c893c1638a99":"<strong>Правки, що могли зламати сесію:</strong> запис усього порядку доріжок міг загубити доріжки; видалення доріжки чи кліпу лишало рядки патерна, що вказували в нікуди, тож кожен наступний жест у реку на цьому патерні відхилявся; можна було видалити дубль, який ще використовувався на іншій доріжці; дві машини могли назавжди розійтися, коли одна редагувала всю доріжку, а інша — щось усередині неї; кліп, перенесений на доріжку, яку тримає хтось інший, перевірявся не за тією доріжкою.","changelog.8dfa12545efa":"<strong>Правка, зроблена одразу після збереження, не позначала проєкт як незбережений</strong>, а швидка правка могла злитися зі скасуванням чи повтором.","changelog.5fe00713937b":"<strong>Частини файлу, записані новішою версією Oscillate, тепер переживають збереження.</strong>","changelog.eb5b0a0ed3af":"<strong>Повторне приєднання до кімнати</strong> більше не дописує в журнал попередньої сесії.","changelog.80a4afa3903d":"Таймлапс сесії, розпочатої із шаблону, більше не відкривається фальшивим розділом <em>Кімнату відкрито</em>; перевірка з'єднання більше не повідомляє про симетричний NAT, якого немає; п'ятий учасник більше не може приєднатися.","changelog.bf9104f16adc":"<strong>Вікна й налаштування</strong>","changelog.f478b946c3ed":"<strong>Відокремлені вікна перезаписували налаштування одне одного.</strong> Тепер налаштування записуються по одному ключу, під одним блокуванням, і кожне вікно їх перечитує.","changelog.0e7572903a98":"<strong>Вихід із програми, коли вікно було згорнуте, губив його положення й розмір.</strong>","changelog.3d17c7fddadd":"<strong>Два звіти про збій, записані одночасно, перезаписували один одного.</strong>","changelog.8ad92ece2e49":"<strong>Журнал відновлення скидається на диск, коли Oscillate завершує роботу</strong>, коли ви зупиняєте відтворення і коли надходить дубль.","changelog.09d6b687a5b5":"<em>Так, перевіряти під час запуску</em> у запитанні першого запуску мовчки відхилялося, а невдале встановлення оновлення зникало без жодного слова.","changelog.166249aead89":"Призначення <code>Space</code> у Налаштування ▸ Клавіатурні скорочення забирало клавішу у відтворення; екран помилки заміняв рядок заголовка, тож вікно не можна було закрити; вікно могло лишитися немасштабованим після перетягування, перерваного посередині.","changelog.42078e2a4ce9":"<strong>Оновлювач та інструменти випуску</strong>","changelog.079af0dc6c83":"<strong>У Windows не було б маніфесту оновлень узагалі.</strong> Скрипт випуску шукав назви інсталяторів, яких Tauri 2 не створює.","changelog.ec17b741d16a":"<strong><code>1.0.0</code> збігалася б з інсталяторами <code>1.0.0-rc</code></strong>, тож маніфест фінального випуску міг би назавжди вказувати на реліз-кандидат.","changelog.12c5a28c6a09":"<strong>Тег реліз-кандидата не міг зібрати свій інсталятор</strong>, бо MSI відхиляє передрелізну версію. Тепер передреліз збирає лише NSIS.","changelog.df7f1b0ff2d6":"<strong>Нотатки до випуску вирізалися за збігом префікса</strong>, тож <code>1.0.0</code> узяла б нотатки реліз-кандидата, а відсутні нотатки викликали лише попередження. Тепер це рівно розділ цієї версії, а промах зриває випуск.","changelog.88312da3637b":"<strong>Перевірки, які не могли впасти або ніде не запускалися:</strong> перевірці паритету в CI бракувало цілі WebAssembly; перевірка завантажень провалювала кожен випуск лише для Windows; наскрізні тести у двох файлах не могли впасти; запуск наскрізних тестів переписував знімки екрана в документації; опублікована сторінка змін містила дублікати id розділів. Нова перевірка відхиляє керівні символи в журналі змін і документації.","changelog.da13fe88f9b4":"<strong>Знайдено під час огляду самих виправлень</strong>","changelog.d52c1048f2f9":"⚠ Кожне виправлення вище після внесення переглянули ще раз. Ці огляди знайшли справжні регресії у виправленнях і кілька старіших дефектів, які пропустив перший прохід. Усі вони виправлені тут.","changelog.8f27c8f6a2dc":"⛔⛔ <strong>Після видалення доріжки чи відкриття проєкту екранна клавіатура, MIDI-клавіатура й прослуховування нот у piano roll грали не на тій доріжці або взагалі мовчали, а запис нічого не захоплював.</strong> Живі ноти адресувалися за id каналу, тоді як рушій читає їх за позицією, і ці два збігаються лише до видалення першої доріжки. Тепер ноти знаходять свою доріжку за позицією, яку перечитують після кожної зміни, а клавіша, утримувана під час видалення доріжки, відпускається на своїй доріжці.","changelog.0e5001be4975":"⛔ <strong>З увімкненим циклом MIDI-ноти на початку циклу губилися на кожному повторі після першого.</strong> З аудіокліпами все було гаразд. Тепер планування нот знає про цикл.","changelog.4dd4a9484523":"⛔ <strong>Правки в кімнаті, що зачіпали кілька речей одразу, могли лягти по-різному на різних машинах — назавжди й мовчки</strong> (переміщення двох кліпів, поки хтось перефарбовував один із них, або видалення доріжки, поки хтось редагував її патерн). Тепер кожна правка в межах операції розв'язується окремо, а нова перевірка програє три машини через усі можливі порядки надходження.","changelog.73da74cfe8a0":"⛔ <strong>Учасник міг перехопити ваш <code>Ctrl+Z</code></strong>, повторно використавши id вашої останньої правки. Тепер id, який уже належить комусь іншому, відхиляється, і це коштує порушникові штрафного бала.","changelog.3496697e7b5b":"⛔ <strong>Збереження могло обвалити плагін, налаштування якого перевищували приблизно 19 МБ, а кожне збереження додавало у файл проєкту ще одну повну копію доріжки</strong>, тож файли росли без меж. Тепер налаштування плагінів передаються як байти й зберігаються у файлі один раз: ніколи в історії скасувань, ніколи в кімнаті.","changelog.f26a96f70549":"<strong>Плагіни:</strong>","changelog.6efbe93b609b":"Плагін, що відхиляє свої збережені налаштування, більше не записує свої типові налаштування поверх ваших.","changelog.3d2817502593":"Затримка, про яку повідомляє плагін, більше не позначає проєкт зміненим, не додає крок скасування й не стирає налаштування плагіна у співавтора.","changelog.c4b6e7b8714a":"Плагін, що один раз пригальмував, більше не вважається таким, що впав, а той, що відповідає миттєво, більше не приймається за завислий і не перезавантажується.","changelog.ae1ae60b6520":"Скасування й повтор повертають плагіни з тими налаштуваннями, що в них були, — зокрема коли співавтор видалив доріжку й скасував це і коли плагіна на той момент бракувало.","changelog.5dc3a7247bfd":"Зміни пресетів VST 3, що зачіпають понад 128 параметрів, тепер повністю доходять до звуку, а плагін більше не перезапускається на кожному блоці. Перезапуск VST 3 більше не викидає інші зміни, про які плагін оголосив під час нього.","changelog.1396f179afdf":"Плагіни працюють на частоті дискретизації аудіопристрою.","changelog.39e285644bd7":"Файлові діалоги належать головному вікну й відкриваються по одному. «Зберегти як» відмовляє, якщо проєкт відредагували чи замінили, поки діалог був відкритий, а «Відкрити» більше не відхиляється через те, що співавтор тим часом щось змінив.","changelog.ba3a925735d4":"<strong>Відтворення і запис:</strong>","changelog.ac75155693e0":"Від'єднання й відновлення аудіопристрою або зміна темпу під час відтворення більше не розсинхронізовують звук і курсор відтворення.","changelog.cfe7e8319c5a":"Доріжки з компенсацією затримки плагіна більше не випадають щоразу, коли мікс перебудовується або цикл повертається на початок.","changelog.99bca8f464be":"Утримувані клавіші більше не обриваються, коли цикл повертається на початок або курсор відтворення зсувається.","changelog.d98cd614c1dc":"Ноти, зіграні під час відліку, більше не звалюються на першу долю дубля. Нота, зіграна трохи раніше сильної долі (у межах блока або 30 мс), зберігається й лягає на неї.","changelog.e786b3ffa54c":"Трохи запізнілий виклик входу більше не лишає пропусків у записі, а моніторинг входу більше не зникає на кілька мілісекунд щоразу, коли обрізається черга вхідних даних.","changelog.ee43b80e51fe":"Ноти з параметром «Імовірність» після переміщення курсора відтворення більше не повторюють той самий малюнок, який дав би наступний прохід циклу.","changelog.ae9faf402cfe":"Багатоканальні аудіоінтерфейси більше не міняють входи місцями після переповнення.","changelog.a28c78da2430":"Входи з високою частотою дискретизації більше не дають аліасингу в сесії з нижчою частотою.","changelog.66785b97f53f":"<strong>Експорт:</strong>","changelog.e230adbb4330":"MP3 понад 48 кГц провалювався вже після рендеру всієї пісні. Тепер MP3 записується на 48 кГц, і Налаштування ▸ Експорт про це кажуть.","changelog.6e5025c21bdc":"Відхилений експорт тепер пояснює причину під меню «Файл»; раніше він провалювався мовчки.","changelog.1de1be9b8ded":"Пристрій із попереднім переглядом сигналу (look-ahead) більше не змушує експорт починатися пізно й губити кінець.","changelog.69d54e8f37b8":"MIDI в експорті більше не зсувається раніше після зміни темпу чи плавного переходу темпу.","changelog.a4184301f89d":"<strong>Перемикач «Дизеринг» ігнорувався:</strong> кожен 16- і 24-бітний експорт дизерувався навіть із вимкненим перемикачем. Тепер його враховано, а стеми мають незалежний дизеринг.","changelog.01060597d526":"Файли, перетягнуті з тимчасової теки, більше не лишають копій в Imports.","changelog.1181bbddc23a":"Панель «Гучність» більше не називає кожен показник «неповним» на 88.2 кГц і вище.","changelog.0f052d7de643":"<strong>Кімнати й сесії:</strong>","changelog.ce576eef99b0":"Будь-хто може завершити батл Куміте — зокрема той, хост якого пішов, — і батл ніколи не зберігається у файл проєкту; два одночасні натискання «Почати» дають один батл.","changelog.9a242815cb22":"Приєднання до кімнати з проєктом, який також є у вас на диску, більше не видаляє дані відновлення після збою для цього проєкту.","changelog.e1a82a286154":"«Скасувати досюди» в кімнаті надсилає кожне скасування іншим продюсерам і забирає назад зміни, які ви повторили після того моменту.","changelog.152a9fa8944c":"Дубль, обірваний збоєм, надходить під час наступного надсилання.","changelog.b58ba06bb488":"Відновлення після збою зберігає перетягування фейдера співавтором, яке перервала ваша власна правка.","changelog.db0e3ba74f7a":"Відкриття проєкту в кімнаті більше не дає старішим правкам учасників перезаписати його; повторне приєднання до кімнати більше не коштує вам штрафного бала.","changelog.121c95328780":"Два окремі повороти однієї ручки — це два кроки скасування, а не один.","changelog.731cf5b68562":"Відокремлені вікна більше не скасовують одне одному розміри панелей, гарячі клавіші чи налаштування експорту.","changelog.19fbc09eb565":"Файл ▸ Новий більше не пропонує відновити сесію, яку ви щойно залишили.","changelog.9e2773fb1867":"Ручка, яку ви повертаєте на пристрої, поки на ньому щось тягне співавтор, зберігає своє значення на кожній машині, а фейдер чи ручка, відведені й повернуті туди, звідки почали, доходять до кімнати замість того, щоб коштувати вам штрафного бала.","changelog.0541b65c1e83":"Доріжка чи дубль, видалені, поки співавтор перефарбовує один із їхніх кліпів або робить на ньому фейд, зникають на кожній машині, а скасування видалення, поки співавтор змінює той самий кліп, повертає його на кожній машині.","changelog.d15a8772edef":"Зведення кількох MIDI-кліпів в аудіо одночасно доходить до інших продюсерів, а патерн, що грав два з них, більше не продовжує вказувати на один.","changelog.622a2b984e68":"Завершення батлу, який почав хтось інший, більше не ламає <code>Ctrl+Z</code>, а гість, що виходить із кімнати, більше не завершує батл хоста для всіх.","changelog.0603f0c1588b":"Продюсер, що повертається в кімнату, зберігає правки, зроблені під час перепід'єднання, його ім'я та місце в батлі повертаються, щойно зникає його старе з'єднання, а друга людина, що видає себе за нього, більше не може перехопити його особу.","changelog.f1a8d7a6d26e":"Відхилена правка учасника більше не дає цій машині повторно використати її мітку, а прийняте в кімнаті відновлення після збою більше не дає старішим правкам учасників перезаписати відновлену роботу.","changelog.c8981d80a918":"<strong>Редактори:</strong>","changelog.e708a20db8e5":"Перше перетягування ручки на інструменті зі старішого проєкту (скажімо, заводському Cello) — це один крок скасування, а в кімнаті воно більше не перезаписує правки співавтора на цій доріжці.","changelog.102d708d0039":"Під барабанною сіткою доріжка автоматизації вирівнюється з кроками.","changelog.8febd9bab766":"Рядок тексту, кинутий точно на початок іншого рядка, ставиться після нього, і більше нічого не зсувається.","changelog.1a424e0ded88":"Файли WAV, заголовок формату яких вказує щось інше, ніж звичайний PCM чи плаваючу кому, відхиляються з повідомленням, а не відтворюються як шум.","changelog.08c29531d3c4":"Рядок патерна, кліп якого видалено, не показує кліпу взагалі, а не безіменний кліп, який не можна відкрити.","changelog.3c2daf0d3e7f":"<strong>MIDI-вхід:</strong> клавіші, зіграні, коли до запису підготовлено доріжку, якій нема на чому грати, відхиляються, а не накопичуються, щоб потім прозвучати всі разом; можна вибрати обидві з двох однакових клавіатур; Налаштування ▸ MIDI більше не зависають через повільний драйвер.","changelog.412206443be0":"Змінено — що звучить інакше у збереженому проєкті","changelog.6459a83979a9":"⚠ <strong>Проєкт, збережений до цієї збірки, може звучати інакше, коли ви його відкриєте.</strong> Кожен пункт тут — виправлення, і кілька з них зсувають рівні на кілька децибелів, тож перевірте мікс, який вам важливий.","changelog.d2730738dfc9":"<strong>Запис ігнорує цикл.</strong> Поки ви записуєте, цикл вимкнено — і для аудіо, і для MIDI, — а дубль іде прямо далі за кінець циклу. Для відтворення цикл діє, як і раніше. Раніше кожен прохід зацикленого запису записувався впритул один до одного, а MIDI-дубль розходився з аудіодублем.","changelog.15f909e8e1c8":"<strong>Експорт може тривати до десяти хвилин за будь-якої частоти дискретизації.</strong> Якщо машині бракує пам'яті, щоб його вмістити, він одразу відхиляється із зазначенням причини. До цієї збірки межа становила десять хвилин на 48 кГц, а експорт ігнорував вибрану частоту.","changelog.3d3d8119cb3d":"<strong>Затримка Ceiling із типовими налаштуваннями — 100 семплів (було 72)</strong>, і перемикач «Передискретизація» тепер її змінює. Ceiling оголошує свій look-ahead плюс власну затримку детектора, тож компенсація затримки плагінів його вирівнює.","changelog.18563098f694":"<strong>Comb:</strong> перехід через нуль увімкнено за замовчуванням, а центр розгортки на один крок «Затримки» нижчий.","changelog.429dc9a41e0f":"<strong>«Натяг» у Coil</strong> тепер відображає 0 на 1.92 (було 1.2), а 1 — на 0.75 (було 1.0); 0.5 не змінилося.","changelog.42ca15cb09d8":"<strong>Wear, Spool і Oxide:</strong> складова 6 Гц тепер підкоряється «Плаванню», а не «Детонації». Носії Vinyl і Converter у Wear звучать по-новому; Tape не змінився.","changelog.9605e8d810a8":"<strong>Sparks:</strong> коли хмара розріджена, а також із типовими налаштуваннями, зерна тепер — чисті вікна Ганна, тож форма зерна змінюється, навіть якщо ви її ніколи не чіпали.","changelog.a2fb1a26818a":"<strong>Guard</strong> відкривається лише в межах свого «Зміщення сітки» від ноти.","changelog.ee039b997faa":"<strong>Vise, Weld, Parry, Peen і Guard:</strong> сайдчейн фільтрується перед вимірюванням, тож фактичні пороги зсуваються на кілька децибелів.","changelog.4415b1af6ee9":"<strong>Quench</strong> деесує з іншою силою.","changelog.2d621f5fc3be":"<strong>Edge:</strong> «Атака» й «Спад» тепер учетверо повільніші, як і підписано.","changelog.c091d1c40cb7":"<strong>Triode, Rasp, Shear і Fold:</strong> баси й просідання змінюються за високої передискретизації. <strong>Furnace:</strong> змінюється таймінг просідання.","changelog.3875af7ad8a2":"<strong>Chamber, Foil, Coil, Vault і Baffle:</strong> змінюються вихідні відводи реверберації, тож рівень і стереообраз зсуваються. Пізнє поле <strong>Vault</strong> тепер починається на передзатримці, а його дифузори коротші.","changelog.0a57881c2b36":"<strong>Shoal</strong> має менший зворотний зв'язок, коли «Голоси» більше за 1. Драйв <strong>Rein</strong> тепер наростає разом із його величиною.","changelog.72f7c4662b6e":"Повтори <strong>Relay</strong> лягають вчасно, і через його новий лімітер зворотного зв'язку проходять лише відлуння, що йдуть на нове коло, тож гарячий вхід не насичується. Додаткові головки <strong>Spool</strong> повторюють саме в задані моменти.","changelog.def90dbc42c4":"<strong>Sideband</strong> тепер справді робить чотирикратну передискретизацію й оголошує затримку 24 семпли. <strong>Hammer</strong> більше не подвоює рівень при повторному запуску, а клеп у <strong>Skin</strong> реагує на велосіті.","changelog.5d9cf4f7dd65":"<strong>Інтегровані LUFS</strong> показують інакше: стробування тепер використовує блоки по 400 мс із перекриттям 75%, як і вимагає стандарт.","changelog.85271e6ecd8c":"<strong>Експорт більше не дизерується, якщо «Дизеринг» не ввімкнено.</strong> Раніше перемикач ігнорувався, тож 16- чи 24-бітний експорт, зроблений попередньою збіркою, містив дизеринг, якого ви не просили.","changelog.d82014f95805":"<strong>Запис і моніторинг входу запізнюються приблизно на 5 мс</strong> при аудіоперіоді 10 мс. Вхід тепер тримає невеликий запас, щоб трохи запізнілий виклик не лишив пропуску в дублі; затримка стала.","changelog.ccde2b49c256":"Ще не вирішено","changelog.a501d4a1a083":"⚠ <strong>Експорт рендериться без плагінів VST 3 і CLAP</strong> (TASK-098). Про це сказано в README в кожній теці експорту. Щоб це виправити, офлайн-рендер має отримати власний екземпляр плагіна, а це архітектурне рішення, а не дефект.","changelog.0740065d75e1":"⚠ <strong>Пітч-бенд, колесо модуляції й тиск MIDI-клавіатури</strong> поки не передаються. Ноти, велосіті й педаль сустейну — передаються. Апаратна нота звучить на початку аудіоблока, що її отримав, а записані дублі ще не компенсуються на затримку входу й виходу.","changelog.e4f8567eaca5":"⚠ <strong>Налаштування плагінів зберігаються у файлі проєкту як список чисел</strong>, що приблизно в три з половиною рази більше за їхній розмір, а відновлення після збою повертає їх такими, якими вони були на момент останнього збереження.","changelog.94b3ea8fff75":"⚠ <strong>Чотири рідкісні стани гонитви в кімнаті досі можуть лишити машини різними:</strong> кліп, поставлений на доріжку в ту саму мить, коли співавтор цю доріжку видаляє; правка, зроблена в момент відкриття батлу Куміте, перш ніж її автор побачив батл; ручка на старішому інструменті, яку повернув один продюсер і яка доходить до третьої машини раніше за перший рух ручки, що її підготував; і кліп, видалення якого скасовують, поки співавтор його перефарбовує, — він повертається скрізь, але перефарбування може зберегтися лише на деяких машинах.","changelog.7f22bd522c65":"Додано — патерн нарешті може потрапити на стрічку часу","changelog.91f6d0b1eef7":"⛔⛔ **<code>ClipContent::Midi</code> є живим посиланням від TASK-037A — <em>«правка джерела змінює кожне його розміщення, і це і є патерн»</em> — але ніщо на сторінці не могло створити друге розміщення будь-чого.** <code>ArrangementEdit::PlacePattern</code> не мав джерела, а його обробник безумовно викликав <code>MidiSource::empty</code>, тож кожне розміщення було новісіньким порожнім патерном. Продюсер міг зібрати патерн у реку, але не мав жодного способу вставити його в пісню. Модель це вміла, а продюсер — ні; саме за цю різницю проєкт уже раз заплатив на журналі операцій.","changelog.894247c903fd":"<strong><code>PlacePattern</code> приймає необов'язкове <code>source</code>.</strong> Один варіант, а не два: сусідній <code>PlaceExistingPattern</code> був би тим самим дефектом «двоє дверей до одного поля», через який 2026-09-17 видалили <code>ArrangementEdit::SetClipLoop</code>. <code>None</code> — це точнісінько стара поведінка, і подвійне клацання на порожній стрічці часу тепер так і каже.","changelog.a278c0f6d9cf":"<strong>Рек ставить патерн рядка на позицію курсора відтворення</strong>, беручи власну довжину кліпу, а не вгаданий такт, а кліп отримує назву патерна, тож два розміщення <em>Куплет</em> читаються як двічі <em>Куплет</em>, а не як двоє незнайомців.","changelog.bad0be6b218c":"⚠ <strong>Кнопка, а не перетягування.</strong> WebView2 у Tauri передає кожне перетягування HTML5 обробникові скидання файлів ОС, перш ніж його побачить сторінка, тож <code>draggable</code> + <code>onDragStart</code> зелені під Playwright — у Chromium під ним немає шару Tauri — і мертві в готовій програмі. До того ж кнопку клавіатура й екранний диктор отримують задарма.","changelog.b2a11a0200e5":"⛔ <strong>Розміщення показує аранжування.</strong> Рек і стрічка часу займають той самий центральний слот, тож зсередини реку успішне розміщення нічого не змінювало на екрані — те саме «здається, воно нічого не робить», яке цей випуск виправляє й у <em>Новий патерн</em>, а розміщення, якого продюсер не бачить, він натискає знову.","changelog.d996223bdc2c":"⛔⛔ <strong>Перевірка — це саме живе посилання</strong>: поставити один патерн двічі, один раз відредагувати ноти й переконатися, що змінилися <strong>обидва</strong> розміщення, — а тоді <em>Зробити унікальним</em> для одного й переконатися, що інше не змінилося. ⚠ Будь-що слабше проходить на реалізації з копіюванням під час розміщення, яка в день випуску виглядає на екрані так само, а потім її вже не розплутати. Доведено: таку реалізацію написали й побачили, як ця перевірка — і лише вона — стала червоною.","changelog.4e4c1e91df18":"Виправлено — <em>Новий патерн</em> виглядав так, ніби нічого не робить","changelog.bb60005cf453":"⛔ <strong>Власник, 2026-09-19.</strong> Правка щоразу застосовувалася. <code>refreshPatternRack</code> зберігає відкритий патерн, <em>якщо він ще існує</em>, а після додавання попередній завжди існує — тож виділення ніколи не зсувалося, вміст панелі ніколи не змінювався, і єдиним свідченням успіху був ще один пункт у закритому випадному списку.","changelog.cb9e75e7d0bf":"<strong>Тепер відкритим стає новий патерн</strong>, знайдений через різницю множин, а не за позицією: <code>patterns.at(-1)</code> було б неявним другим твердженням про порядок, у якому модель повертає патерни, — правдивим сьогодні й мовчазним, коли воно перестане бути правдою.","changelog.fe911c060ae2":"<strong>Новий патерн більше не бере вже зайняту назву.</strong> Номер брався з кількості, тож після <em>Патерн 1 / 2 / 3</em> з видаленим <em>Патерн 2</em> наступний ставав другим <em>Патерн 3</em> — тоді як коментар поруч стверджував, що саме така будова цьому й запобігає. Вибір показує патерни за назвою, тож два з однаковою назвою неможливо розрізнити в єдиному місці, де продюсер між ними вибирає.","changelog.37c6b44b957f":"⚠ **Наявний тест перевіряв, що правку <em>надіслано</em>.** Її таки надсилали. Усі перевірки були зелені над кнопкою, яку власник назвав мертвою, — пастка 8 майже дослівно: тести покривали частини, але ніколи не шов між ними. Новий тест питає, що продюсер бачить після цього.","changelog.8bc07e14cb41":"Змінено — крейт synth наздогнав своє першоджерело","changelog.154685bf2ba8":"▶ <strong><code>synth/</code> імпортується з <code>Freally MIDI Master</code> і ніколи не редагується тут</strong> (TASK-077), а <code>tests/the_synth_is_not_forked.rs</code> порівнює обидві копії побайтово на будь-якій машині, де вивантажено обидві. Цей тест почервонів: ця копія відставала на один коміт.","changelog.973b9db56f9d":"<strong>Повторно імпортовано на <code>ff99972c</code></strong> — запушеній ревізії, а не робочому дереві, тож скопійоване не могло зсунутися під копією. Узято весь <code>src</code>, а не лише три файли, що відрізнялися, — це й доводить, що більше нічого не розійшлося: <code>git</code> показує рівно ці три плюс заголовок.","changelog.d0edfd8085ba":"<strong>Разом із ним прийшла одна функція</strong>: трисмуговий регулятор тембру на виході кожної партії, після каскаду драйву. За замовчуванням АЧХ пласка, а <code>is_flat()</code> пропускає весь каскад, замість того щоб ганяти три біквадратні фільтри з одиничним підсиленням.","changelog.563488a64458":"⚠ <strong>Жоден заводський звук не змінився, і це виміряно, а не доведено словами.</strong> Для всіх <strong>1 648</strong> запечених ван-шотів зняли відбитки до імпорту й запекли їх знову після нього: кожен побайтово ідентичний. Обхід точний.","changelog.719cec9783d3":"⛔ <strong>Власний заголовок крейта чотири коміти поспіль стверджував, що він «ідентичний первинному імпорту, крім перенесення рядків rustfmt».</strong> Це перестало бути правдою в <code>b6149993</code> і лишалося на сторінці до <code>0e36a6ab</code>. Тепер заголовок називає чотири коміти, які його змінили. Перевірка цього продукту прив'язувала твердження до вилученого речення, тож перевірка перейшла на речення, що його замінило: заголовок, який більше не каже, що крейт імпортовано, — досі провал, а на машині без сусіднього checkout це <em>єдине</em>, що перевіряє.","changelog.69b25eeb0c5b":"<strong>Тринадцять перевірок, яких не було в першоджерелі.</strong> Регулятор тембру вийшов без жодного тесту в обох продуктах, а <em>«кожне поле в типовому значенні — це точний обхід»</em> тримає на собі 372 600 звуків там і 1 648 тут — і трималося лише на коментарі. Для кожної доведено, що вона падає на дефекті, який називає. Ті, що варті свого місця:","changelog.b94bccab9f9e":"<strong>Типовий патч рендериться побітово ідентично патчу з абсурдними частотами смуг і всіма підсиленнями на нулі</strong> — тож плаский еквалайзер не може просочити свої центральні частоти у вихід.","changelog.5e207e72d810":"<strong>Зсунуту смугу чути.</strong> ⚠ Без цього тест обходу вище так само радісно проходив би на еквалайзері, не під'єднаному ні до чого, — а це найчастіше записаний дефект цього проєкту.","changelog.185db1f5eda0":"<strong>Кожна смуга робить те, що каже її назва, — виміряно як амплітудну характеристику в дБ.</strong> ⛔ Тест, що перевіряє лише те, що вихід <em>змінився</em>, проходить на еквалайзері, під'єднаному задом наперед. Низька полиця піднімає 50 Гц на 12 дБ, а 12 кГц зсуває менш ніж на пів децибела; середній пік зсуває власний центр і не чіпає обох країв; Q справді визначає ширину. І кожна смуга на 0 дБ — одинична: <code>resonator.rs</code> власними словами попереджає, що полиця й пік із двох різних виведень не дадуть у сумі пласкої характеристики, а приховав би це саме обхід рушія.","changelog.561660be824d":"<strong>Патч із полями <code>NaN</code> і нескінченностями все одно рендерить скінченний звук.</strong> ⛔ Підсилення навмисно ненульові, тож обхід пласкої АЧХ не може його врятувати, і роботу має зробити обмеження. Якщо видалити обмеження, у вихідну шину справді потрапляють нескінченні семпли — патч приходить із файлу проєкту, пресета чи блоба сесії, тож ці числа беруться з диска.","changelog.cf7a53067d45":"<strong>Патч, збережений до появи цього поля, як і раніше завантажується — і завантажується пласким</strong>, а це кожен файл проєкту, який продюсер уже має. ⚠ Тест перевіряє, що ключ <code>eq</code> знайдено, перш ніж його видалити, тож перейменування не може змусити тест тихо завантажувати сучасний документ і рапортувати про успіх.","changelog.5cfdbb31fdb6":"<strong><code>reset</code> очищує пам'ять регулятора тембру</strong> — а саме цим шляхом проходять усі 1 648 запечених ван-шотів, один за одним, через один рушій.","changelog.8db9ed06330a":"<strong>Коефіцієнти стежать за зміною частоти дискретизації</strong> — див. нижче.","changelog.844ddc7e034e":"⚠ <strong>Регулятор тембру недоступний з Oscillate</strong>, і це чесний стан, а не недогляд. Ніщо тут не записує <code>patch.fx.eq</code>, а пристрій інструмента не має для нього регулятора — це функція передньої панелі <code>Freally MIDI Master</code>, яка прийшла, бо крейт приходить цілим. Тож тут він назавжди плаский, тобто назавжди в обході. Перевірки вище існують для того, щоб у день, коли Oscillate <em>таки</em> його відкриє, обіцянка, з якою його імпортовано, вже виконувалася.","changelog.04a45d3f4f5f":"⛔ <strong>І два дефекти, знайдені під час написання цих перевірок, — обидва виправлені в першоджерелі й імпортовані назад.</strong> <code>SynthEngine::set_sample_rate</code> перебудовував голоси, затримку й реверберацію, але не регулятор тембру: перебудову захищала умова зміни <em>параметрів</em>, а частота дискретизації до них не належить, тож хост, що переходив 48 кГц → 96 кГц, лишав коефіцієнти, розраховані на 48 кГц, і кожна смуга опинялася на октаву нижче — полиця 6 кГц діяла на 3 кГц. ▶ <strong>В іншому продукті це живий дефект, а не теорія</strong>: його плагін викликає <code>set_sample_rate</code> під час ініціалізації, тож проєкт, відкритий на іншій частоті, вийшов би саме таким.","changelog.164f095fad5b":"⚠ Огляд умови-захисту для цього виправлення виявив другий дефект: вона запам'ятовувала <strong>обмежені</strong> параметри й порівнювала їх із <strong>необмеженим</strong> патчем, тож будь-який патч хоча б з одним числом поза діапазоном ніколи не збігався й перебудовувався на кожному блоці — три трансцендентні функції на смугу на канал, в аудіопотоці, протягом усього життя ноти. Саме цієї ціни захист і мав уникати — а її сплачували сповна.","changelog.462b8c4c398c":"▶ Обидва виправлено в <code>ff99972c</code>, і цей крейт містить виправлення. ⛔ <strong>Жоден не латали тут</strong> — TASK-077 саме про це правило: про дефект в імпортованому крейті повідомляють його першоджерелу, а виправлення повертається через повторний імпорт.","changelog.763976c39a5e":"⚠ <strong>Oscillate не міг натрапити на жоден</strong>: <code>prepare</code> перебудовує рушій, а не змінює його частоту, ніщо тут узагалі не викликає <code>set_sample_rate</code> у синтезатора, і ніщо не записує <code>patch.fx.eq</code>, тож каскад просто пропускається. Тест однаково лишено — у день, коли цей продукт відкриє регулятор, ніхто не згадає, що крейт колись тут помилявся.","changelog.748d76268df9":"Виправлено — перевірка, яка вимірювала машину","changelog.907c2f2fd645":"<strong>Перевірка вартості збереження в <code>the_profile</code> нестабільно падала, і її власні числа спростовували її повідомлення.</strong> Вона показала 1.007 мкс/операцію на 1 000 записів, <strong>4.399</strong> на 10 000 і 2.030 на 40 000, а тоді впала з повідомленням <em>«вартість однієї операції зростає разом із журналом»</em>. ⛔ Вартість, що зростає, не падає назад — найбільша вибірка показала менш ніж половину значення, на якому перевірка впала. Середній вимір був затримкою, знятою, коли <code>cargo-test-parallel</code> змусив цей бінарник ділити машину із сусідами на 265 с і 198 с.","changelog.f740ca8afb55":"⚠ <strong>Тепер три виміри, з яких береться найменший, а межа не змінилася.</strong> Шум планувальника, page fault і алокатор, що розширює свою арену, можуть лише <em>додати</em> час, тож мінімум — найближчий вимір реальної вартості. ▶ Доказ того, що це кращий вимір, а не м'якший: він дає <strong>0.484 мкс/операцію</strong> — саме ті <em>«приблизно пів мікросекунди»</em>, які власний коментар тесту документує відтоді, як його написали. Межа 2.0 зберігає наданий їй запас 4×.","changelog.ee0e7470e12b":"⚠ <strong>Найбільше це важить там, де воно не безкоштовне</strong> — той самий бінарник працює в завданні macOS із множником оплати 10×, де випадковий збій коштує грошей, а перезапуск означає, що людина вирішує їх витратити.","changelog.976e6e97f8a2":"Виправлено — два огляди і тридцять дефектів, які вони знайшли","changelog.db1222c7163d":"▶ <strong><code>/code-review</code> і <code>/security-review</code> по всьому дереву, а потім огляд під'єднання кожного елемента керування.</strong> Огляд безпеки не знайшов нічого, що можна було б використати для атаки. Два інші знайшли тридцять дефектів, і всі вони — одне й те саме, сказане трьома способами: механізм працює, але ніщо його не викликає.","changelog.7cf2cd2dae19":"<strong>Звук</strong>","changelog.6b2f9047e7fb":"<strong>Після розділення аудіокліпу обидві половини грали ті самі такти.</strong> <code>tail_of</code> зсував <code>content_offset_ticks</code>, а рушій читав <code>source_start_frame</code>, тож розріз восьмитактового дубля на п'ятому такті знову відтворював такти з першого по четвертий на місці п'ятого–восьмого, і справжній кінець дубля ставав недосяжним. ⚠ Тим самим шляхом проходять <em>розріз</em>, запис поверх дубля і перетягування лівого краю кліпу. Тепер ці два значення додає лише одне місце — <code>clipwindow.rs</code>.","changelog.2c8ea832888d":"<strong>Репітч разом із Реверсом виходив за кінець файлу в тишу</strong>, а Репітч разом із Повтором мовчки нічого не робив. Редактор завжди вимикав цей режим для обох поєднань; рушій цього ніколи не перевіряв.","changelog.776681ae58b6":"<strong>Клацання приблизно на 85-й мс кожного кліпу з репітчем</strong>, що починався з початку свого файлу: ресемплер припускав вступну ділянку ядра, якої йому не дали, а на наступній межі фрагмента відскакував на неї назад.","changelog.025480518fc8":"<strong>Кнопка M барабанної доріжки та її група чоку зберігалися, але ніколи не відтворювалися.</strong> Заглушений хет усе одно звучав; два хети в групі 1 усе одно дзвеніли разом. Тепер обидва обробляє планувальник, тож закритий хет обриває відкритий.","changelog.00a6999c8a9e":"<strong>Елементи керування, які нікуди не вели</strong>","changelog.dcf104640213":"<strong>Усі десять параметрів Налаштування ▸ Експорт.</strong> Формат, розрядність, дизеринг, частота, три прапорці <em>Що записувати</em>, шаблон імен стемів, тека, нормалізація і хвіст записувалися в <code>preferences.json</code>, і їх не читало <strong>ніщо</strong>: єдиний експорт у продукті мав жорстко вшитий 24-бітний WAV і щоразу питав теку. Продюсер, який вибрав FLAC, отримував WAV, і ніщо про це не казало. ⚠ <em>Нормалізацію</em> і <strong>хвіст</strong> реверберації реалізовано заново, а не просто під'єднано, а <em>Що записувати → Мастер</em> тепер справді може створити той мікс, який типово завжди й запитувався.","changelog.59d90c6cb919":"<strong>Меню кліпу мало один пункт, хоча бекенд умів сім речей.</strong> <em>Заглушити цей кліп</em>: рушій враховує <code>Clip::muted</code> ще з фази 5, але жоден елемент керування не міг цього встановити, тож глушити можна було лише всю доріжку. <em>Зробити унікальним</em>, <em>Очистити комп</em>. Тепер меню відкривається й на порожньому кліпі.","changelog.e5b3cca1b7df":"<strong>Підсилення кліпу і slip-редагування</strong>, обидва в аудіоредакторі. Slip — найпоширеніша аудіоправка, а в продукті не було жодного способу її зробити.","changelog.6d771bdd8e51":"<strong>Групу пристроїв не можна було перейменувати</strong>, тож кожна група назавжди звалася <em>Нова група</em>. Двічі клацніть її назву.","changelog.467d149679e8":"<strong>Сітка прив'язки ніколи не зберігалася.</strong> Після кожного перезапуску вона поверталася до <em>Адаптивна</em> і різнилася між головним вікном і кожним відокремленим. ⚠ Тепер це параметр проєкту, що зберігається як <strong>режим</strong>, а не як кількість тіків: <em>адаптивна</em> — це правило щодо масштабу, а <em>такт</em> і <em>тріоль</em> залежать від розміру, тож жодне число не могло б утримати відповідь.","changelog.a5d42a8ae7a9":"<strong>Лічильник пропусків можна скинути</strong> — натисніть на нього. Лічильник, що накопичується від запуску, не скаже продюсерові, чи допоміг щойно змінений розмір буфера.","changelog.ba7c289f15f7":"<strong>Вікно плагіна в хості можна закрити</strong>, а не лише відкрити.","changelog.2cb47acac22e":"<strong><code>Ctrl</code>+<code>2</code> нічого не робило.</strong> Комбінацію було вказано в налаштуваннях і надруковано в підказці кнопки «Патерни», а перемикала вона параметр, який рамка вікна вже перестала читати.","changelog.e50883a683a3":"<strong>Налаштування ▸ Клавіатурні скорочення показували сирий ключ перекладу</strong> як назву дії в рядку «Рек патернів» — усіма вісімнадцятьма мовами.","changelog.b14b86b1382f":"<strong>Те, що зламалося б на чужій машині</strong>","changelog.66c3c6c5267c":"<strong>Кожна збірка для macOS була зламана.</strong> <code>include_bytes!</code> вказував на PNG заставки, видалений разом з анімацією, до якої він належав, — жорстка помилка компіляції на єдиній платформі, яку машина з Windows ніколи не компілює.","changelog.0baaabb3b598":"<strong>Робочий процес релізу ніколи не міг завершити чернетку.</strong> Він збирав лише на трьох раннерах, а маніфест оновлювача досі вимагав усіх чотирьох платформ, тож крок щоразу завершувався з кодом 1. Тепер реліз оголошує, які платформи він охоплює, і великими літерами каже, що залишає без оновлень.","changelog.8427ce0ef17b":"<strong>Дві перевірки CI не запускалися ніде</strong> — перевірка типу ретранслятора і перевірка ліцензії інсталятора, — хоча заголовок самого робочого процесу стверджував, що запускаються всі.","changelog.a778bef2ac7c":"<strong>Чесно про те, чого не зроблено</strong>","changelog.542fd1169d51":"<strong>Доріжка CC каже, що не відтворюється.</strong> Криву малюють, фіксують, зберігають і зчитують назад, але жоден інструмент її не читає: <code>NoteMessage</code> не має варіанта для контролера, і жоден пристрій не має елемента керування, на який його можна призначити. Доріжка й далі працює як редактор, але більше не створює враження, що її чути.","changelog.2a6141e43be0":"Змінено","changelog.19d2f3668484":"<strong>Питання про оновлення під час першого запуску блокує і клавіатуру, і мишу.</strong> Його затемнення зупиняло лише клацання, тож <code>Space</code> запускав транспорт, а <code>B</code> вибирав лезо позаду діалогу, який мав блокувати вікно.","changelog.4408a66cf4a7":"<strong>Перетягування фейдерів і ручок надсилає записи по одному.</strong> Кожен запис був окремим завданням, 60–120 на секунду, а фіксація не атомарна, тож перетягування зі зміною напрямку могло застосувати значення <strong>у зворотному порядку</strong> й залишити фейдер на значенні, яке рука вже минула.","changelog.a76424b61990":"<strong>Типове значення <code>Writes</code> — усі три.</strong> Раніше це був лише мастер (під діалог зведення, якого так і не зробили), хоча єдиний експорт цього продукту — супровідна тека, а вся її специфікація — це стеми та MIDI.","changelog.4118fb4fed0e":"Вилучено","changelog.15b34653c2d8":"<code>ArrangementEdit::SetClipLoop</code> — другий вхід через шов до поля, яким уже володіє <em>Повторювати</em> в аудіоредакторі. Два входи до одного поля можуть розійтися.","changelog.87ab637f8719":"П'ять зареєстрованих команд, до яких ніщо не могло дістатися, серед них цілий другий шлях запису, що дублював упорядкування, яким володіє <code>transport_toggle_record</code>.","changelog.840e2d665a01":"<code>InputRouting::midi_channel</code> — його ніде не записували й не читали, а поле у форматі файлу натякає, що така функція існує.","changelog.68ff7b9f2a51":"Мертва друга копія навігації файлового браузера і дублікат логотипа рядка стану на 1.4 МБ, який ніщо не імпортувало.","changelog.5804894b279c":"Додано — п'ять перевірок, і доведено, що кожна падає на дефекті, заради якого її написали","changelog.cbc111af658b":"▶ <strong>Огляди знайшли дефекти; ці перевірки знайдуть наступні.</strong>","changelog.0ced7e4acc29":"<strong>Кожну зареєстровану <code>#[tauri::command]</code> щось викликає.</strong> Наявна перевірка звіряла оголошені↔зареєстровані в обидва боки і не бачила випадку, який огляд насправді знайшов сім разів.","changelog.bfa23431d44f":"<strong>Кожен шлях <code>include_bytes!</code> у дереві Rust існує</strong> — його читають як текст, тож перевірка бачить і рядки, яких збірка під Windows ніколи не компілює.","changelog.82c650a2453e":"<strong>Кожна перевірка, яку визначає <code>ci:local</code>, запускається в CI або пояснює, чому ні.</strong>","changelog.bbe1d90a6900":"<strong>Кожен шлях, названий у <code>tauri.conf.json</code>, існує</strong>, а графіка інсталятора справді є растровим зображенням.","changelog.35eba3face11":"<strong>Типові значення експорту однакові в Rust і TypeScript.</strong> <code>preferences.ts</code> стверджував, що їх узгоджує перевірка. Такого тесту не існувало, і значення вже розійшлися.","changelog.601f1c69bd48":"Переклади комбінацій клавіш тепер <strong>виводяться з таблиці прив'язок</strong>, а не перелічуються вручну. Рукописний список відставав на вісімнадцять ідентифікаторів.","changelog.b9d982ea6bd7":"Додано — дев'ять речей, яких не вмів piano roll","changelog.1f9c5a34c9d1":"▶ <strong>Розрив між piano roll в Oscillate і тим, який продюсер уже знає.</strong> Їх дев'ять, і жодна не є параметром: кожна — це жест, який або існує, або ні.","changelog.d5a043ed3427":"<strong>Примарні ноти.</strong> Інші патерни на стрічці часу, намальовані позаду того, який ви редагуєте, тож басову лінію можна писати проти акордів, під якими вона звучить. ⚠ <strong>Вирівнювання за СТРІЧКОЮ ЧАСУ</strong>, а не від нульового тіку до нульового тіку: примарна нота стоїть там, де справді звучить, тож перетягування її кліпу зсуває те, що ви бачите. Їх малюють без ідентифікаторів нот, тому їх не можна клацнути, перетягнути чи видалити — випадково відредагувати не той патерн неможливо.","changelog.acb285536839":"<strong>Імовірність для кожної ноти.</strong> Нота з <code>chance: 60</code> звучить шість разів із десяти. ⚠ Кидок <strong>детермінований</strong>: та сама нота на тому самому місці відповідає однаково під час кожного рендеру, тож зведення звучить як прослуховування, — а відповідь змінюється на кожному колі <strong>дужки циклу</strong>, і саме так ви це чуєте.","changelog.91a46043d207":"<strong>Відхилення велосіті для кожної ноти.</strong> Напівширина навколо власної велосіті ноти, тож партія хетів дихає, і її не треба перемальовувати. Обидва поля мають у piano roll власну доріжку поруч із доріжкою велосіті.","changelog.ae227f69dad4":"<strong>Арпеджіо, бій, форшлаг і нарізка</strong> — чотири інструменти, що перетворюють одне виділення на багато нот. ⚠ <em>Бій</em> зсуває кожну атаку й лишає на місці кожен <strong>кінець</strong>, тож акорд усе одно завершується разом; <em>арпеджіо</em> зсуває всю ноту.","changelog.7567510c9217":"<strong>Штамп акорду.</strong> Намалюйте одну ноту — отримайте акорд. Основний тон лишається тією самою нотою, тож скасування та повторне редагування працюють як слід; інтервал, що вийшов би за межі клавіатури, відкидається, а не загортається в неправильну октаву.","changelog.a5716970627f":"<strong>Склеювання.</strong> Об'єднує ноти однакової висоти, які справді стикаються. Окремо для кожної висоти й ніколи поза зовнішніми межами виділення.","changelog.6dca58299583":"<strong>Прослуховування за клацанням.</strong> Натисніть ноту — і почуєте її: вона звучить, поки ви тримаєте, і <strong>замовкає, щойно ви починаєте її перетягувати</strong>, тож переміщення ноти не перетворюється на потік висот. ⚠ Вона звучить на <strong>власній доріжці кліпу</strong>, а не на доріжці, підготовленій до запису.","changelog.d436aec70d34":"<strong>Редагування кількох кліпів.</strong> Виділіть кілька кліпів в аранжуванні, і інструмент piano roll дістане до всіх. ⛔ <strong>Окремо для кожного патерну, ніколи над їхнім об'єднанням</strong>: обернення двох кліпів як одного проміжку поміняло б їхній вміст місцями замість обернути кожен.","changelog.02c466c71f3d":"<strong>Блокування ладу</strong> <em>(на прохання власника)</em>. Коли воно ввімкнене, ніщо не потрапляє поза тональність: ні малювання, ні перетягування, ні жодне перетворення, ні ноти, зіграні з MIDI-клавіатури. ⚠ <strong>Барабанна доріжка — виняток</strong>, бо висоти в наборі — це слоти, а не ноти. Імпортовані файли <code>.mid</code> і правки учасників навмисно не зачіпаються: блокування стереже те, що граєте <em>ви</em>, і не переписує того, що вам дали.","changelog.c0a758a4c2c8":"Додано — ще три речі, про які власник попросив, поки будувалися ці","changelog.228a32503478":"<strong><code>[</code> і <code>]</code> на краях кліпу.</strong> Курсор ще до натискання показує, який край ви збираєтеся обрізати, а посередині повертається до курсора переміщення.","changelog.67dab04fd1a6":"<strong>Зведення виділеного в аудіо.</strong> Кілька MIDI-кліпів стають аудіофайлами одним натисканням, і <strong>одне скасування</strong> повертає їх усі як MIDI. ⚠ Рендер враховує імовірність і відхилення велосіті, тож аудіо — це саме те, що ви чули.","changelog.e79c873347d5":"<strong>Сторінка комбінацій клавіш і застосунок збігаються.</strong> Тест тепер порівнює прив'язки застосунку з таблицею в документації в обидва боки, тож прив'язка, додана без свого рядка, — або рядок, що лишився після переміщення прив'язки, — валить збірку, а не доходить до читача.","changelog.94af29dd35e5":"Змінено — чотирнадцять інструментів кажуть, чим вони є","changelog.dba1519e23b3":"▶ <strong>Власник, 2026-09-16:</strong> <em>«змініть усі назви моїх плагінів аудіо/MIDI-ефектів на звичайні назви, тільки не такі, як в Ableton/FL Studio, і те саме з усім іншим у моєму застосунку, що має стосунок до 'Kiln' чи чогось такого».</em>","changelog.da573c0bab5c":"Шістдесят один ефект перейменували на попередньому щаблі; інструменти лишилися з кодовими назвами на ковальську тему, і відкритим було питання, чи мають вони піти слідом. Пішли:","changelog.c973dfc231e6":"⚠ <strong>Три з них досі неактивні й пояснюють чому</strong>, і пояснюють уже під новими назвами: <code>Hardware Instrument</code> грає зовнішнім обладнанням через MIDI-порт, а MIDI-порту в Oscillate ще немає; <code>Track Replay</code> потребує власного записаного виходу цієї доріжки; <code>Folder Kit</code> потребує бібліотеки семплів продюсера, а це робота Провідника файлів.","changelog.759ed41312d0":"⚠ <strong>Змінився й один ефект.</strong> <code>Strum</code> тепер зветься <strong>Chord Strummer</strong>, бо в Live 12 є MIDI-трансформація, що зветься саме <em>Strum</em>, а вказівка прямо забороняла будь-яку їхню назву.","changelog.5bce801ca6dd":"⛔ <strong>Нічого з того, що зберігає файл проєкту, не змінилося.</strong> Змінилася лише показувана назва; кожен <code>type_id</code> — <code>crucible</code>, <code>flint</code>, <code>hammer</code> та інші — точно такий, як був, бо саме цей рядок є ключем, який несе збережений <code>.oscillate</code>. Продюсер, що відкриває проєкт минулого тижня, знаходить кожен пристрій там, де його залишив, з усіма налаштуваннями й автоматизацією. ⚠ Тож кодова назва, що вціліла в <code>type_id</code>, — не недогляд, який слід прибрати пізніше; прибрати її — це і є дефект, а <code>every_device_name_says_what_it_is.rs</code> фіксує всі п'ятнадцять.","changelog.a4c30729338f":"⚠ <strong>«Kiln» навмисно не чіпали</strong>, і варто сказати, де воно є: це взагалі не пристрій, а <em>«Kiln Gong»</em>, один пресет серед 1 648 в імпортованій заводській бібліотеці. Цю бібліотеку побайтово порівнюють із копією Freally MIDI Master, тож перейменування в ній створює форк імпорту й порушує обіцянку, що той самий <code>PresetId</code> звучить однаково в обох продуктах.","changelog.388337669577":"Додано — відновлення після збою дістається й до сесії, яку ніколи не зберігали","changelog.4e88f60bb868":"⛔⛔ <strong>Журнал має назву проєкту, якому належить, а в сесії, яку ніколи не зберігали, немає файлу проєкту, який можна було б знову відкрити</strong>, — тож наступний запуск створював новий проєкт із новим ідентифікатором і ніколи її не шукав. Робота весь час лежала на диску, і ніщо не пропонувало її повернути, — а це саме той продюсер, який працює з обіду й жодного разу не зберігся.","changelog.e842b6131eed":"✅ Тепер Oscillate під час першої правки записує в журнал знімок початкового стану незбереженої сесії, а запуску, який ще не почав власної роботи, пропонується найновіший осиротілий журнал, який можна відновити. ⚠ Діалог каже, яка це пропозиція: в осиротілого журналу немає збереженого файлу, тож звичайне заспокоєння — <em>«ваш збережений проєкт не змінено»</em> — описувало б файл, якого не існує.","changelog.7a6d58e08394":"⛔ <strong>Журнал без власного знімка ніколи не пропонується</strong>, бо немає збереженого проєкту, на який його можна відтворити, і результатом був би проєкт, якого ніколи не існувало. Пропозиція, яку вже прийняли чи відхилили, не повертається.","changelog.e51b2a693d90":"Відоме обмеження — довга сесія дає великий файл проєкту","changelog.7b7551a966b9":"⚠ <strong>Журнал операцій живе всередині <code>.oscillate</code> навмисно</strong>: саме він дає скасуванню пережити збереження й перезавантаження, і з нього виводяться і Перемотування сесії, і Таймлапс сесії. Ніщо його не обрізає, тож файл росте разом із сесією: виміряно <strong>29 МБ після 100 000 операцій і 58 МБ після 200 000</strong> — це приблизно восьмигодинна сесія, а записується файл за 67 мс.","changelog.2d5d351a5323":"▶ Зростання <strong>лінійне</strong>, а не наростаюче, і стелю задокументовано, а не обмежено: обрізання журналу прибрало б разом скасування після перезавантаження, Перемотування сесії і Таймлапс. ⛔ Рішення власника, 2026-09-15.","changelog.1bd930b6d7dc":"Змінено — браузер звужує вибірку в самому джерелі","changelog.ad56b31dd7dc":"⚠ <strong>Відкриття полиці в браузері більше не будує спершу весь перелік.</strong> Кожну з п'яти полиць — Інструменти та чотири Factory Expansion — показували, клонуючи всі 1 648 інструментів і відкидаючи чотири п'ятих, що належать іншим полицям, — і так за кожного показу. Тепер обходиться лише запитана полиця: <strong>0.140 мс → 0.001 мс</strong>, виміряно в релізній збірці для Інструментів, і щонайменше 1 298 виділень пам'яті під рядки, яких тепер щоразу не відбувається.","changelog.f69b8488a31f":"⛔ Це той самий дефект, який <code>Freally MIDI Master</code> виправив у першоджерелі того ж дня, і його обґрунтування прийшло разом з імпортом: список, звужений постфактум, будується повністю в <em>«потоці, з якого DAW малює своє вікно»</em>.","changelog.46a40063d923":"Виправлено — те, що знайшли огляди фази 11","changelog.92c5375cd4da":"⛔ <strong>Заставка на macOS затримувала застосунок на сім секунд під час кожного запуску.</strong> У нативному вікні немає сторінки, тож ніщо ніколи не викликало <code>splash_finished</code>, — а 4-секундний сторожовий таймер, написаний для <em>«сторінки, що викинула виняток»</em>, непомітно став звичайним шляхом на macOS. Тепер нативна заставка передає керування, щойно мине тривалість її власної анімації, а перевірка читає гілку macOS, щоб сторожовий таймер сторінки туди ніколи не повернувся.","changelog.fcfe9625c96b":"⛔ <strong>І вона показувала інший стрибок, ніж на Windows і Linux.</strong> Версія на Rust мала симетричну параболу там, де в таблиці стилів <code>51 − 17u − 78·sin(πu)</code>, зовсім не мала масштабування, мала інвертований знак вертикального зсуву і вікно на 62 % дисплея замість усього, — тож фігура пірнала замість стрибати, ніколи не наближалася до вас і обрізалася невидимою рамкою посеред робочого столу. Усі чотири вади виправлено, і <code>splash_macos.rs</code> тепер <strong>розбирає власні ключові кадри <code>window.css</code></strong> і падає, якщо дві реалізації розходяться хоча б в одній із двадцяти однієї вибірки.","changelog.9e463e8ee449":"⛔ <strong>Сайт документації лишався попередньою мовою, коли ви знову вибирали англійську.</strong> Кожен вузол, що перекладається, постачається з англійським текстом у розмітці, і перемикач розумів це як «для англійської робити нічого не треба», — тож вибір Français, а потім English залишав французьку сторінку під <code>lang=&quot;en&quot;</code>. Після арабської макет переставав бути дзеркальним, а текст лишався арабським. Тепер англійська — такий самий каталог, як і будь-який інший, і його один раз зчитують зі сторінки, перш ніж щось його перезапише.","changelog.704583748781":"⛔ <strong>Невдале завантаження оновлення викидало пропозицію, яку ви щойно переглянули</strong>, тож повторна спроба означала другий мережевий запит. ⚠ Крім того, панель <em>Оновлення</em> на кожній свіжій інсталяції оголошувала <em>«Ні до чого не зверталися.»</em> як живий результат під перемикачем, що вже казав <em>«Вимкнено.»</em>, — речення про те, чого ніхто не робив.","changelog.058de0de8dea":"⚠ Також: <code>--verify</code> без <code>--assets</code> повідомляв про катастрофу § F-32 для справного маніфесту звуків; виняток у <code>deny.toml</code> міг непомітно скасувати заборону GPL; <code>|</code> усередині фрагмента коду додавав стовпець до опублікованої таблиці; а три перевірки читали <code>main.rs</code> пошуком, на який міг відповісти коментар, який міг задовольнити метод із відступом, і — в одному випадку — з контролем проти хибної порожньої перевірки, що ніколи не доходив до гілки, яку охороняв.","changelog.16ca0f9a8fbd":"⛔ Заморожування функцій — 11 вересня 2026","changelog.ca13a48bad9c":"<strong>Список функцій закрито до стабільної <code>v1.0.0</code>.</strong> Відтепер надходять лише виправлення дефектів, посилення захисту, оптимізація, документація й локалізація. Ідея, що з'являється під час бети, отримує номер версії <em>після</em> 1.0, а не місце в ній: бета, набір функцій якої змінюється, — не бета, і звіти про помилки в ній перестають щось означати.","changelog.73951f911f5c":"⚠ <strong>Три речі, специфіковані до цієї межі, ще доробляються</strong>, і їх перенесено, а не вирізано: Таймлапс сесії, доставлення стемів MixSir і повідомлення про учасників, що відпали, у кімнаті. Перенести незавершену функцію — не те саме, що додати нову.","changelog.6293a41b4e75":"Додано — програма вміє оновлюватися сама, і з'явився посібник","changelog.ac19bec2400d":"<strong>Oscillate вміє оновлюватися сам і спершу питає.</strong> <em>Налаштування ▸ Оновлення</em> показує версію, яку ви запускаєте, кнопку <em>Перевірити оновлення</em>, точну адресу, до якої було б звернення, і час, коли таке звернення справді відбулося востаннє. ⛔ <strong>Нічого не відбувається, доки ви щось не натиснете.</strong> Перевірка під час запуску — це перемикач, і він <strong>вимкнений</strong>; коли він вимкнений, ні до чого не звертаються, панель не показує жодного результату, а <em>Остання перевірка</em> лишається <em>Ніколи</em>. ⛔ Панель ніколи не пише <em>«у вас найновіша версія»</em> поверх перевірки, якої не було: це різні факти, і правдивим був би лише один із них.","changelog.2d43b4efba6d":"⚠ <strong>Що надсилає перевірка: нічого.</strong> Вона запитує один статичний файл і не несе жодних відомостей про вас, цю машину чи ваші проєкти. Коли оновлення знайдено, вам показують версію, дату, список змін і розмір, і вибираєте ви. ⛔ <strong>Кожне оновлення підписане</strong>, а те, чий підпис не проходить перевірку, відхиляється з помилкою, а не встановлюється, — обійти цю перевірку немає як.","changelog.fc410aff2057":"⛔ <strong>Через це виправлено два речення, і обидва вже постачалися.</strong> Налаштування казали <em>«жодного облікового запису, жодної телеметрії, жодних автоматичних з'єднань»</em> вісімнадцятьма мовами, і угода казала те саме. Перевірка під час запуску, яку ви ввімкнули, <strong>є</strong> автоматичним з'єднанням, тож обидва тексти тепер кажуть, що Oscillate не робить <em>жодного з'єднання, про яке ви не просили</em>, і називають три випадки, коли він узагалі користується мережею.","changelog.459ef05e4504":"<strong>Сайт документації вісімнадцятьма мовами.</strong> Головна, повний посібник, список змін і драбина версій — без CDN, аналітики, трекерів, вбудованих шрифтів і будь-яких сторонніх скриптів; це та сама обіцянка, яку дає застосунок, і її забезпечує складальна перевірка, а не лише заява. ⛔ <strong>Завантажень на ньому немає і не буде до <code>v1.0.0</code>.</strong> Сторінку завантаження зібрано, вона прямо каже, що там поки нічого немає, і на неї немає посилань.","changelog.51a624b39021":"<strong>Кожну задокументовану процедуру проілюстровано справжнім знімком екрана справжньої збірки</strong>: те, що вам кажуть натиснути, обведено червоним і пронумеровано. Знімки робить безголовий прохід по зібраному фронтенду, їх ніколи не малюють вручну й перевіряють під час кожного запуску, тож зображення збірки, якої вже не існує, не може вціліти.","changelog.84b4b10ce168":"<strong>Нативна заставка на macOS.</strong> Та сама фігура й той самий стрибок, але намальовані AppKit замість другого вебперегляду, — і це дало змогу позбутися єдиного приватного API Apple, яким користувався продукт. ⚠ Приватний виклик — це виклик, який Apple може прибрати в проміжному релізі; якби це сталося під час бети, кожен Mac малював би непрозорий прямокутник поверх робочого столу. Windows і Linux не змінилися.","changelog.1246fc93bca0":"Виправлено","changelog.4c1daaca8982":"⛔ **Кнопка <em>Відкрити заповнений звіт на GitHub</em> у застосунку вела в нікуди.** Вона вказувала на попереднього власника репозиторію, тож кожен продюсер, який нею скористався, — а це єдиний шлях, заради якого існує весь механізм звітів про збої, — отримував 404 уже після того, як написав звіт. Хост плагінів представлявся плагінам CLAP тією самою мертвою адресою.","changelog.fdc84a95e8eb":"⚠ <strong><code>v0.4.5</code> бракувало в опублікованій драбині версій</strong>, а також у приватній, хоча фазу за нею збудовано ще 2026-09-04. Тепер обидві драбини генеруються з одного файлу й звіряються під час кожної збірки.","changelog.70e390902fc1":"Додано — їх можна бачити, чути, передати їм доріжку й надрукувати, хто що написав","changelog.0ff6295aa3e0":"⛔⛔ <strong>Голос, камера й показ екрана на панелі кімнати.</strong> Натисніть <em>Говорити</em> — і інші вас чують; натисніть <em>Камера</em> — і вони вас бачать. Показувати екран може лише одна людина водночас. ⚠ <strong>Мікрофон і камера вимкнені, доки ви щось не натиснете, і Oscillate типово відмовляє їм у доступі</strong>: застосунок зберігає власну згоду, а вебперегляд запитує операційну систему лише після того, як ви сказали «так». Закриття кімнати або вимкнення елемента керування зупиняє медіапотік, і саме це гасить індикатор на пристрої.","changelog.58fe9d7d8f57":"⚠ <strong>Ніщо з камери чи мікрофона не записується, не буферизується на диск і не надсилається нікуди, крім учасників вашої кімнати.</strong> Сервера на шляху немає. ⚠ Показ екрана передає <strong>лише відео</strong>: усе, що грає на вашому комп'ютері, зокрема музика, яку написали не ви, лишається на вашій машині.","changelog.3b3fa07d1428":"⛔ <strong>Показ екрана — лише на Windows і Linux.</strong> На macOS немає способу захопити екран із вбудованого вебперегляду без приватного API в нотаризованому бінарнику, тож кнопки там немає, і замість збою після натискання сказано чому.","changelog.8b18ea1e7eeb":"⛔⛔ <strong>Передавання — віддайте одну доріжку комусь і заберіть її назад однією клавішею.</strong> Поки людина тримає доріжку, писати в неї може <strong>лише</strong> вона, <em>навіть не ви</em>: ваші власні правки цієї доріжки відхиляються, доки ви її не заберете. ⚠ І утримання не лише виключне, а й <strong>обмежувальне</strong>: ця людина може писати в цю доріжку й більше ні в що. Передати басову лінію — не означає передати сесію.","changelog.52c632003a26":"⚠ <strong>Забрати доріжку назад — це позначка часу, а не перемикач.</strong> Правка, зроблена до того, як людина могла про це дізнатися, лишається її правкою й застосовується; зроблена після — ні. Відхилити все, що вже в дорозі, означало б карати когось за швидкість світла.","changelog.d460b43b1bf3":"⛔ <strong>Утримання зобов'язує лише машину, яка його надала</strong>, і триває рівно стільки, скільки з'єднання. Хто відключився, той нічого не утримує, — інакше вихід із кімнати заблокував би вам власну доріжку до кінця сесії.","changelog.8d5007a0052a":"⛔⛔ <strong>Куміте — біт-батл, у якому кожен хід володіє власними тактами.</strong> Кожен хід отримує окремий відрізок стрічки часу, зафіксований на початку батлу, тож <em>чий зараз хід</em> і <em>у межах його діапазону</em> — це одне й те саме питання. ⚠ <strong>Зворотний відлік на екрані нічого не блокує, і це навмисно</strong>: перевірка за настінним годинником дала б двом комп'ютерам дійти протилежних висновків щодо тієї самої правки, і два проєкти непомітно розійшлися б. Затягувати час нічого не дає, і немає ходу, який можна захопити чи відмовитися віддати.","changelog.884f0b382cfc":"⚠ <strong>Вікна тактів охоплюють розміщення кліпів.</strong> Патерни, доріжки, автоматизація, доріжки CC і барабанні доріжки за своєю будовою охоплюють усю стрічку часу й лишаються під правилом «перемагає останній запис»; панель про це каже, а не лишає вам це відкривати.","changelog.a7e65a956e7d":"⛔⛔ <strong>Розподіл авторства виводиться, і робота, яку ви скасували, не зараховується.</strong> Скасування — звичайна операція в журналі, тож наївний підрахунок зарахував би продюсерові вісім нот, які він скасував, — і зарахував би двічі: раз за роботу й раз за скасування. Повтор теж ураховано: робота, скасована й потім повторена, зараховується знову. ⚠ Для кожного автора: операції, ноти, кліпи, пристрої та доріжки, яких він торкався, а частки в сумі дають загальне число, частками якого вони є.","changelog.2b918a7903cf":"⚠ <strong>Виведений факт не можна ввести вручну.</strong> <code>Contribution</code> не містить жодного тексту — лише ідентифікатори, цілі числа й позначки часу — і не має десеріалізатора, тож ніколи не може надійти з файлу, від учасника чи зі сторінки. Його можна лише обчислити. Імена підставляються на межі, за ідентифікаторами, а автор, до якого в цієї машини немає каналу, зберігає свій ідентифікатор, а не позичає чужий псевдонім.","changelog.a0d3d98f71d7":"⚠ <strong>Експорту в Markdown, CSV і PDF ще немає</strong>, як і редагованого стовпця з відсотками. Постачається саме виведення, на екрані.","changelog.f4799f613685":"Змінено — учасник не може говорити від чужого імені","changelog.d169d798cfa7":"⛔⛔ <strong>Ідентичність — це з'єднання, а не поле в повідомленні.</strong> До цього релізу автором операції був рядок, який вибирав відправник: стара перевірка відхиляла лише операцію, що видавала себе за <em>вас</em>, і нічого не робила з учасником, який ставив на неї ідентичність <strong>третьої особи</strong>. Через це передану доріжку, хід у батлі й рядок авторства можна було б підробити одним рядком кожен.","changelog.e345cf9eb7ad":"▶ У кімнаті немає облікових записів, і ніщо не могло б підписати повідомлення, тож Oscillate користується єдиним, що може знати: з'єднанням, яким байти фізично прийшли. Перше повідомлення в з'єднанні представляє, хто говорить, а після цього <strong>жодна половина цієї пари не може змінитися</strong>: з'єднання не може себе перейменувати, а нове з'єднання не може видавати себе за когось, кого Oscillate уже чує. ⚠ Ідентичності, якої ще не бачили, вірять, коли вона заговорить уперше; без облікових записів кращого немає, а вдавати інакше було б гірше за саме обмеження.","changelog.e4feb5900f76":"⛔ <strong>Відмова більше не є штрафним балом.</strong> Три штрафи відключають учасника, і раніше зараховувалася кожна відмова в дозволі, — тож той, чий зворотний відлік казав, що сигнал ще не пролунав, або чий дозвіл щойно відкликали, збирав штрафи за поведінку, точнісінько передбачену задумом. Тепер зараховується лише пошкоджене чи підроблене повідомлення, і цю різницю забезпечує помилка компіляції, а не коментар.","changelog.bdb9d0d768f8":"Виправлено — п'ять глухих кутів на панелі кімнати","changelog.c26c74c2acfa":"⛔⛔ <strong>Згорнуту ділянку можна знову відкрити.</strong> Панель кімнати ховається, коли ширина менша за 1180 CSS-пікселів, а її кнопка в заголовку вікна була <strong>неактивна</strong>, — але ноутбук на 1280 пікселів із типовим масштабуванням Windows повідомляє приблизно 853, тож на звичайній машині <strong>відкрити кімнату було взагалі неможливо</strong>. Тепер згортання — це типове значення, яке можна скасувати. Тісно, але придатно — краще, ніж правильно, але недосяжно.","changelog.68ce629f09b9":"⛔ <strong>З напівствореної кімнати є шлях назад.</strong> Продюсер, який натиснув <em>Створити</em>, а потім захотів натомість приєднатися до кімнати друга, застрягав: ні поля для приєднання, ні кнопки <em>Покинути</em>, ні нічого, що повернуло б панель на початок. Єдиним виходом був перезапуск застосунку.","changelog.9a716d44d5e3":"⛔ <strong>Під названою причиною збою тепер є кнопка.</strong> Коли з'єднання нормально зібрало кандидатів, а потім так і не відкрилося, панель показувала точне пояснення остаточного збою, але натиснути було нічого — <em>той самий спінер, тільки з додатковими кроками</em>.","changelog.e95b50b168e7":"⛔ <strong>Порожній код — це відмова, а не код.</strong> Без бекенда панель показувала порожнє поле з активною кнопкою <em>Копіювати</em> і попередженням <em>ставтеся до цього як до пароля</em> поруч.","changelog.2efd7314519c":"⚠ <em>«Проєкт приймається…»</em> більше не висить над бездіяльною панеллю, а другий і третій учасники, що приєднуються, отримують порожнє поле для вставлення замість тексту попереднього.","changelog.0294d79bbe62":"Додано — одна клавіша перетворює сесію на те, що можна опублікувати","changelog.2b19ee32f945":"⛔⛔ <strong>Картки сесії.</strong> Натисніть <code>Ctrl/Cmd+Shift+C</code> або Файл ▸ <em>Картка сесії…</em>, і Oscillate намалює зображення сесії 1200×630: темп, тональність, кількість доріжок і кліпів, тривалість, обрис аранжування та знак Oscillate. Збережіть або скопіюйте його й опублікуйте.","changelog.789fdbc637f7":"⛔ <strong>Код кімнати типово вимкнено</strong>, а попередження стоїть поруч із його перемикачем, а не в підказці: <strong>ставтеся до нього як до пароля — будь-хто, хто його побачить, може приєднатися.</strong> Коли кімнату не відкрито, перемикач так і каже, а не стоїть сірим без пояснень.","changelog.70bf28ecdf8d":"⛔ <strong>Картка не може видати нічого про вашу машину, і це властивість задуму, а не фільтра.</strong> У фактах, з яких будується картка, <strong>немає місця для тексту</strong>: ні назви проєкту, ні назви доріжки, ні назви семплу, ні шляху. Немає очищувача, який міг би помилитися, бо очищувати нічого.","changelog.2ffea8d2ddec":"⚠ <strong>Зберегти — кнопка, яка працює завжди.</strong> Чи дозволить ця платформа Oscillate покласти зображення в буфер обміну, ми обіцяти не можемо, тож <em>Копіювати</em> прямо каже, коли не вдалося, а не вдає, що спрацювало.","changelog.49b5e00378e0":"⚠ Обрис малюється з усього аранжування, а не з видимої частини, — тож та сама сесія двічі дає ту саму картку.","changelog.5eabaf9d3bff":"Додано — вашу сесію можна відкрити без Oscillate","changelog.85583a70d607":"⛔⛔ <strong>Файл ▸ Експортувати супровідну теку…</strong> перетворює сесію на теку звичайних файлів: стем на всю довжину для кожної доріжки, MIDI-файл для кожної партії, усі партії в одному <code>.mid</code> типу 1, карту темпу і README, який усе це пояснює. <strong>Скрізь деінде файли проєктів тримають вас у заручниках.</strong> Співавтор без Oscillate кидає стеми на такт 1, і вони збігаються.","changelog.b3048638cc00":"▶ <strong>Кожен стем завдовжки з усю пісню</strong>, тож нічого не доводиться підсовувати на місце.","changelog.353e48b03b6b":"⛔ <strong>Заглушену партію рендерять і підписують, а не тихо пропускають.</strong> Віддати комусь правильно названий файл правильної довжини, у якому тиша, — найгірший спосіб пропустити доріжку, бо виглядає все правильно, — тож Oscillate все одно її рендерить і вносить у README до розділу <em>MUTED PARTS</em>, щоб ви заглушили її знову, якщо хочете саме те, що звучало.","changelog.a9bc3aab7e27":"⛔ <strong>README каже й про те, чого в теці НЕМАЄ.</strong> Oscillate рендерить ці стеми без жодного VST 3 чи CLAP, що були в сесії: власні пристрої Oscillate входять, плагіни — ні, — і співавтор, який отримав партію, що звучить не так, заслуговує знати чому, а не гадати. Це обмеження записано у файл, який створює кожен експорт.","changelog.83bc1a94a3b0":"⚠ <strong>Сесію, довшу за десять хвилин, так експортувати поки не можна</strong>, і про це сказано, а не створено щось обрізане.","changelog.76f000611d9c":"Додано — мастер каже, що з ним зробить кожен сервіс","changelog.c8f1227e67e3":"⛔⛔ <strong>Чесні вимірювання мастера.</strong> Натисніть <strong>Гучність</strong> у мікшері, і Oscillate покаже інтегральну, короткочасну й миттєву гучність мастера в LUFS, його діапазон гучності та <strong>істинний пік у dBTP</strong>, а поруч із опублікованою ціллю кожного сервісу — що цей сервіс насправді зробить із цим мастером. Мастер на −9.16 LUFS проти −14 у Spotify буде <strong>приглушено на 4.84 дБ</strong>, і панель каже це саме такими словами.","changelog.fdb6d3d5fb12":"▶ <strong>LUFS є в усіх. Ніхто не каже, що це означає там, куди йде запис.</strong> Ця таблиця — суть функції.","changelog.e3f75c74b59a":"⛔ <strong>Істинний пік — не пік семплів, а досі Oscillate мав лише другий.</strong> Перетворювач відновлює хвилю <em>крізь</em> семпли, і ця хвиля може піднятися вище за найвищий із них, — тож лімітер, налаштований за піком семплів, кліпує під час відтворення, хоча індикатор показує −0.1. Тепер Oscillate вимірює з 4× передискретизацією, як вимагає ITU-R BS.1770-4, і показує результат у dBTP, тож сама одиниця каже, на яке число ви дивитеся.","changelog.db653ea0e802":"⛔ <strong>Ціль — не правило, і кожен рядок каже, що саме це.</strong> Більшість із них — нормалізація під час відтворення, яку слухач може вимкнути; дві — EBU R 128 і ATSC A/85 — справжні специфікації для здачі матеріалу. Примітка є частиною рядка, а не підказкою, яку треба шукати. ⚠ Таблиця живе в <code>data/loudness-targets.json</code> разом із датою останньої перевірки, бо ці значення змінюються.","changelog.721221e316a5":"⛔ <strong>Завжди два десяткові знаки, а значення, якого ніхто не виміряв, — це тире, а не число.</strong> Індикатор, що округлює так, щоб лестити, — це індикатор, який ввічливо бреше, а «−200.00 LUFS» — це вимірювання нічого.","changelog.b4bf7c9e9637":"⚠ <strong>Типово вимкнено, бо це забирає процесорний час</strong>, і кнопка про це каже.","changelog.b0bc2e5d54c5":"Додано — мікшер може сказати, які дві доріжки б'ються між собою","changelog.92a06653ecc1":"⛔⛔ <strong>Радар маскування.</strong> Натисніть <strong>Радар</strong> у мікшері, і Oscillate перелічить пари доріжок, що займають ту саму частину спектра, від найгірших, і назве смугу, де вони стикаються. Клацніть рядок — і він перенесе вас до однієї з них.","changelog.2e33bd64d89d":"▶ <strong>Це арифметика, і панель так прямо й каже.</strong> Звук кожної доріжки зводиться до енергій у тридцяти одній третинооктавній смузі; дві доріжки отримують високу оцінку в смузі, коли їхні енергії <em>схожі</em> і обидві <em>справді присутні</em>, а зіткнення — це пара, яка трималася так півтори секунди. iZotope бере гроші за індикатор маскування й спирається на машинне навчання; тут — розрахунок перекриття, що йде в комплекті, і підказка так і каже, а не натякає на інше.","changelog.e7e45a4d31f7":"⛔ <strong>Типово вимкнено, бо це забирає процесорний час</strong>, і кнопка каже про це ще до натискання. Вимкнення звільняє аналізатори й зупиняє захоплення в аудіопотоці — вимкнено означає справді вимкнено.","changelog.0acfd6d0ea4c":"⛔ **Пара, якої Oscillate ще не чув, позначається як <em>ще не почуто</em>, а не як чиста.** Дві доріжки, що не видали жодного звуку, — це не дві доріжки, перевірка яких виявилася чистою, і панель, яка повідомляла б друге, маючи на увазі перше, робила б твердження, якого ніхто не вимірював.","changelog.dd554854708c":"⚠ <strong>Чого ще немає — прямо.</strong> Немає кнопки <em>Порадити</em>: радар показує, де перекриття, і не пропонує зміни еквалайзера, а клацання рядка вибирає одну з двох доріжок, а не відкриває обидві. А сесію з понад тридцятьма двома доріжками відстежують лише до цієї межі — панель так і каже, а не показує решту як чисті.","changelog.766ccc081745":"Додано — збірка тепер відхиляє функцію, до якої застосунок не може дістатися","changelog.d340e8a8a795":"⛔⛔ <strong><code>check-commands.mjs</code>: кожна <code>#[tauri::command]</code> має бути в <code>generate_handler!</code>.</strong> Це перевірка проти <strong>дефекту, який цей проєкт постачав частіше за будь-який інший</strong>: механізм, що пережив своє єдине місце виклику, — сімнадцять зафіксованих випадків. Команда, якої бракує в цьому переліку, <strong>компілюється, проходить clippy, проходить <code>cargo test</code> і не існує для сторінки</strong>: ні помилки, ні попередження, ні тесту, що падає, — просто функція, якої мовчки немає в застосунку, що постачається. Одного разу так стала недосяжною ціла фаза.","changelog.6a242e5b8d08":"▸ <strong>Вона падає в обох напрямках</strong>: на команді, яку ніхто не зареєстрував, і на назві, що лишилася в переліку після того, як її функцію перейменували. ▸ <strong>Вона не може збігтися з власним текстом.</strong> Очевидна версія такої перевірки шукає назву команди grep-ом і тому знаходить саме оголошення <code>fn</code>, пропускаючи те, що мала б ловити; ця ж порівнює дві <em>множини</em>, тож немає пошуку підрядка, який можна обдурити. ▸ <strong>І вона відмовляється звітувати про чистий прохід по порожнечі</strong>: якщо будь-яка зі сторін розбирається менш ніж на сотню записів, розбір зламано, і перевірка падає, а не каже «чисто». Перевірка, що проходить, нічого не знайшовши, гірша за відсутність перевірки, бо їй вірять.","changelog.368c3ca85aec":"⚠ Вона запускається в <code>npm run ci:local</code> і в завданні CI з ланцюжка постачання. До коміту бачили, як вона червоніє в обох напрямках, а дерево, яке вона стереже, наразі чисте: <strong>163 оголошено, 163 зареєстровано</strong>.","changelog.c791e210b65a":"Додано — ваші слова на стрічці часу, і дубль пам'ятає, які саме","changelog.f5e9ebab3d41":"⛔⛔ <strong>Доріжка тексту.</strong> Натисніть кнопку тексту на панелі інструментів аранжування, і під лінійкою відкриється смуга з вашими словами, розкладеними вздовж пісні. Поточний рядок малюється акцентним кольором, а склад, над яким стоїть курсор відтворення, підсвічується, коли курсор його минає, — це зчитується з <strong>того самого тіку, з якого малюється курсор відтворення</strong>, шістдесят разів на секунду, а не за таймером. Суфлер, що відстає від транспорту, — це єдине, чого ця функція ніколи не має допускати.","changelog.47d04dae6e96":"▸ <strong>Імпорт <code>.txt</code> або <code>.lrc</code>.</strong> <code>.lrc</code> із таймінгом лягає на ті такти, на яких його співали: його мітки <code>[mm:ss.xx]</code> перераховуються через карту темпу вашого проєкту, тож пісня, що сповільнюється на дев'ятому такті, усе одно збігається. Текст без таймінгу розподіляється по секції, і ви підсуваєте кожен рядок на місце по такту за раз, і кожен зсув скасовується одним натисканням. ⚠ Слова з файлу копіюються у ваш проєкт; на сам файл більше ніколи не посилаються, тож аркуш, який ви перетягли з теки завантажень, не спорожніє наступного тижня.","changelog.9ed712d8b53f":"▸ <strong>Дубль пам'ятає слова, під які його співали.</strong> Коли запис з'являється, він зберігає, який аркуш був на екрані, тож комп із чотирьох дублів несе правильний куплет у кожній ділянці. ⛔ <strong>І переписування рядка не переписує історії</strong>: перша правка після появи дубля зберігає для нього старі слова й дає вам новий аркуш для роботи. Видалення аркуша, на який посилаються дублі, питає двічі й каже, скільки їх.","changelog.c7fbbc8b0881":"⚠ <strong>Ще не зроблено</strong>: перетягування рядка вказівником (сьогодні рядок рухають кнопки зсуву) і ручне розбиття рядка на склади.","changelog.eda939abbe78":"Додано — суфлер, який видно з іншого кінця кімнати","changelog.9c8a4a093ca5":"⛔⛔ <strong>Три способи бачити слова, і жоден не потребує другого екрана.</strong> Значок тексту на панелі інструментів аранжування, як і раніше, відкриває їх <strong>вбудовано</strong> в доріжку. Поруч із кнопкою запису тепер є ще два: <strong>Телесуфлер</strong>, що піднімає великий плаваючий суфлер над сесією, і <strong>⇱</strong>, що переносить його в <strong>окреме вікно</strong> для другого дисплея. Усі три малюють ті самі слова з того самого тіку — того, з якого малюється курсор відтворення, — тож доріжка й суфлер ніколи не розійдуться в тому, на якому рядку ви зараз.","changelog.162980882b3e":"▸ <strong>Шрифт розміром для мікрофонної стійки, а не для письмового стола.</strong> Найменший розмір суфлера більш ніж утричі перевищує розмір основного тексту застосунку, а повзунок звідти лише збільшує. Цю нижню межу забезпечено двічі, у коді й у таблиці стилів, і її <em>вимірюють</em> у справжньому браузері, а не просто оголошують, — бо розмір, який записали й ніколи не застосували, виглядає точнісінько як робочий.","changelog.bc3bce45fb64":"▸ <strong>Дзеркально — для скла телесуфлера.</strong> Слова виходять на екрані навиворіт, щоб скло розвернуло їх правильно для співака. ⚠ Елементи керування ніколи не віддзеркалюються: повзунок, у який не можна поцілити, гірший за відсутність повзунка.","changelog.b5cab03de549":"▸ <strong>Високий контраст</strong> — біле на чорному в обох темах, 21:1, що значно перевищує найсуворішу планку доступності. Поточний склад зберігає свій акцентний колір і підкреслення.","changelog.09c361712c76":"▸ <strong>Швидкість прокручування</strong>, і вона чесна щодо того, що робить: <em>коли</em> рядок стає поточним, вирішує транспорт, тож цей параметр змінює лише те, як швидко колонка до нього доїжджає, — від миттєвого переходу до повільного ковзання. Ніщо тут не керується годинником.","changelog.03410a1b5d7b":"<code>Esc</code> прибирає плаваючий суфлер. Кнопка ⇲ відокремленого вікна ховає його, тож він повертається саме туди й таким, яким ви його залишили.","changelog.18c67528e236":"Змінено — сторінка подяк перестала перебільшувати те, що постачається","changelog.509f0435939b":"⛔⛔ <strong>Там було написано «926 компонентів». 360 із них — інструменти збирання, яких в Oscillate взагалі немає</strong>: компілятори й засоби запуску тестів, якими проєкт збирають і які ніколи не потрапляють на вашу машину. Тепер Налаштування → Подяки прямо називають обидва числа: <strong>567 компонентів постачаються всередині Freally Oscillate</strong>, а ще 360 працювали лише на машині, яка його зібрала. Ця сторінка існує, щоб ви могли самі перевірити твердження «безкоштовно і без ШІ», тож число, яке нам лестило, — найгірше, що вона могла містити.","changelog.5814ad801a5b":"▸ <strong>Список згруповано, і видно, що є що.</strong> SDK плагінів, аудіокодеки, крейти Rust, набори іконок, пакети npm і графіка, яку намалював власник Oscillate, — шість заголовків, бо на питання «котрий із них кодек?» неможливо було відповісти за пласким списком із дев'ятисот рядків.","changelog.f9de56f9441e":"▸ <strong>Кожен компонент, що називає автора, тепер його показує</strong> — саме це й означає обіцянка сторінки подяк. ⚠ Пакети npm не називають своїх авторів ніде, звідки Oscillate міг би це прочитати без звернення до сервера, а Oscillate до серверів не звертається, тож у цих рядках автора немає замість здогадки.","changelog.3d0eb391f040":"▸ <strong>VST 3 Plug-In SDK тепер у списку разом зі своїм повідомленням про авторські права</strong>: його немає в жодному lock-файлі, тож ніщо його туди не вносило, а ліцензія вимагає саме цього.","changelog.7377a939c0c4":"Додано — щойно записаний дубль доходить до іншого продюсера","changelog.7fb3fbc8f280":"⛔⛔ <strong>Запис передається; пакет семплів — ні.</strong> Дубль — єдине, чим ви безсумнівно володієте, тож коли хтось приєднується до вашої кімнати, записані вами дублі йдуть разом із проєктом, і їхні кліпи грають. Усе, що ви купили, лишається на місці, а список того, що треба піти й дістати, не змінюється.","changelog.0e125500e568":"▶ <strong>Oscillate знає, що дубль ваш, бо сам записав файл</strong>, саме в мить запису, а не здогадується за шляхом. І надсилає він лише файл, який справді лежить у його власній теці Takes, тож проєкт, який вам хтось надіслав поштою, не може перетворити вашу машину на спосіб пересилати <em>їхні</em> файли далі.","changelog.52dc23d22b34":"▸ <strong>Дубль, що надійшов, не вам передавати далі.</strong> Кожна машина ручається лише за те, що записала сама. ⚠ Це записали як правило ще до того, як воно стало правдою: коду, що мав знімати позначку, не існувало, тож дубль від одного співавтора пропонувався б далі третьому так, ніби його записали ви. Тепер це забезпечено в обох напрямках, і над цим стоїть перевірка.","changelog.4976afdf942b":"▸ <strong>Панель каже, скільки дублів надійшло</strong>, поруч зі списком семплів, яких немає. Кліп, що починає грати за кілька секунд після приєднання, — це функція, яка працює, але на екрані нічого про це не казало.","changelog.91203a1b805c":"Виправлено — імпортований семпл позначався як ваш власний запис","changelog.bf40e3fa098c":"⛔⛔ <strong>Кожен аудіофайл, імпортований через аранжування, записувався в проєкт як дубль, створений Oscillate.</strong> Він мав спільний шлях коду з рекордером, і цей шлях ставив позначку безумовно, а коментар стверджував, що туди потрапляє лише рекордер. Із цього випливали дві речі: співавторові ніколи не казали, з якого пакета ваш імпортований семпл, тож він не міг піти й купити його; а щойно дублі почали передаватися, куплений семпл передавався б разом із ними. Тепер імпорт і запис розрізняє система типів, а не коментар.","changelog.8d484c32c666":"Додано — ваші пакети семплів лишаються вашими","changelog.8f6475f914ce":"⛔⛔ <strong>Oscillate — не спосіб переносити пакети семплів між комп'ютерами, і тепер він це забезпечує, а не обіцяє.</strong> Коли ви працюєте з кимось, передається лише <em>посилання</em> проєкту на звук — ніколи не сам звук і ніколи не шлях, за яким він лежить на вашому диску.","changelog.f988bbb09929":"▶ <strong>Якщо пакет є у вас обох, він просто грає.</strong> Oscillate впізнає звук співавтора у вашій власній бібліотеці за вмістом, тож той самий пакет працює, хоч би де ви його зберігали і як би перейменували теку. Нічого шукати не треба.","changelog.c8bdf1531d58":"▸ <strong>Якщо пакета у вас немає, Oscillate каже, що це</strong> — пакет і файл, — і кліп мовчить, доки ви його не дістанете: від співавтора через Discord або купивши, як ви й так зробили б. ⚠ Ваш семпл із тією самою назвою, але іншим звуком, позначається як інший, а не тихо підставляється замість нього, бо це змінило б запис, не сказавши вам.","changelog.4649fcb81559":"⚠ <strong>Це діє під час роботи, а не лише під час приєднання.</strong> Семпл, перетягнутий на доріжку посеред сесії, вирушає без шляху, як і все інше.","changelog.57f9f9dbb430":"Додано — позначка на пакетах, які є у вас обох","changelog.1c9cfe9ae3ee":"▸ <strong>Тепер Oscillate може сказати, які з ваших пакетів семплів є й у людей, з якими ви працюєте</strong>, — побайтово, а не за назвою. Тека, яка є у вас обох, отримує позначку в браузері, тож ви з першого погляду знаєте, що звук, по який ви тягнетеся, вони справді почують.","changelog.3f47892c9684":"⚠ Порівняння відбувається у два кроки, щоб лишатися швидким: спершу назви й розміри файлів, що нічого не читає з диска, а повна побайтова перевірка — лише для тих пакетів, які, як виявилося, є ще в когось. Пакет, що є у вас обох у теках із різними назвами, однаково збігається.","changelog.7bec1b129e12":"⛔ <strong>Вона лише позначає, і більше нічого.</strong> Нічого не надсилається: збіг каже, що звук ідентичний, і ніколи не може сказати нікому, як кожен із вас його отримав.","changelog.bb2db2d36be7":"Виправлено — панелі кімнати взагалі не було на екрані","changelog.55a9091211cb":"⛔⛔ <strong>Ділянка кімнати малювала свій заголовок, кнопку відокремлення і більше нічого.</strong> Усе за нею було збудовано, але нічого не було досяжним: ні кнопки, яку можна натиснути, ні коду, який можна скопіювати. ⚠ Знайшов це тест, що дивиться на <em>зібрану</em> сторінку, а не на компонент.","changelog.1ec729130651":"▸ ⚠ <strong>А смуга показу/приховування віртуальної клавіатури була замала, щоб у неї зручно було влучити</strong>: 21 піксель заввишки там, де все, що натискається, має бути щонайменше 24. Видимою всюди вона стала лише в попередньому релізі, і саме тоді це почало мати значення.","changelog.57877c1f100c":"Виправлено — скасування нічого не робило після відкриття збереженого проєкту","changelog.5243b35620d0":"⛔⛔ <strong>ВІДКРИЙТЕ ПРОЄКТ, ЗРОБІТЬ ЗМІНУ, НАТИСНІТЬ <code>Ctrl+Z</code> — І НІЧОГО НЕ ВІДБУВАЛОСЯ.</strong> Кожен запуск давав цьому комп'ютерові нову ідентичність, а збережений проєкт пам'ятав того, хто його писав, тож після відкриття файлу ваші зміни записувалися під чужим іменем, і ваше скасування не могло їх знайти. ⚠ Помилки не було: пункт меню просто був сірим, а комбінація клавіш нічого не робила.","changelog.c356d2d80bd1":"▸ Тепер цей комп'ютер зберігає одну ідентичність, тож повторне відкриття вчорашнього проєкту повертає й історію скасувань, яку ви в ньому залишили, — саме для цього файл проєкту й було задумано.","changelog.f0d11ed91957":"Додано — запис можна перетворити на ноти, а патерн — на запис","changelog.a7701541a706":"⛔⛔ <strong>КЛАЦНІТЬ КЛІП ПРАВОЮ КНОПКОЮ — І ВІН СТАНЕ ІНШОГО ТИПУ.</strong> Аудіокліп стає патерном поруч; патерн стає аудіо поруч. ⚠ <strong>Вихідний кліп ніколи не замінюється</strong> — ви просили інший тип, а не щоб перший перестав існувати, — а все перетворення скасовується <strong>одним натисканням</strong>, разом із доріжкою, яку воно створює для результату.","changelog.2a5ddf2c998c":"▸ <strong>Запис стає нотами</strong>: програма слухає, де починається кожна нота і яка в неї висота. ⚠ <strong>Результат буде неідеальним, і про це сказано.</strong> Барабанний луп перетворюється <strong>взагалі ні на що</strong> й повідомляє, зі скількох ударів не вдалося зчитати висоту, — мелодія, якої у вашому записі немає, гірша за чесну відмову.","changelog.59ed1e55e7ad":"▸ <strong>Патерн стає аудіо через усе, що стоїть на цій доріжці</strong>: інструмент у його слоті, потім кожен аудіоефект після нього, по черзі, і кожен названо в рядку, що з'являється після завершення. ⚠ Пристрій, вимкнений фіолетовою крапкою, або вимкнена ціла група до рендеру <strong>не</strong> входять. ⚠ Фейдер і панорама доріжки навмисно <em>не</em> запікаються: новий кліп грає через них, тож запікання подвоїло б їхню дію.","changelog.083ef45f5391":"▸ <strong>Якщо слот інструмента порожній, програма каже, який звук використала натомість</strong>, а семплер, у який нічого не завантажено, <strong>відхиляється з назвою</strong>, а не повертається як дві секунди тиші.","changelog.79e200253532":"▸ <strong>Прогрес — це число, а не спінер.</strong>","changelog.85981714a333":"Додано — кімната відкривається, і ніхто не тримає сервер","changelog.4749e8ae03da":"⛔⛔ <strong>ЧЕТВЕРО ПРОДЮСЕРІВ, ОДНА СЕСІЯ, ЖОДНОГО СЕРВЕРА.</strong> Натисніть <em>Створити код кімнати</em>, надішліть код комусь, вставте код, який вам надішлють у відповідь, — і ви з'єднані. <strong>Ні облікового запису, ні входу, нічого, що треба тримати запущеним, і нічого, що хтось може вимкнути.</strong>","changelog.40cbdaae0aa4":"▸ <strong>Половина того, хто приєднується, тепер існує.</strong> Вставте код у панель кімнати, і Oscillate відповість власним кодом, який треба надіслати назад, — цієї частини бракувало, коли попередня версія вміла створити кімнату, до якої ніхто не міг увійти.","changelog.5417dcda779c":"▸ ⛔ <strong>Третя й четверта людина коштують по одному обміну, а не по шість.</strong> Щойно двоє з'єднані, це з'єднання переносить знайомства для всіх інших: кімната на чотирьох — це <strong>три</strong> обміни замість шести, яких інакше потребувала б повнозв'язна мережа, а третій і четвертий учасники ніколи нічого одне одному не вставляють.","changelog.e32d5d96e2d3":"▸ <strong>Видно, хто тут.</strong> Список учасників із кольором для кожної людини — тим самим кольором у кожному місці, де вона з'являється, — і <strong>її вказівник, що рухається вашим аранжуванням</strong>, поки вона працює. ⚠ Імена вводить той, хто ними користується, і список про це каже: облікового запису немає, тож немає нічого, що могло б ім'я перевірити.","changelog.309b2d70f417":"▸ <strong>Чат — доки існує кімната.</strong> ⛔ Він ніде не записується: ні на диск, ні в проєкт, ні у ваші налаштування.","changelog.63c63c2cdd7b":"▸ ⛔ <strong>Ваше скасування — ваше.</strong> <code>Ctrl+Z</code> скасовує <strong>вашу</strong> останню зміну й ніколи чужу, навіть коли чужі правки надходять поміж ваших. Двоє людей, що редагують одне й те саме в ту саму мить, зрештою бачать однаковий результат, і жодній машині не доводиться нічого питати.","changelog.f28f76dbdb7c":"▸ ⚠ <strong>Коли з'єднатися не вдається, програма каже чому.</strong> Приблизно одна пара з десяти не може дістатися одне до одного напряму, і Oscillate називає справжню причину — зокрема <strong>вимірює</strong> випадок, коли ваша мережа дає кожному серверу іншу адресу, а тут не допоможе ніщо, крім ретранслятора. ⛔ Нескінченного спінера немає.","changelog.17298de48df2":"▸ ⛔ <strong>Вам кажуть, до чого програма звернеться і до чого звернулася.</strong> Відкриття кімнати запитує вашу адресу в публічного сервера STUN: сервери, які буде випробувано, перелічено на панелі ще до того, як ви щось натиснете, ті, що справді відповіли, видно потім у Налаштування ▸ Спільна робота, список можна замінити власним, а <strong>Не звертатися до жодного сервера</strong> вимикає це повністю.","changelog.63cb58714c59":"▸ ⛔⛔ <strong>Код кімнати містить публічну адресу вашого комп'ютера</strong>, і саме це взагалі уможливлює кімнату без сервера. <em>«Ставтеся до цього як до пароля»</em> стоїть поруч із <strong>кожною</strong> кнопкою, що копіює код.","changelog.9191285a6277":"⚠ <strong>Нічого не запускається, доки не знадобиться</strong>: ні кімнати, ні процесу, ні запиту брандмауера на машині, де кімнату ніхто ніколи не відкривав.","changelog.e3b418ec5f75":"⚠ <strong>Чого тут ще немає:</strong> людина, що приєднується, <strong>не</strong> отримує вашого проєкту. Доки цього не зроблено, обидві машини мають відкрити той самий файл <code>.oscillate</code>, щоб правки означали те саме.","changelog.e9c85ff00dfa":"Виправлено — ніщо ніколи не зчитувало хвильових форм теки","changelog.d7b3c5728d91":"⛔⛔ <strong>ДОДАВАННЯ ТЕКИ ТЕПЕР ЗЧИТУЄ ЇЇ ХВИЛЬОВІ ФОРМИ.</strong> Так мало бути й раніше: був прохід, індикатор прогресу й кеш, але <strong>ніщо в програмі ніколи не запускало проходу</strong>. Кожна хвильова форма малювалася тоді, коли ви вперше клацали той файл, — саме в ту мить, коли чекати хочеться найменше. ⚠ Тепер індикатор поруч зі списком тек рухається, і на ньому видно кількість файлів.","changelog.c5045ae52aa6":"Додано — файли лягають туди, куди ви їх кидаєте, і кожен пристрій має власне обличчя","changelog.8aa7963ebacf":"⛔⛔ <strong>ПЕРЕТЯГНІТЬ СЕМПЛ ІЗ ПРОВІДНИКА ПРОСТО НА АРАНЖУВАННЯ.</strong> Аудіо лягає на аудіодоріжки, MIDI — на MIDI-доріжки; файл не того типу <strong>відхиляється, а не мовчки отримує нову доріжку</strong>, і ціль каже про це ще до того, як ви відпустите. Порожнє місце під останньою доріжкою створює доріжку потрібного типу з назвою файлу. ⚠ Кілька файлів одночасно лягають один за одним і скасовуються <strong>одним</strong> натисканням, а <code>.mid</code> надходить як ноти на власній сітці проєкту, а не в темпі, у якому його записали.","changelog.e2a8868bca4e":"▶ <strong>Для цього не знадобилося жодного нового дозволу.</strong> Перетягування йде тим самим каналом, що й індикатори рівня; шляхи до файлів узагалі ніколи не доходять до сторінки.","changelog.c170e8e66577":"⛔⛔ <strong>ЛІМІТЕР БІЛЬШЕ НЕ СХОЖИЙ НА ЕКВАЛАЙЗЕР.</strong> Кожен із сімдесяти п'яти пристроїв оголошує власне обличчя: що він малює над своїми елементами керування, якої ширини хоче бути і які з його елементів керування ви шукаєте першими. Еквалайзер малює свою характеристику; компресор — те, що він знімає, з числом поруч зі смужкою. ⚠ Обличчя, вимірювання для якого ця збірка ще не робить, не малює <strong>нічого</strong>, а не вигадану форму.","changelog.9913ddb063ed":"⛔⛔ <strong>ГРУПУЙТЕ ПРИСТРОЇ Й ВИМИКАЙТЕ ЦІЛУ ГРУПУ ОДНІЄЮ КРАПКОЮ.</strong> Позначте дві чи більше картки в стійці, натисніть <em>Згрупувати</em>, і вони переїдуть разом під один заголовок із назвою, стрілкою згортання й однією фіолетовою крапкою — заповненою, коли групу ввімкнено, і порожнистою, коли вимкнено. ⚠ Вимкнення й повторне ввімкнення групи повертає точно те, що було, зокрема й той пристрій усередині, який ви навмисно обійшли. ⛔ Проєкт із групами все одно відкривається в збірці, яка про них ніколи не чула.","changelog.7742cde966eb":"▸ <strong>Таку крапку має й кожна картка пристрою</strong> — як на власних пристроях Oscillate, так і на плагінах VST 3 і CLAP у хості.","changelog.70451f4cd15b":"▸ <strong>Пристрої можна перетягувати з браузера в стійку</strong>, у вибраний вами проміжок; проміжки, які його не приймуть, кажуть чому, ще до того, як ви відпустите.","changelog.e5e7c82e5751":"▸ <strong>Монопольний звук у Windows, керований подіями.</strong> Пристрій дістається лише Oscillate, а системний шлях мікшування обходиться; екран налаштувань показує те, що справді відкрилося, а не те, що запитували. ⚠ Усе, що машина відхиляє, повертається до робочого спільного потоку, а не до тиші.","changelog.9cc28e987ea4":"Виправлено — власним нотам плагіна не було куди йти","changelog.e38c38ecdf91":"⛔ <strong>Ноти, які видає плагін у хості, тепер мають перевірку на кожному перегоні.</strong> Їх забирали з плагіна, переносили через канал і вставляли в блок, — а єдиний тест цього з'єднання ганяв туди й назад <strong>порожній</strong> список подій, тож двадцять байтів, які займає подія, ніщо ніколи не перевіряло.","changelog.14fc2e72aca1":"Додано — редактори плагінів відкриваються, а браузер знає, на якій ви доріжці","changelog.3a086a46c809":"⛔⛔ <strong>ВЛАСНЕ ВІКНО ПЛАГІНА В ХОСТІ ВІДКРИВАЄТЬСЯ.</strong> Пісочниця володіє справжнім вікном верхнього рівня з циклом повідомлень, тож редактор VST 3 чи CLAP з'являється, рухається, закривається й <strong>відкривається знову</strong> — закриття редактора більше не означає, що картку треба видалити, щоб його повернути. ⚠ Плагін, який відмовляється показати редактор, тепер відрізняють від плагіна, що впав: відмова нічого не робить сірим.","changelog.1aed8953980f":"▸ <strong>Категорія «Плагіни» показує те, що знайшов сканер</strong>, і плагіни з'являються <strong>в міру знаходження</strong>, а не всі наприкінці. ⚠ Сканування більше не відкриває консольне вікно для кожного плагіна — перше сканування справжньої бібліотеки раніше блимало десятками таких вікон.","changelog.84b095c699d5":"▸ <strong>Заголовок доріжки одним словом каже, MIDI вона чи Звук.</strong> Позначка була маленьким значком за <code>aria-hidden</code>, що нічого не казав екранному читачеві й дуже мало — новому продюсерові; а відповідати вона має на питання <em>які ефекти сюди можна поставити</em>.","changelog.dc9fc03cc83d":"▸ <strong>Браузер стежить за вибраною доріжкою.</strong> Аудіодоріжка не показує плагінів-інструментів і нотних ефектів, бо не має нот, які могла б їм дати; вбудована категорія, що не підходить, так і каже, а не стає порожньою. Власні аудіоефекти Oscillate ніколи не ховаються — їм місце на доріжках обох типів.","changelog.899b576b1610":"▸ <strong>Другий інструмент замінює перший</strong>, як у будь-якій іншій DAW, одним жестом, тож одне натискання скасування повертає старий разом із його налаштуваннями.","changelog.ece91873bdd3":"Виправлено — синхронізованим із темпом плагінам повідомляли неправильний час","changelog.940e26b06d02":"⛔⛔ <strong>КУРСОР ВІДТВОРЕННЯ ЗБІГАВСЯ; СТРІЧКА ЧАСУ НАВКОЛО НЬОГО — НІ.</strong> Плагін у хості отримує транспорт у кожному блоці. Позиція в долях завжди була справжньою, а п'ять полів поруч були константами, і <strong>обидва формати плагінів оголошували ці поля дійсними</strong>:","changelog.f753d55e9822":"⛔ <strong>Позиція в семплах у VST 3 була вільним лічильником</strong>, а не курсором відтворення. Вона збігалася до першого переміщення, а потім назавжди розходилася — рівно на довжину стрибка, — тож плагін, що довіряє годиннику з точністю до семпла, з'їжджав із сітки, щойно ви вмикали цикл.","changelog.f49a399d635c":"⛔ Стрічка часу в секундах дорівнювала <code>0</code>, хоча CLAP повідомляли, що вона дійсна.","changelog.f6279218ddd3":"⛔ Цикл мав нульову довжину, хоча VST 3 оголошував поля циклу надійними.","changelog.17084eb56c2d":"⛔ Розмір завжди був чотири чверті, тож усе, що синхронізується з тактами, помилялося в 3/4 чи 7/8; такт завжди нібито починався на самому початку пісні; а прапорець запису завжди був хибним.","changelog.9cdee9cc734d":"▸ Тепер усі п'ять беруться із самого транспорту, а позиція в семплах <strong>виводиться</strong> з курсора відтворення, а не рахується окремо: два годинники розходяться, один — не може.","changelog.77ad99f84eb0":"Додано — Windows відкриває потік із низькою затримкою, а панель перестає гадати","changelog.a602943c1b8b":"⛔⛔ <strong>ДРАБИНА МОГЛА НАДАТИ ЩАБЕЛЬ, ЯКИЙ НІЩО НЕ МОГЛО ВІДКРИТИ.</strong> Ще з фази 7 Oscillate питав Windows, з яким періодом працює її аудіорушій; але відкрити потік із цим періодом він не міг. <code>cpal</code> не робить виклику <code>IAudioClient3::InitializeSharedAudioStream</code>, і попросити його про це не можна, тож <code>ModeReason::LowLatencyNotBuilt</code> існувала, щоб чесно про це сказати, а не обіцяти затримку, якої продукт не міг дати.","changelog.e7258ea8357b":"▸ <strong>Тепер є другий аудіобекенд.</strong> <code>MMDeviceEnumerator</code> ▸ <code>IAudioClient3</code> ▸ <code>GetSharedModeEnginePeriod</code> ▸ <code>InitializeSharedAudioStream</code>, керований подіями, із власним потоком рендерингу. На машині розробки обидві кінцеві точки відповідають <strong>480 кадрів на 48 кГц</strong>. ⚠ Будь-який збій повертає до звичайного спільного потоку, і звук усе одно є: старіша Windows, драйвер, що не приймає цей період, формат мікшування, відмінний від 32-бітного з рухомою комою.","changelog.861accbc382a":"⛔ <strong>Рядок причини змінив значення, тож змінилося й формулювання в усіх 18 мовах.</strong> <code>lowLatencyNotBuilt</code> раніше означав <em>Oscillate цього не вміє</em>. Тепер він означає <em>ця машина цього не зробила</em> — і провина саме там.","changelog.6e9efa7f4ed8":"Виправлено — аудіопанель повідомляла прогноз замість факту","changelog.ea32534bf5d0":"⛔⛔ <strong>НАЛАШТУВАННЯ ▸ ЗВУК НАЗИВАЛИ ПРИСТРІЙ «СПІЛЬНИМ», ХОЧА ЧЕРЕЗ НЬОГО ГРАВ ПОТІК ІЗ НИЗЬКОЮ ЗАТРИМКОЮ.</strong> Драбина вирішує за тим, що драйвер <em>заявляє</em>: мінімальний період 128 кадрів або краще на 48 кГц. Кінцеві точки машини розробки заявляють 480 — а <code>InitializeSharedAudioStream</code> усе одно їх відкриває.","changelog.b78ee47f67e4":"▶ <strong>Панель більше не прогнозує щодо пристрою, який уже відкрито.</strong> Рушій записує щабель, який справді зайняв, і це беззастережно перемагає; за драбиною лишається одна чесна робота — казати, що, імовірно, дасть пристрій, який <strong>не</strong> відкрито. ⚠ Попереднє виправлення натомість коригувало прогноз даними рушія, а коригування може лише <em>віднімати</em> від прогнозу, якого не воно робило, — тож воно ловило один напрямок і було сліпим до іншого.","changelog.8870524415ec":"⛔ <strong>А період на екрані тепер виміряний.</strong> Там був <code>min_period_frames</code> — те, що стверджує драйвер, — показаний поруч із потоком, що працював із тим періодом, який надав <code>InitializeSharedAudioStream</code>. Для невідкритого пристрою лишається заявлене значення: там це прогноз, а не твердження про щось, що працює.","changelog.e255b62cecd9":"⛔ <strong>Відмова зберігає свою причину.</strong> Драйвер, що не працює так швидко, Windows, надто стара для <code>IAudioClient3</code>, і пристрій, що зник, зливалися в одну порожню відповідь, і панель підписувала всі три як <em>«ця машина не відкрила потік із низькою затримкою»</em>, — а це посилає людину оновлювати Windows через налаштування драйвера.","changelog.5b21975b68bb":"Виправлено — аудіопанель повідомляла рішення замість факту","changelog.2718cbe5591b":"⛔⛔ <strong>Побудова бекенда відкрила ту саму неправду поверхом вище.</strong> Коли потік із низькою затримкою став справжнім, драбина надає цей щабель будь-якому досить швидкому драйверу, — а коли відкриття потім не вдається, рушій тихо відступає, тоді як панель і далі показує <em>«Низька затримка, спільний»</em>. ▸ Тепер Налаштування ▸ Звук показують те, що справді зайняв працюючий рушій, а не те, що за нього вирішили.","changelog.795cdd276d4e":"Виправлено — блок на 10 мс планувався, як текстовий редактор","changelog.ebec07e8645f":"⛔ <strong>Потік рендерингу не був зареєстрований у MMCSS.</strong> Просити в драйвера 480 кадрів марно, якщо потік, що їх заповнює, може витіснити перетягування вікна. Тепер він приєднується до завдання <strong>Pro Audio</strong>, а перевірка зчитує власний пріоритет потоку рендерингу зсередини зворотного виклику — <strong>0 → 15</strong>, — а не вірить на слово.","changelog.c73668bfb50e":"Додано — плагін у хості вперше видає звук","changelog.73ae63bbe1c7":"⛔⛔ <strong>ЖОДЕН VST 3 ЧИ CLAP НІКОЛИ НЕ ОБРОБИВ У ЦЬОМУ ПРОДУКТІ ЖОДНОГО БЛОКУ ЗВУКУ.</strong> Усю фазу 6 і фазу 7 плагін сканувався, завантажувався, активувався, повідомляв свою затримку, записував її назад у проєкт і відкривав власне вікно редактора — кожен крок під перевіркою і зелений, — а сигнал ішов <strong>повз нього</strong>. Продюсер чув доріжку без свого плагіна, маючи вікно плагіна просто перед очима.","changelog.732aab71cf12":"▶ <strong>Чотири речі мали бути правдою одночасно</strong>: <code>DeviceRack</code> зберігав <code>Vec&lt;Box&lt;dyn StockDevice&gt;&gt;</code>; єдиними дверима <code>GraphBuilder</code> був <code>registry::build</code>; <code>Channel::chain</code> мав ключі за <code>type_id</code> реєстру, якого плагін не має; а <code>oscillate_app::mixer</code> починав свій цикл проєкції з <code>let DeviceKind::Stock { .. } else { continue }</code>. ⚠ <strong>Увосьме цей проєкт знайшов завершений механізм, який ніщо не викликає.</strong>","changelog.4d8fc1027169":"⚠ <strong><code>oscillate-audio</code> і далі не залежить від <code>oscillate-host</code>, і не повинен.</strong> Рушій оголошує <em>форму</em> — <code>rack::ForeignDevice</code>, — а <code>src-tauri</code>, який уже залежить від обох, її постачає. Рушій і досі не може відкрити спільну бібліотеку, але тепер може запускати те, що відкрило щось інше.","changelog.f8700736d0be":"Додано — доріжка може грати вихід плагіна іншої доріжки","changelog.3e316a37dda0":"Те, що в Live записується як <strong>«MIDI From → track → Plug-in Output»</strong>, а <code>InputRouting</code> отримує <code>notes_from</code>. ⛔ <strong>Це був фірмовий дефект у найчистішому вигляді:</strong> вихід плагіна, що видає ноти, забирав CLAP, забирав VST 3, <code>AudioMessage::events</code> переносив назад через канал і вставляв у список того, хто викликав, — п'ять правильних етапів, — а потім його <strong>відкидали</strong>, бо в рушії не було куди його подіти.","changelog.bcc00e454522":"⚠ Маршрут — це <strong>ребро впорядкування</strong> в тому самому топологічному проході, що впорядковує аудіомаршрутизацію, тож ноти належать цьому блоку, а не попередньому, а дві доріжки, що вказують одна на одну, відхиляються, а не рендеряться назавжди із запізненням на блок.","changelog.2447de6a9358":"Додано — запис MIDI, якого Oscillate ніколи не робив","changelog.0bba2bd8bed7":"<code>capture::NoteCapture</code> — без блокувань, без виділення пам'яті, шістнадцять тисяч нот, і <strong>кожна несе своє місце в субтіках</strong>, бо кільце голих повідомлень поставило б кожну ноту дубля на першу долю. ⛔ Захоплення відбувається <strong>після</strong> того, як приєднуються змаршрутизовані ноти, і <strong>перед</strong> власним нотним ланцюжком доріжки — саме це записує кожна DAW: вхід, а не результат після ефектів. Захоплення після ланцюжка запекло б арпеджіатор, а відтворення кліпу крізь нього арпеджувало б арпеджіо.","changelog.71aaaf954cef":"⚠ Дубль надходить як <strong>одна</strong> <code>Operation</code> із двома правками — патерном і кліпом, що його розміщує, — тож скасування не лишає по собі патерна, який ніщо не грає.","changelog.44edd735e062":"Додано — Налаштування ▸ Звук, і драбина вирішує на основі правди","changelog.26faed29b702":"⛔ <strong>Ця вкладка вісім фаз поспіль показувала порожнє тіло</strong>, тоді як <code>device::enumerate</code>, <code>device::resolve</code>, <code>negotiate</code>, <code>Granted</code> і <code>ModeReason</code> лежали в рушії <strong>без жодного виклику поза <code>device.rs</code></strong> — дев'ятий випадок того самого дефекту. Панель перелічує виходи, дає вибрати один і вибрати, скільки пристрою зайняти, і <strong>називає надане разом із причиною</strong>, бо компроміс між затримкою і спільним використанням пристрою — вибір продюсера.","changelog.3eff9d3dc578":"<code>engineperiod::smallest_period</code> запитує <code>IAudioClient3::GetSharedModeEnginePeriod</code> через <code>windows-rs</code>, тож драбина вирішує за справжнім періодом рушія, а не за заявленою драйвером нижньою межею буфера. ⛔ <strong>Це виявило два справжні дефекти</strong>: вбудована звукова карта цієї машини заявляє нижню межу <strong>нуль</strong>, що <code>negotiate</code> прочитав як <code>0 &lt;= 128</code> і надав щабель низької затримки; а панель показала б <em>«Низька затримка, спільний»</em> над звичайним спільним потоком, бо <code>InitializeSharedAudioStream</code> не реалізовано. Обидва виправлено, а другий тепер — <code>ModeReason::LowLatencyNotBuilt</code>: чесна відповідь замість неправди на екрані налаштувань самого продюсера.","changelog.db88097b77e2":"Додано — провідник, п'ять форматів експорту і прослуховування в браузері","changelog.409208576c1a":"Провідник файлів із транспортом прослуховування, прослуховуванням MIDI-кліпів, тегами інструментів за двома осями, кешуванням хвильових форм та індексуванням; експорт у WAV, AIFF, FLAC, Ogg і MP3 — мастер, стеми й MIDI — з панеллю налаштувань і чесним прогресом.","changelog.a7939e4436cb":"Виміряно — рішення «так/ні» щодо вебзастосунку, на чотири щаблі раніше","changelog.93f8bbf3e20c":"⛔ <strong>Перенесено вперед із <code>v2.0.0</code> за аргументом власника</strong>, і він мав рацію: дізнатися на <code>v2.0.0</code> означає дізнатися після того, як кожну функцію спроєктовано двічі. Відповіді на обидва питання — у <code>web/spike/</code>.","changelog.799111b932af":"✅ <strong>DSP компілюється в <code>wasm32-unknown-unknown</code> з першої спроби</strong> без жодних змін у коді — разом з <code>oscillate-synth</code> і заводською бібліотекою на 248 інструментів, — а один змодельований рояль на повній поліфонії коштує близько <strong>11% блоку на 128 кадрів</strong>.","changelog.7ead2fc63ed7":"✅ <strong>VST 3 може дістатися вкладки браузера через нативний міст</strong>: повний цикл через loopback — <strong>p99 0.049 мс</strong>, близько 2% блоку.","changelog.1f8fdb6a96c2":"⛔ <strong>Але звучить воно не так само.</strong> WASM і нативна збірка розходяться в першому блоці на 2.4e-5 і встановлюються близько <strong>−60 dBFS</strong>, бо 551 трансцендентний виклик на блок обчислює власний порт <code>libm</code> від Rust на wasm і MSVC CRT у нативній збірці. ▶ Засіб обмежений — крейт <code>libm</code> з обох боків, — але він змінює й вихід десктопної версії, тож це рішення, а не латка.","changelog.09954837c4f4":"⚠ <strong>Фази 6 і 7 обидві потрапили в <code>main</code> 2026-08-29</strong> як коміти злиття <code>43785ad</code> і <code>7bb1ea1</code>. Разом вони — щабель <code>v0.3.0</code>: DAW, яка розміщує ваші плагіни <em>і</em> має власні, — і щабель <strong>ще не позначено тегом</strong>: спершу потрібен <code>REL-0.3.0</code>, наскрізна релізна збірка. <code>v0.2.0</code> і <code>v0.2.5</code> за ним досі без тегів.","changelog.9b1dcbd5fbd5":"Додано — усі 248 інструментів, барабанні пакети і Freally MixSir","changelog.52be750b9006":"⛔⛔ <strong>У ПЕРЕЛІКУ БУЛО 197, І ПРИЧИНУ ВАРТО ЗНАТИ.</strong> Він <strong>обходив</strong> власний <code>Kind::ALL</code> кожного рушія, тож міг бачити лише інструменти, які <em>називає</em> змодельований рушій. <code>SubBass</code>, <code>SawLead</code>, <code>WarmPad</code>, <code>Riser</code>, <code>VoxChop</code> і ще сорок шість визначаються <strong>патчем</strong>, а не індексом виду, — жоден обхід не міг до них дістатися. У цьому й увесь розрив між 197 і 248.","changelog.40218bb7cac0":"⛔ <strong>А індекс виду — не звук.</strong> Фіксація <code>(Bowed, 2)</code> давала <em>типовий</em> патч смичкового рушія з вибраним <code>Cello</code> — а не той Cello, який продюсер чує у Freally MIDI Master, тобто <code>generator::generate</code> → <code>articulation::apply</code> → <code>tone::apply</code>. Два продукти, одна назва, різний звук — і нічого не падає.","changelog.5e270075e2b0":"Тож <code>factory/</code> — це каталог, <strong>імпортований</strong>: сім файлів побайтово з власного модуля пресетів плагіна, плюс <code>preset.rs</code>, виведений із фрагмента його <code>mod.rs</code>, що не містить оголошень модулів. Перевірка на форк заново виводить цей фрагмент і падає, називаючи рядок. <code>style_sound</code>, <code>palette</code> і <code>user</code> лишилися позаду — половина для артистів/продюсерів, — і четвертий тест падає, якщо хоч один із них колись з'явиться.","changelog.3de65c2ec7b1":"⚠ <strong>Два локальні дублікати видалено, а не залишено поруч з імпортом.</strong> <code>natural_note</code> і посімейний <code>shape</code> запікача ван-шотів були грубішими копіями <code>audition_note()</code> і <code>render_time()</code>, які таксономія вже містить <strong>для кожного інструмента</strong>.","changelog.3a4683be12b7":"<strong>Модуляція висоти, клавіатура і звукова стійка.</strong> У 91 із 248 висоту можна модулювати, у 157 — ні, і цей поділ проходить просто крізь сімейства — лише в «Перкусії» 11 із модуляцією і 82 без, — тож браузер <strong>фільтрує</strong> кнопкою-пігулкою, а не теками. Обидві половини питання мають відповідь: пігулка — для пошуку, вбудована SVG-позначка в кожному рядку — для перегляду. (Не <code>∿</code>, U+223F: цього символу немає в Noto Sans, і він малюється порожнім прямокутником.)","changelog.542c14231314":"Клавіші віртуальної клавіатури підписано з контрастом справжнього піаніно — на білих клавішах темні підписи, на чорних світлі — через <code>--color-text</code>, а не літерал, і саме тому вона переживає обидві теми. Її стан зберігається, і типово вона відкрита.","changelog.327f4ea52638":"Звукова стійка над нею несе власні слова плагіна — <strong>Кімната, Жар, Відлуння, Підсилення, Панорама, Модуляція висоти</strong>, — взяті з його каталогів усіма вісімнадцятьма мовами, бо <em>«DAW, що називає це 'Драйв', коли плагін називає це 'Жар', дає два імені одному елементу керування»</em>. ⛔ На інструменті, висоту якого не можна модулювати, її взагалі не малюють. ⚠ Підсилення і Панорама — це регулятори <strong>доріжки</strong>, а не друга пара.","changelog.9fde2df9f578":"<strong>Барабанні пакети.</strong> Одинадцять наборів і 407 ван-шотів під CC0, у комплекті й доступні в браузері. ⛔ Скопійовано звук, а не генератор: <code>kitgen</code> бере кожен семпл із потоку <strong>ChaCha8</strong>, а <code>rng</code> в Oscillate — це <strong>SplitMix64</strong>, тож перенесений генератор постачав би іншу барабанну бібліотеку під тими самими одинадцятьма назвами.","changelog.36f9d92b4cee":"<strong>Freally MixSir</strong> — під'єднайте телефон через QR, надішліть йому аранжований проєкт як стеми, зведіть його намальованими ручками й завантажте мікс або будь-яку доріжку у WAV чи MP3. ⛔ Усе після надходження стемів — локальне: мікшер і експорт працюють без мережі, і в цьому вся суть — <em>«дім друга — це інша мережа. Живий потік помирає на порозі. Файл — ні.»</em>","changelog.94365ba1d670":"⛔ <strong>Секрет сесії не є необов'язковим.</strong> Один на кожне з'єднання, нічого не зберігається, п'ять невдач — і з'єднання мертве, а відмова одна й нічого не каже про те, яка частина була неправильною, — бо повідомлення, що відрізняє «немає секрету» від «неправильний секрет», каже нападникові, чого з двох він досяг.","changelog.083b2dd09b8a":"⛔ <strong>Кожна картка вбудованого пристрою була підписана його ID.</strong> Стійка показувала <code>whetstone</code>, <code>vise</code>, <code>factory.cello</code> — внутрішній ідентифікатор саме там, куди продюсер дивиться, щоб побачити, що стоїть на його доріжці.","changelog.6d162dd890d4":"⛔ <strong>У 248 інструментів на картках не було б жодної ручки.</strong> Вони не є записами <code>registry::ALL</code> і знаходяться через другий пошук, якого шлях картки не робив.","changelog.8ac445d35eda":"⛔ <strong>Ручка на картці рухала не той параметр.</strong> Ручки на картці пропускають перемикачі вибору, тож позиція ручки на картці — не її індекс у списку пристрою, і на будь-якому пристрої, чия панель відкривається з перемикачем режиму, кожна ручка на картці рухала елемент керування над тим, яким була підписана. Мовчки.","changelog.a56a71232f82":"⛔ <strong>Рецепт «проєкт → мікшер, який можна відрендерити» був розірваний.</strong> Цикл, що з'єднував кожен канал із його слотом потоку, жив усередині однієї команди Tauri і більше ніде, тож усе, що будувало мікшер в обхід неї, рендерило <strong>тишу</strong>.","changelog.7dfa8f74186b":"<strong>Вид аранжування відокремлюється у власне вікно.</strong> ⚠ Відокремлення і приховування — різні речі: якби його можна було приховати, DAW лишилася б без місця для кліпу, тож кнопки в заголовку вікна для цього досі немає, — але продюсер із двома екранами хоче бачити стрічку часу на великому.","changelog.acbb6415e329":"<strong><code>cargo test --workspace</code> скоротився з 417 с до 166 с</strong>, а одноразове запікання — зі 168 с до 15 с, без жодного пропуску і без шардингу.","changelog.27f0c63ca33a":"Додано — пристрій можна почути, перш ніж ним скористатися","changelog.9e4c221fc50d":"⛔⛔ <strong>НІЩО В OSCILLATE НЕ МОГЛО ЗАЗВУЧАТИ ПРИСТРОЄМ, ЯКОГО ЩЕ НЕ БУЛО НА ДОРІЖЦІ.</strong> Браузер перелічував сімдесят п'ять пристроїв за виразною назвою та одним рядком простою мовою, а щоб вибрати між <code>Crucible</code> і <code>Muster</code>, треба було додати один на доріжку, намалювати ноту, натиснути відтворення, послухати, видалити його й повторити те саме з другим.","changelog.5804f25b08c9":"▶ <strong>Плеєр попереднього прослуховування під Провідником файлів.</strong> Клацніть один із власних пристроїв Oscillate — і він зіграє свою демонстрацію; виберіть теку й клацніть семпл — і зазвучить він. Один плеєр, а не транспорт на кожен рядок: прослуховуватися водночас може лише один звук, а хвилеформі є де жити.","changelog.40cbef0ecde9":"<strong>Хвилеформа — і для інструментів, і для семплів</strong>: мінімум і максимум на стовпчик, а не кожен N-й семпл, тож транзієнт удару барабана переживає малювання. <strong>Тло за відіграною частиною змінює колір по ходу відтворення</strong>, з курсором відтворення та показником <strong>минуло / усього секунд</strong>.","changelog.f3f0517ac936":"<strong>Відтворення і зупинка, цикл, який можна знову вимкнути, і ← / → для відтворення назад і вперед.</strong> Реверс — це напрямок, у якому крокує індекс джерела, а не другий буфер і не другий шлях коду.","changelog.884d06fa9f2c":"<strong>Нота, велосіті й тривалість для кожного інструмента</strong>, виміряні, а не вгадані: <code>Crucible</code> і <code>Muster</code> тримають C3 понад дві секунди, бо вейвтейбл-патч і секція з дванадцяти музикантів через секунду ще розвиваються; <code>Skin</code> тримається 40 мс, бо бочка — це суцільний хвіст; <code>Sideband</code> вдаряють, відпускають і лишають дзвеніти.","changelog.8d682a63aee9":"⚠ <strong>П'ять з одинадцяти інструментів пояснюють, чому не можуть.</strong> <code>Flint</code>, <code>Armory</code>, <code>Bench</code>, <code>Hammer</code> і <code>Filings</code> — семплери, і вони мовчать, доки в них не завантажено файл, тож показують це речення замість кнопки, яка нічого не грає. ⛔ Межу тримає перевірка: кожен зібраний інструмент або оголошує прослуховування, або оголошує слоти для семплів.","changelog.151407842cb1":"⚠ <strong>Плеєр — це голос, що мікшується ПІСЛЯ графа</strong>, за зразком <code>click.rs</code>. Він звучить при зупиненому транспорті, не потребує перебудови графа й ніколи не виділяє пам'ять: буфер рендериться нагорі, у застосунку, і передається вниз, а той, який він замінює, <strong>відкладається для потоку застосунку, а не звільняється</strong>, бо звільнення пам'яті — близнюк виділення. Його покриває перевірка аудіопотоку, і ми бачили, як вона падала з <code>deallocations: 1</code>.","changelog.e7fc9384962d":"Додано — інструменти Freally Secretarium і прослуховування, що є просто читанням файлу","changelog.356af9b34f95":"⛔⛔ <strong>БРАУЗЕР ПЕРЕЛІЧУВАВ ОДИНАДЦЯТЬ ВИГАДАНИХ ІНСТРУМЕНТІВ І ЖОДНОГО СПРАВЖНЬОГО.</strong> Вказівка власника, повторена чотири рази: <em>«у мене мали бути всі ті самі інструменти, що й у Freally MIDI Master»</em>, <em>«і у Freally Secretarium»</em>, <em>«саме ті інструменти, а не вигадані»</em>.","changelog.88620eb11d8a":"▶ **<code>synth/</code> у цьому робочому просторі <em>і є</em> <code>havoc_dsp</code> із Secretarium<strong> — модуль у модуль, — і всі </strong>197<strong> його інструментів уже були скомпільовані в Oscillate. Ніщо їх не перелічувало. <code>Quiver</code>, <code>Muster</code> і <code>Crucible</code> стояли там, де мали бути <code>Violin</code>, <code>Tuba</code>, <code>Grand Piano</code>, <code>Rhodes EP</code>, <code>Accordion</code> і набори 808/909/707/606. ⚠ </strong>Шостий у цьому проєкті випадок механізму, який працює правильно, але його ніхто не викликає**, і найбільший з усіх.","changelog.9d0068c6cd97":"⚠ <strong>Каталог не прописує жорстко жодної назви.</strong> <code>oscillate_dsp::secretarium</code> обходить власний <code>Kind::ALL</code> кожного рушія й питає в нього <code>name()</code>, тож за самою побудовою це <em>і є</em> список Secretarium, і розійтися з ним він не може.","changelog.527bd770093f":"Виправлено — клацання ▶ заморожувало застосунок на дев'ять секунд","changelog.7cfc5be2b1d8":"⛔⛔ <strong>ВИМІРЯНО В RELEASE-ЗБІРЦІ, НА 48 кГц:</strong>","changelog.00ab2993d58b":"▶ <strong>Кожна <code>#[tauri::command]</code> у цьому застосунку синхронна, а синхронна команда виконується в потоці інтерфейсу.</strong> <code>preview_device</code> будував там цілий змодельований інструмент і рендерив секунди звуку — на кожне клацання, тож клацання по <code>Muster</code> заморожувало застосунок на дев'ять секунд, а повторне ставило в чергу ще дев'ять. Це одна причина двох скарг власника: <em>«інструменти завантажуються дуже повільно»</em> і <em>«я все клацаю кнопку, щоб зіграти, і зрештою воно падає»</em>.","changelog.f75de40a46cd":"⛔ <strong>Виправлення — це задум самого власника</strong>: <em>«треба просто завантажувати аудіокліп для ван-шоту, а не весь інструмент, якщо його не додано у вид аранжування»</em>. <code>bake-oneshots</code> рендерить усі 197 під час збирання — <strong>кожен на тій ноті, якою цей інструмент справді звучить</strong>, з його реальної теситури: <code>Tuba</code> на C2, <code>Piccolo</code> на C6, <code>Violin</code> на G4, <code>Double Bass</code> на E2. Ударні без висоти так і позначено, замість того щоб вигадувати їм тональність.","changelog.8d6da56f85ca":"<strong>197 кліпів, 22.6 МБ, запечені за 110 с</strong> — моно, 16 біт, вирівняні за рівнем до −1 dBFS, щоб порівняння двох інструментів порівнювало їхній звук, а не гучність, і обрізані там, де звук справді закінчується, а не за вгаданим лімітом.","changelog.94c1bdbaa43a":"<strong>Прослуховування тепер — це читання файлу: у середньому 0.19 мс, у найгіршому разі 0.5 мс.</strong> У готовому бінарнику через CDP список із 197 з'являється за <strong>134 мс</strong>, а <code>Violin</code>, <code>Tuba</code> і <code>Grand Piano</code> починають звучати за <strong>75 / 45 / 51 мс</strong>.","changelog.2dc07d5f1557":"⚠ Це тримають дві перевірки: кожен інструмент має кліп і жоден не мовчить, а читання одного кліпу лишається коротшим за 50 мс.","changelog.c5ee9fe2006c":"⛔ <strong>І кліпи ледь не вийшли недосяжними.</strong> Оголошення їх як <code>../assets/oneshots</code> клало в установлене дерево буквальну теку <strong><code>_up_</code></strong> — <code>Freally Oscillate\\_up_\\assets\\oneshots\\</code> — тоді як застосунок шукав <code>assets/oneshots</code>. Кожен запуск у розробці працював, бо відповідав запасний шлях робочого простору; <em>установлена</em> збірка не знайшла б нічого й грала б тишу для всіх 197. ⚠ <strong>Знайдено, розпакувавши MSI й запустивши розпаковану структуру з прихованою копією вихідного коду</strong>, — це єдине розташування, у якому запасний шлях не може врятувати від помилки. Тепер запікач пише всередину <code>src-tauri/</code>, тож <code>../</code> узагалі не бере участі.","changelog.f4ddb6130986":"Виправлено — шалене натискання <em>Додати</em> запускало процес плагіна на кожне клацання","changelog.a8ec7142d4cc":"⛔ Скарга власника: <em>«якщо я дуже швидко додаю плагін знову і знову, застосунок падає; він не повинен 15 разів поспіль намагатися завантажити його в ту саму аудіо/MIDI-доріжку, а потім падати»</em>. Кожне додавання запускає пісочницю <code>oscillate-hostproc</code> і чекає на неї; п'ятнадцять клацань були п'ятнадцятьма запусками процесів наввипередки в потоці інтерфейсу. ⚠ <strong>Відкидаються, а не стають у чергу</strong> — продюсер, який тисне на кнопку, хоче ще один пристрій, а не п'ятнадцять.","changelog.7dda4841cc1a":"Додано — виберіть інструмент і грайте його клавішами ← і →","changelog.82c24a2d7b61":"⚠ Список — це listbox: клацання по назві вибирає її, <strong>→ грає вперед, а ← — назад</strong>. ⛔ Напрямок задається <em>до</em> завантаження кліпу — у зворотному порядку перше натискання грає вперед і розвертається лише на другому, що виглядає як загублене натискання клавіші, а не як помилка.","changelog.fafc2a09973e":"Додано — Провідник файлів тепер браузер, улаштований так, як в Ableton","changelog.edb9f6a2c94a":"⛔⛔ <strong>ЦЕ БУВ ПЛАСКИЙ СПИСОК, А ПЛАСКИЙ СПИСОК ІЗ СІМДЕСЯТИ П'ЯТИ ПРИСТРОЇВ — ЦЕ СТІНА.</strong> Вказівка власника: <em>«має бути список на кшталт «Плагіни», «Інструменти», а потім кнопка «Додати теку» … так само, як улаштовано браузер Ableton»</em>.","changelog.5e9e61c53217":"▶ <strong>Домашній екран із розділами</strong>, кожен зі знаком <code>›</code>: <strong>Інструменти</strong>, <strong>Аудіоефекти</strong>, <strong>MIDI-ефекти</strong>, <strong>Плагіни</strong>. Клацніть один — і побачите, що в ньому. Під ними <strong>Вибрати теку</strong>, а під нею — додані вами теки, <strong>лише за назвою</strong>: клацніть назву — і отримаєте дерево цієї теки: корінь, підтеки, семпли та MIDI.","changelog.099ce0f7d765":"<strong>← і → над списком — це НАВІГАЦІЯ</strong>, а не відтворення. «Назад» повертає до категорій крок за кроком; «вперед» повторює пройдений шлях або — якщо попереду нічого немає — відкриває теку, у якій ви були востаннє. ⚠ <strong>Історія, а не прапорець режиму</strong>: булеве <code>showingCategories</code> не може відповісти на <em>«вперед, в останню теку, де ви були»</em>, а саме в цьому весь сенс стрілки.","changelog.79957fde35e2":"<strong>Фільтр шукає в тому, що ви зараз переглядаєте</strong>, причому і за тим, чим пристрій <em>є</em>, і за його назвою: <code>compressor</code> знаходить <code>Vise</code>, чия назва про це нічого не каже.","changelog.e8b3a1a389e9":"<strong><code>Plugins</code> означає чужі плагіни</strong>, як і в Ableton. Сімдесят п'ять власних пристроїв Oscillate є в індексі сканування — саме це взагалі зробило перелік пристроїв досяжним — і тут їх знову відфільтровано, інакше кожен з'являвся б двічі, а <em>Плагіни</em> стали б єдиним розділом, який будь-кому потрібен.","changelog.0047f4f33bdc":"<strong>Плеєр попереднього прослуховування лишається закріпленим під браузером</strong>, як і просили.","changelog.4f2676f1a739":"Виправлено — три дефекти, які внесло переписування браузера, і всі знайдені під час роботи зі збіркою","changelog.f49547b29542":"⛔ <strong>Семплеру казали, що в нього немає голосу.</strong> <code>previewDevice</code> брав свою відмову зі списку, який стара панель завантажувала під час монтування; переписана панель його не завантажувала, тож список лишався порожнім, і кожен семплер провалювався до <em>«цей пристрій не має власного голосу»</em>. ▶ <strong>Уже вчетверте в цьому проєкті механізм пережив свого єдиного викликача</strong>, і втретє в межах однієї цієї функції. Рядок уже містить відповідь, тож тепер відмова береться з рядка, і немає другого списку, який міг би з ним розійтися.","changelog.662d079a371c":"⛔ <strong>Покроковий сценарій сфотографував відмову під підписом, що обіцяв хвилеформу.</strong> Він клацав перший ▶ у списку, а це <code>Armory</code> — семплер. Шість із сімдесяти п'яти звучать самі по собі; тепер ▶ каже, який він, у <code>data-can-hear</code>, а сценарій просить той, що звучить.","changelog.6d5cf6780d7a":"⛔ <strong>Правило самого власника щодо тривалості не захищала жодна перевірка.</strong> <em>«Не просто ван-шот на 1 секунду, а ван-шот на 2–4 секунди, щоб було чути ансамбль чи скрипку»</em> — а єдиною перевіркою була смуга <code>400..=6_000</code> для числа в реєстрі, яка спокійно пропускає скрипку, обрубану на 400 мс, бо оголошена тривалість нічого не каже про те, чи закінчився <strong>звук</strong>. Тепер замість цього слухають дві перевірки:","changelog.67673c6c454c":"<code>no_instrument_is_cut_off_while_it_is_still_sounding</code> рендерить кожне прослуховування й порівнює останню десяту частину з власним піком — саме відношення, бо три з цих шести різняться за абсолютним рівнем на порядки, і абсолютний поріг лише заново вимірював би <em>той</em> дефект. Якщо наприкінці рівень у межах 30 дБ від піку, буфер обривається посеред ноти.","changelog.9dba8e1945f1":"<code>an_instrument_that_holds_a_note_demonstrates_for_at_least_two_seconds</code> вимагає від двох до чотирьох секунд від будь-якого пристрою, що тримає ноту секунду, — випадок скрипки й мідних, який назвав власник, — і лишає вдарений хай-хет коротким. Обидві бачили падаючими: <code>crucible</code>, обрізаний до 1.5 с, повідомляє <em>«ще звучить, на −27.9 дБ нижче свого піку»</em>.","changelog.3ac136922655":"Виправлено — шлях зі сторінки діставався диска, а перевірка цього не бачила","changelog.d83b8e757dd9":"⛔⛔ <strong><code>preview_file</code> БРАВ ШЛЯХ ІЗ WEBVIEW І ВІДКРИВАВ ЙОГО</strong>, а <code>no_command_opens_a_path_from_the_page</code> при цьому лишалася <strong>зеленою</strong>. <code>Source::open(</code> був у списку маркерів цієї перевірки; прослуховування декодує на частоті сесії, а тому викликає <strong><code>Source::open_at</code></strong>, з яким цей запис не збігався.","changelog.f6e0367699b1":"▶ <strong>Саме це й передбачає власний коментар списку</strong> на випадок, коли виклик отримує нову назву, а списку про це не кажуть, — і це сталося двічі в одній зміні, бо <code>preview_browse</code> доходить до <code>read_dir</code> через приватний <code>listing_for</code> і теж не містив жодного маркера. Та сама картина, що й із <code>place_recording</code> раніше.","changelog.81f850dd8839":"⚠ Тепер перевірка знає <code>Source::open_at(</code>, <code>read_dir(</code> і <code>listing_for(</code> і стверджує, що вибирає <strong>п'ять</strong> команд, які приймають шлях, а не три. Бачили, як вона падає: якщо прибрати перевірку, вона каже <em>«перевірка — це не список, а виклик.»</em>","changelog.2d054f75b71a":"⛔ <strong>Саму перевірку робить <code>oscillate_app::preview::Roots</code></strong> — теки, які продюсер вибрав у <strong>системному діалозі</strong>, а сторінка не може ні відкрити його, ні вибрати теку за когось. Той самий аргумент, який <code>Session::knows</code> наводить щодо проєкту. Перед порівнянням шляхи канонізуються, тож <code>../</code> за межі дерева, символьне посилання за межі дерева і сусідня тека зі спільним префіксом назви відхиляються, і на кожен випадок є тест.","changelog.eab49295e87c":"⚠ Знайдено, але не виправлено — рівні змодельованих голосів ударних не відкалібровано","changelog.1db39a57f0b2":"⛔ <strong>Рендер демонстрації вперше в цьому проєкті виміряв РІВЕНЬ на виході інструмента</strong>, і три пристрої дуже далекі від норми. На типових налаштуваннях, на 48 кГц:","changelog.8dbc3e72e325":"⚠ <strong>Регулятори <code>Level</code> застосовуються й працюють</strong>: <code>Skin</code> типово стоїть на −6 дБ, а <code>Bronze</code> — на −9. Просто змодельовані голоси під ними не відкалібровані ні щодо повної шкали, ні один щодо одного. На доріжці <code>Skin</code> жорстко кліпує, а <code>Sideband</code> поруч із ним не чути.","changelog.01769f9570bb":"⛔ <strong>Свідомо не виправлено тут.</strong> Перенастроювання трьох випущених пристроїв змінює кожен проєкт, що вже їх використовує, тож це рішення власника, а не тиха зміна, зроблена мимохідь під час додавання функції браузера. Прослуховування вирівняні за рівнем — для порівняння це й так правильно, і так робить кожна бібліотека семплів, — а <code>Rendered::raw_peak</code> зберігає справжнє число, тож дефект лишається вимірюваним. <code>the_percussion_voices_are_not_level_calibrated_and_this_says_so</code> фіксує поточний стан і впаде того дня, коли їх хтось відкалібрує, — це й буде нагадуванням оновити цю таблицю.","changelog.d14d01c626ec":"Змінено — генератори належать Freally MIDI Master, а не Oscillate (фаза 8)","changelog.dc81dfbc9b4f":"⛔ <strong>Oscillate не містить коду генерації, а крейта <code>engine</code> більше немає.</strong> Від першого коміту він був порожньою заглушкою в робочому просторі й чекав на імпорт, якого вже не буде.","changelog.e3f68ceb379a":"▶ Натомість Freally MIDI Master постачається як <strong>вбудований плагін у хості</strong>, тож його генератори приходять через межу плагінів, яку вже збудувала фаза 6, — VST 3 і CLAP, поза процесом.","changelog.7fc1c070e5b4":"⚠ <strong>Чому тут одне джерело істини краще за самодостатню збірку.</strong> Вендоринг рушія означав би побайтову копію, яку на місці тримає перевірка форків, повторну синхронізацію щоразу, як зміниться першоджерело, і вихідний код іншого продукту у двох репозиторіях. Обидва продукти мусять погоджуватися — те саме зерно й той самий стиль мають давати однакове аранжування в обох, — а копія і є тим, що врешті перестає погоджуватися.","changelog.2048fc009c6c":"Додано — власні пристрої Oscillate (фаза 7)","changelog.f5822af61c3c":"⛔⛔ <strong>ШІСТДЕСЯТ ДЕВ'ЯТЬ ІЗ СІМДЕСЯТИ П'ЯТИ ЗІБРАНО</strong>, зокрема всі двадцять вісім основних ефектів, кожен із шістнадцяти нотних пристроїв і дев'ять інструментів. ⚠ Шість лишаються лише оголошеними, і кожен заблокований швом, а не DSP, — їх перелічено поіменно нижче, у розділі <em>Що не зібрано</em>, разом із тим, на що чекає кожен.","changelog.668c497ed943":"⛔ <strong>Пристрої, зібрані відтоді, як у переліку було п'ятдесят чотири</strong>, і шви, яких вимагав кожен:","changelog.8e557db4dbd0":"<strong><code>Filings</code></strong> — хмара гранул з одного кліпу, шістдесят чотири гранули з наперед виділеного пулу. Власні перевірки знайшли в ньому два дефекти до випуску: сумарні огинаючі гранул були гучними в <code>Density × Grain Size</code> разів, тож ущільнення хмари з сорока гранул на секунду до двохсот додавало 14 дБ; а гранула, розпорошена за кінець свого джерела, замовкала на повній огинаючій — виміряно на 23 дБ тихіше.","changelog.50a4eea3576b":"<strong><code>Armory</code></strong> — вісім зон по вісім round-robin поверх пласкої таблиці 128×128 «клавіша × велосіті», побудованої поза аудіопотоком, тож нота коштує один індекс і жодної арифметики. На стиках — рівна потужність, бо дві зони мультисемплу — це різні записи, а лінійний кросфейд між некорельованими джерелами просідає на 3 дБ. Пул голосів отримав для нього справжню огинаючу фільтра.","changelog.25ae013f0dd8":"<strong><code>Sift</code></strong> — спектральне видалення шуму на 4096/1024, а отже <code>Stft</code> мусив приймати довжину кадру під час створення, а не з константи крейта. Віднімання в області потужності, а не амплітуди: тон на 53 дБ над шумом втрачає 0.12 дБ в одному випадку і менше тисячної частки децибела в іншому.","changelog.99e2902c99af":"<strong><code>Yield</code></strong> — тримає партію осторонь регістру іншої доріжки. Знадобився шов зайнятості висот між доріжками: <code>Context</code> тепер несе <code>&amp;[PitchSet]</code>, доступний лише для читання й без блокувань <em>за типом</em>, а не за обіцянкою, плюс три горизонти випередження, щоб його елемент <code>Lookahead</code> щось означав на 0, 1 і 2 долях.","changelog.cc6fff187e87":"<strong><code>Press</code></strong> — MPE-формувач, якому було потрібно, щоб <code>NoteMessage</code> ніс <code>Pressure</code>, <code>Timbre</code> і <code>Bend</code>. Ключем є нота, а не канал, бо member-канал — це деталь транспорту MIDI 1.0. Шістнадцята одночасна нота відхиляється й рахується, але ніколи не забирає чужий голос.","changelog.267f52bbec0d":"<strong><code>Ply</code></strong> — гармонайзер, що слідує за акордом, який справді є в аранжуванні. Його перевірки виявили три дефекти: детектор висоти на вході читав найгучніший бін, а для співаного голосного це той обертон, якому сприяють форманти, — голос на середньому до визначався на октаву й квінту вище; округлення бінів залишало проміжки під час зсуву вгору; а сухий шлях не затримувався відповідно до обробленого, тож за типового співвідношення це був гребінчастий фільтр, чию оголошену затримку граф компенсував би, висуваючи сухий сигнал раніше.","changelog.aadbc3dce93b":"<strong><code>Rein</code></strong> — ефект, яким керує MIDI-кліп, а не LFO. Знадобилися велосіті й щільність нот для кожної доріжки в індексі аранжування.","changelog.f7bd53ba1079":"<strong><code>Muster</code></strong> — одна партія, яку грає секція до дванадцяти виконавців; таймінг, стрій, рівень і атаку кожного виконавця один раз беруть із зерна проєкту й зберігають.","changelog.e4a1a80427f8":"<strong><code>Quiver</code></strong> — вісім ланцюжків під однією клавіатурою, напіввідкриті зони з рівнопотужним переходом.","changelog.abefe55690b3":"⛔⛔ <strong>І ЧОТИРИ ПОРУШЕННЯ В АУДІОПОТОЦІ, ЯКИХ ПЕРЕВІРКА ВИДІЛЕННЯ ПАМ'ЯТІ НЕ МОГЛА ПОБАЧИТИ.</strong> Вона проходила кожен зібраний пристрій <strong>без завантаженого семпла й без жодної звучної ноти</strong>, тож шлях читання кожного семплера й цикл голосів кожного інструмента жодного разу не потрапляли під лічильний алокатор. Тепер вона завантажує кліп у кожен слот і двічі вдаряє восьминотний акорд — і знайшла чотири:","changelog.dd412aa63e27":"<code>Skin</code>, <code>Bronze</code> і <code>Sideband</code> кожен читав <code>block.notes.to_owned()</code> — <code>Vec</code>, що виділявся в колбеку рендеру на кожному блоці, який містив ноту.","changelog.1fe564b767bd":"<code>Crucible</code> завантажував свій рушій із <code>process</code>, а імпортований синтезатор будує змодельований стан голосу, коли цей голос захоплюють уперше, — тож дев'ята одночасна нота виділяла пам'ять у колбеку.","changelog.1743b0d8b2c4":"▶ <strong>Раніше:</strong> усі двадцять вісім основних ефектів, одинадцять із шістнадцяти нотних пристроїв, чотири інструменти й одинадцять із сімнадцяти фірмових пристроїв — п'ятдесят чотири із сімдесяти п'яти. ▶ Основні 28 — це все, що специфікація називає «усім, що потрібно продюсерові, щоб закінчити запис, не тягнучись по чужий плагін». Перелік налічує 75, а чесне число — те, що відповідає <code>oscillate_dsp::registry::implemented_count()</code>; обидва числа перевіряються в коді, тож жодне не може розійтися з документом. Решта двадцять один показані в браузері з назвою, сірими, без жодних елементів керування: список елементів керування без DSP, що надає їхнім числам сенсу, був би вигаданими діапазонами, які лише виглядають авторитетно.","changelog.afcfa380d255":"<strong>Еквалайзери:</strong> <code>Whetstone</code>, <code>Hilt</code>, <code>Temper</code>. <strong>Динаміка:</strong> <code>Vise</code>, <code>Weld</code>, <code>Strata</code>, <code>Parry</code>, <code>Ceiling</code>, <code>Peen</code>, <code>Quench</code>. <strong>Драйв і підсилювачі:</strong> <code>Shear</code>, <code>Triode</code>, <code>Rasp</code>, <code>Fold</code>, <code>Oxide</code>, <code>Furnace</code>, <code>Baffle</code>. <strong>Затримки:</strong> <code>Relay</code>, <code>Spool</code>, <code>Sparks</code>. <strong>Ревербератори:</strong> <code>Chamber</code>, <code>Foil</code>, <code>Coil</code>. <strong>Модуляція і фільтр:</strong> <code>Shoal</code>, <code>Veer</code>, <code>Comb</code>, <code>Edge</code>. <strong>Утиліти:</strong> <code>Stance</code>. <strong>Інструмент:</strong> <code>Crucible</code>. <strong>Нотні пристрої:</strong> <code>Runner</code>, <code>Stack</code>, <code>Hone</code>, <code>Weight</code>, <code>Hold</code>, <code>Scatter</code>, <code>Trail</code>, <code>Hand</code>, <code>Approach</code>, <code>Rake</code>, <code>Turn</code>. <strong>Ударні:</strong> <code>Skin</code>, <code>Bronze</code>, <code>Sideband</code>. <strong>Фірмові:</strong> <code>Waypoint</code>, <code>Guard</code>, <code>Lantern</code>, <code>Feint</code>, <code>Wear</code>, <code>Gild</code>, <code>Skywave</code>, <code>Toll</code>, <code>Vault</code>, <code>Cleave</code>, <code>Strand</code>.","changelog.5140cf1f25dd":"Виправлено — три речі, які міг показати лише випущений застосунок","changelog.c5dfcf91c9c3":"⛔⛔ <strong><code>oscillate-hostproc.exe</code> НЕ БУЛО В ЖОДНОМУ ІНСТАЛЯТОРІ, ТОЖ ЖОДЕН ПЛАГІН НЕ МІГ ЗАВАНТАЖИТИСЯ.</strong> <code>tauri.conf.json</code> не оголошував ні <code>externalBin</code>, ні запису <code>bundle.resources</code>, і в <code>target/release/</code> цього бінарника теж ніколи не було — тож кожен VST 3 і кожен CLAP у <em>release</em>-застосунку падав із","changelog.07ff7d609df0":"▶ <strong>Ось відповідь на «жоден плагін ним так і не завантажився»: жоден і не міг.</strong> Увесь результат фази 6 був мертвий у всьому, що зібрано через <code>tauri build</code>, і був би мертвий в інсталяторі, який запустив би тестувальник. Скрізь в інших місцях усе проходило, бо <code>cargo test</code>, <code>cargo run</code> і <code>scripts/host-conformance.mjs</code> запускаються з <code>target/debug/</code>, де cargo вже поклав бінарник поруч із ними. ⚠ Виправлено за допомогою <code>scripts/build-hostproc.mjs</code>, оголошення <code>externalBin</code> і <code>src-tauri/tests/the_bundle_carries_the_sandbox.rs</code>, який падає, якщо оголошення, шлях або крок збирання, що створює файл, колись розійдуться. Обидва інсталятори перезібрано, і обидва зросли на стиснутий розмір бінарника.","changelog.006a47556b9e":"⛔⛔ <strong>ШІСТДЕСЯТ ДЕВ'ЯТЬ ВБУДОВАНИХ ПРИСТРОЇВ УСЕ ЩЕ БУЛИ НЕДОСЯЖНІ З БРАУЗЕРА</strong>, і це шостий випадок тієї самої картини. <code>PluginScan::index()</code> правильно додає перелік на початок; <code>PluginScan::state()</code> клонував сирий результат сканування <strong>на шар нижче від цього виправлення</strong> — а <code>plugins_state</code> є єдиною командою, яку викликає панель браузера. Тож <code>device_rack</code>, <code>device_add</code> і <code>locate_for_load</code> бачили перелік, п'ять перевірок викликали <code>index()</code> і проходили, а продюсер, що вводив <code>vise</code> у фільтр, не отримував нічого. ⚠ Наявний тест стверджував <code>state().index.plugins.len() == 1</code>, і це закріпило дефект. Нова перевірка свідомо йде через <code>state()</code>: <strong>це та функція, на іншому кінці якої є користувач.</strong>","changelog.0cc1ca49a0e2":"⛔ <strong>Підпис елемента керування і його підказку в рядку стану було переставлено в усіх вісімнадцяти каталогах.</strong> <code>arrangement.metre</code> містив речення, а <code>hints.metre</code> — слово, тож панель інструментів аранжування малювала перенесений абзац там, де має бути підпис з одного слова. Обидва рядки існували й обидва були перекладені, тож перевірка паритету, яка порівнює каталоги між собою, була зеленою над вісімнадцятьма однаковими помилками. Тепер є перевірка <em>форми</em>: кожен підпис на панелі інструментів має бути коротшим за підказку, яка його пояснює.","changelog.033773d6f964":"Виправлено — <code>Rein</code> пропонував <code>Off</code> під індексом три","changelog.3dbe0f12826c":"⚠ <code>Params::on</code> відповідає <code>index &gt;= 1</code>, тож елемент керування, який пропонує <code>Off</code> будь-де, крім першої позиції, для кожного пристрою, що питає, читається як <em>увімкнено</em>. У <code>Rein</code> <code>Target A</code> і <code>Target B</code> ставили його останнім. ⛔ Це впіймала <code>every_switch_in_the_crate_reads_off_then_on</code> — інваріант для всього крейта, а не вподобання щодо назв, і саме таке правило, яке окуповується лише тоді, коли хтось додає сімдесятий пристрій о четвертій ранку.","changelog.176683ba65e2":"Змінено — три перевірки перебудовували пристрій для кожного налаштування, і одна з них коштувала дев'ятнадцять хвилин","changelog.7f6ca671bb48":"⚠ <strong>Шістдесят дев'ять пристроїв коштують більше, ніж п'ятдесят чотири, а два з нових — значно більше.</strong> <code>Sift</code> і <code>Ply</code> кожен виконують 4 096-точкове перетворення на канал на кожен крок; <code>Muster</code> вміщує до дванадцяти синтезаторних рушіїв, а <code>Quiver</code> — вісім, і <code>SynthEngine::new</code> триває близько секунди. Набір перевірок зріс із трьох хвилин до <strong>понад двадцяти п'яти, де його вбили, не дочекавшись завершення</strong>, — і дві перші спроби зробити його доступним цілилися не в те.","changelog.c76554d4e4d6":"⛔⛔ <strong>СПРАВЖНЯ ПРИЧИНА — ОДНА КАРТИНА В ТРЬОХ МІСЦЯХ: ПЕРЕВІРКА, ЯКА БУДУВАЛА НОВИЙ ПРИСТРІЙ ДЛЯ КОЖНОГО НАЛАШТУВАННЯ, ЩО ЇЇ ПЕРЕВІРЯЛА.</strong> Жодна з трьох властивостей не має нічого спільного з конструюванням — <code>set_param</code> досягає кожного налаштування, а <code>set_param</code>, <code>prepare</code> і <code>load_sample</code> усі виконуються <strong>поза</strong> аудіопотоком. Конструювання були чистими накладними витратами, а з інструментами з рушіями в переліку стали всім часом виконання:","changelog.8a13018ad9f4":"⛔ <strong>Сама лише <code>silence_in_silence_out</code> займала дев'ятнадцять із цих хвилин</strong>, і вона була останнім тестом, що ще виконувався, коли набір вбили, — ось чому два попередні виправлення нижче виглядали так, ніби нічого не дали.","changelog.6f7962d980c6":"⚠ <strong>Жодне твердження не послаблено.</strong> Кожне налаштування й досі відвідується, у тому самому порядку, на кожному розмірі блоку; кожне перед рендером проходить <code>reset</code>; і кожен елемент керування повертається до типового значення, перш ніж зрушить наступний, тож кожен прохід, як і раніше, рівно на один елемент керування відрізняється від типових налаштувань — саме це раніше давала побудова нового пристрою. ⚠ Якщо вже на те, перевірка тиші тепер перевіряє <em>суворіше</em>: рушії, ліниво побудовані попереднім налаштуванням, лишаються побудованими, тож на порожньому сигналі працює більша частина пристрою, ніж раніше.","changelog.a633f2f1182e":"⚠ <strong>Дві зміни в самих пристроях, які варто було зробити в будь-якому разі і які самі по собі майже нічого не дали:</strong>","changelog.26dabe8bffb3":"<strong><code>Muster</code> будує лише тих виконавців, які звучатимуть.</strong> Секція з чотирьох платила за дванадцять — і в продукті, і в наборі перевірок; решту будують, коли зростає <code>Players</code>, у <code>set_param</code>, який ніколи не виконується в аудіопотоці.","changelog.51e5d2b28182":"<strong><code>Quiver</code> будує лише ті ланцюжки, які можуть звучати.</strong> Сім із восьми відкриваються беззвучними з порожньою зоною, а ланцюжку, який не може звучати, рушій не потрібен.","changelog.df19439598d0":"⚠ <strong>Перевірку, яку ніхто не може собі дозволити запускати, пропускають</strong>, а це те саме, що не мати її взагалі, — а в цьому проєкті зафіксовано сім дефектів, які впіймала б лише перевірка, яку хтось справді запустив.","changelog.6e1b1bcf02c1":"Виправлено — оголошення sidecar ламало кожну збірку <code>cargo</code>, а <code>ci:local</code> при цьому був зеленим","changelog.99a217744ea0":"⛔⛔ <strong>ОГОЛОШЕННЯ <code>externalBin</code> — ЦЕ ВХІДНІ ДАНІ ЗБИРАННЯ, А НЕ ЛИШЕ ПАКУВАННЯ.</strong> Скрипт збирання Tauri відмовляється збирати <code>src-tauri</code> <strong>взагалі</strong>, якщо sidecar не існує для триплета хоста, — навіть звичайний <code>cargo clippy</code> чи <code>cargo test</code>, а не лише <code>tauri build</code>. Тож виправлення для <em>«жоден інсталятор не містив пісочниці»</em> одразу зламало всі три завдання <code>quality</code> з","changelog.c5df1463b340":"⛔ <strong>А <code>npm run ci:local -- --slow</code> показував 18/18, поки це було так.</strong> На машині, яка додала оголошення, лежав sidecar, підготовлений попереднім ручним запуском скрипту збирання, тож кожен локальний запуск відтоді тихо залежав від файлу, який залишила <em>інша</em> команда. ⚠ Запускач, що так робить, не відтворює середовище CI, а це його єдине призначення, — і це вже вдруге в цьому проєкті зелений локальний набір стояв над зламаним деревом.","changelog.18fb4b406b6c":"⚠ Тепер робочий процес готує sidecar <strong>перед</strong> перевірками Rust, а не після них; <code>ci-local.mjs</code> сам готує його першою перевіркою; а <code>ci_stages_the_sandbox_before_anything_that_builds_this_crate</code> перевіряє <strong>порядок</strong>, бо крок підготовки, що виконувався після перевірок, — це саме те, що вже було, і саме те, що зламалося. ⚠ <code>--debug</code>, бо в цьому завданні нічого не пакується, а скрипт збирання лише перевіряє, що шлях існує.","changelog.4773f02d6a28":"⚠ <strong>Завдання <code>release</code> проходили весь час</strong>, бо <code>npm run tauri:build</code> спершу запускає скрипт підготовки. Зачепило лише ті завдання, що збирають крейт без пакування, — ось чому нічого локального цього не впіймало.","changelog.6014a99b778f":"Додано — жоден тест у наборі ще ніколи не давав пристрою короткий останній блок","changelog.0565b063c7c7":"⛔⛔ <strong>КОЖНА КІЛЬКІСТЬ КАДРІВ У НАБОРІ ПЕРЕВІРОК БУЛА ТОЧНИМ КРАТНИМ РОЗМІРУ ЇЇ БЛОКУ.</strong> 1 024 кадри з блоком 64, 4 096 — з 2 048, 8 192 — з 64 у перевірці тиші, тож на <strong>сімдесяти п'яти пристроях і чотирьох розмірах блоку жоден пристрій ні разу не мав обробити неповний блок.</strong> Пристрій, що читав <code>block</code> там, де мав читати <code>frames.min(block)</code>, був би тут скрізь зеленим.","changelog.9fb238124783":"⚠ <strong>Справжній рушій постійно видає короткі блоки</strong>: кінець проміжку, межа циклу, власна компенсація затримки пристрою. Це знайшлося під час скорочення часу роботи набору, а не через збій, — і в цьому неприємна частина, бо інакше цього ніщо б не знайшло.","changelog.1ee0368d2be0":"⚠ <code>frames_for</code> тепер віднімає половину блоку, тож <strong>кожен розмір блоку закінчується неповним блоком</strong>, а <code>every_block_size_ends_on_a_short_block</code> стверджує цю властивість допоміжної функції, а не довіряє коментарю, — інакше розмір блоку, доданий до <code>BLOCKS</code>, який випадково ділить націло, мовчки повернув би набір туди, де він був. ⚠ До того ж це приблизно на п'яту частину <em>дешевше</em> — рідкісний напрямок для виправлення покриття.","changelog.b032786ec60c":"⚠ <strong>Перевірка виділення пам'яті — третій рядок тієї таблиці</strong>, і саме вона зробила картину видимою: коли її навчили завантажувати семпл і вдаряти акорд, її час зріс із двадцяти секунд до понад двадцяти хвилин за один коміт. Тепер вона будує пристрій один раз, причому кожне налаштування й досі відвідується в тому самому порядку, а кожен блок прогріву на місці, — <strong>64 секунди, і досі червона, якщо повернути <code>Vec</code> у <code>process</code>.</strong>","changelog.e90a16ca644f":"Додано — зерно можна перекинути, і шість пристроїв прокинулися","changelog.3f0ff3b92998":"⛔⛔ <strong><code>ops::reroll_seed</code> НЕ МАВ ЖОДНОГО ВИКЛИКАЧА, І ЦЕ ВЖЕ ВСЬОМЕ.</strong> Зерно проєкту є в моделі ще з фази 3; воно їде разом з індексом аранжування й доходить до <code>Context::seed</code>; шість пристроїв беруть із нього кожне випадкове рішення. <strong>Ніщо в інтерфейсі не могло його змінити</strong>, тож кожен із цих шести мав рівно одну поведінку на все життя проєкту, — і кожна перевірка, яка створювала <code>Context</code> вручну, лишалася зеленою, бо створений вручну контекст може нести будь-яке зерно.","changelog.96d0a4ae4376":"⚠ Тепер є <strong>кнопка ⚄ на панелі інструментів аранжування</strong>, поруч із темпом, бо зерно — це властивість пісні, а не машини. Нове число генерує той, хто викликає, і передає в операцію, тож знову відкритий проєкт звучить так само, як збережений: операція, що сама кидала б кості, при повторі дала б інший результат.","changelog.aaf264952da8":"Змінено — модальне вікно розмиває сесію за собою","changelog.109a1280400d":"⚠ Вказівка власника: <em>«коли будь-яке модальне вікно з'являється над DAW, фонові частини DAW мають бути розмиті, і видимим має бути лише це модальне вікно»</em>. Сама лише затемнювальна підкладка лишає кожен фейдер і кліп за нею читабельними. <code>backdrop-filter</code> на підкладці, а не фільтр на корені застосунку: фільтр застосовується до всього піддерева й розмив би також діалог. ⚠ Виміряно на випущеному бінарнику: високочастотна енергія Провідника файлів падає з 7.18 до 3.94, коли діалог відкритий.","changelog.b509ead0e07f":"Додано — кожен елемент керування кожною мовою (фаза 7)","changelog.3fdf63211c68":"⛔⛔ <strong>Панелі говорять усіма вісімнадцятьма мовами.</strong> 482 різні підписи елементів керування на 69 зібраних пристроях, перекладені в усі каталоги, з якими постачається Oscillate, — остання річ у фазі 7, що досі всюди була англійською.","changelog.9b5cef558932":"⚠ <strong>Підпис і його підказку в рядку стану було переставлено в усіх вісімнадцяти каталогах.</strong> <code>arrangement.metre</code> містив речення <em>«Розмір проєкту — скільки долей у такті й чому дорівнює доля.»</em>, а <code>hints.metre</code> — слово <em>«Розмір»</em>, тож панель інструментів аранжування малювала перенесений абзац там, де має бути підпис з одного слова. Ніщо не могло цього впіймати: обидва рядки існували, обидва були перекладені, а перевірка паритету порівнює каталоги між собою — і кожен був хибним однаково. Тепер є перевірка <em>форми</em>: підпис — це слово, підказка — речення.","changelog.e4e709b8830c":"▶ <strong>Галузева конвенція — це не те саме, що перекласти все.</strong> <code>Gain</code>, <code>Attack</code>, <code>Release</code>, <code>Threshold</code>, <code>Ratio</code>, <code>Low Cut</code> лишаються як є в німецькій, французькій, іспанській, італійській, нідерландській та інших, бо саме це продюсер читає в кожній іншій DAW, яку відкривав, — Cubase і Studio One постачаються з німецькими панелями саме з цими словами. Передати їх як <code>Verstärkung</code>, <code>Ansprechzeit</code> і <code>Schwellwert</code> — правильна німецька, але <strong>більш</strong> чужа, а не менш. ⚠ Просто описову лексику — <code>Frequency</code>, <code>Level</code>, <code>Width</code>, <code>Length</code>, <code>Size</code>, <code>Noise</code>, <code>Material</code> — перекладено скрізь.","changelog.7983ad8fb373":"⚠ <strong>Японська, корейська, китайська, російська, українська, арабська й гінді не зберігають жодного латинського тексту</strong>, бо їхні власні DAW цього не роблять: катакана <code>アタック</code>, хангиль <code>어택</code>, <code>起音</code>, <code>Атака</code>. Це та сама конвенція, що дає іншу відповідь, і <strong>жодна з цих семи не фігурує у списку збереженої англійської</strong> — усі 319 перевірено в усіх семи.","changelog.b7c89628b394":"⛔ <strong>Ключ обчислюється в Rust, із підпису.</strong> <code>Gain</code> — це <strong>один</strong> рядок для всього переліку, а не одинадцять, як було б із ключем для кожного пристрою, а перейменований елемент керування дає ключ, який перевірка локалей називає відсутнім, замість панелі, що тихо відкочується до англійської, поки всі тести зелені.","changelog.15e32938dfa3":"⚠ <strong>Сітка складається з шаблону для кожної мови, а не виписана шістдесят разів.</strong> <code>Band 1 Frequency</code> … <code>Band 4 Shape</code> і чотирисмугова сітка динаміки відрізняються лише цифрою чи смугою, тож кожна мова один раз задає власний порядок слів. ⛔ Перша спроба використовувала одну форму на смугу й видала <code>Hoch Ratio Up</code>, <code>Высокие Соотношение вверх</code> і <code>Tief Decay</code> — усе граматично хибне. Слово смуги, що стоїть окремо на регуляторі тембру, — не те слово, яке уточнює інший іменник: німецькій потрібні <code>Höhen-</code> і дефіс, а російській та українській — <strong>родовий відмінок</strong> і місце <em>після</em> терміна. Тепер обидві форми задано окремо.","changelog.94784bd56e51":"⚠ <strong><code>Look Ahead</code> і <code>Lookahead</code> були одним елементом керування, написаним двома способами</strong>: три пристрої писали так, два — інакше. Уніфіковано на <code>Lookahead</code>, як писала більшість і як друкують сучасні лімітери. Це на один дубльований переклад менше у вісімнадцяти мовах, а тепер перевірка відхиляє два підписи, що різняться лише пробілами чи регістром.","changelog.99966156003c":"Додано — чотири механізми, які працювали правильно, але їх ніхто не викликав (фаза 7)","changelog.f9e8e0604480":"⛔⛔ <strong>Oscillate не міг зіграти ноту.</strong> Ні з віртуальної клавіатури, ні з апаратної. Модуль <code>midi</code> з <code>oscillate-audio</code> — <code>ports()</code>, <code>Input::open()</code>, <code>EventQueue</code>, <code>Filter</code>, <code>decode()</code> — був зібраний, протестований і <strong>не використовувався жодним крейтом, крім власного</strong>; <code>NoteBank</code> наповнював лише потік відтворення, з кліпів. Тож кожен інструмент із переліку можна було додати на доріжку, і жодним не можна було зіграти. <code>live.rs</code> — це відсутній шлях, і це <strong>одна</strong> черга, бо віртуальна клавіатура й MIDI-порт — це та сама подія, що заходить різними дверима: два шляхи були б двома відповідями на те, що означає велосіті, двома правилами all-notes-off і двома рішеннями про те, що відбувається, поки транспорт рухається, — і хибним виявився б той, яким користуються рідше.","changelog.dccd39d3b268":"⛔⛔ <strong><code>Waypoint</code>, <code>Guard</code> і <code>Lantern</code> на кожному блоці читали <code>next_section_ticks: None</code>, і так без кінця.</strong> Погляд уперед — головна заява цієї фази: <em>плагінові кажуть, де курсор відтворення, але ніколи — що попереду</em>, — а <code>graph.rs</code> будував свій <code>Context</code> з <code>..Context::default()</code>. Три фірмові пристрої були звичайними компресором, гейтом і затримкою з мертвим регулятором «Випередження». ⚠ <strong>Кожна перевірка лишалася зеленою, бо кожна будувала власний <code>Lookahead</code> і передавала його.</strong> Усі питали, чи пристрій на нього <em>реагує</em>; жодна не спитала, чи він його взагалі <em>отримує</em>. Та сама картина, що й із недосяжністю переліку з браузера, і її знаходить те саме питання: <em>що продюсер насправді натисне?</em> Тепер структура аранжування обчислюється поза аудіопотоком і передається вниз як відносні тіки.","changelog.022bbad0846a":"⛔ <strong>Шов для семплів і один голос за кожним пристроєм, що грає файл.</strong> Сім інструментів були <code>Declared</code> саме через це й ні через що інше. Пристрій будується з <code>type_id</code> і списку <code>f64</code>, а шлях — ні те, ні інше: <code>ParamSpec</code> несе числа, бо аудіопотік не може бачити <code>String</code>, — тож семпл не міг прийти як елемент керування. Натомість він приходить як підміна <code>Arc&lt;SampleData&gt;</code>, декодована у фоновому потоці. ⚠ <strong>Пастка — у звільненні</strong>: відпускання останнього <code>Arc</code> звільняє пам'ять у тому потоці, який його відпустив, тож аудіопотік повертає старий назад, а не звільняє його. ⚠ Зчитувальна головка була в <code>delay::sinc_read</code> ще з AM-A1, задокументована як <em>«для семплера»</em> — написана, протестована й недосяжна для жодного семплера, бо жодного семплера не можна було написати. Один голос обслуговує їх усіх: пул створюється в <code>prepare</code>, після цього пам'ять ніколи не виділяється, голос забирається спершу в найтихішої ноти, потім у найстаршої, і <strong>затухає, а не обривається</strong>, бо жорсткий обрив на довільному семплі — це клацання на повному рівні, і лунає воно саме тоді, коли продюсер грає.","changelog.47a37733c964":"▶ <strong>У переліку 63 із 75, а було 54.</strong> Дев'ять пристроїв зійшли зі списку заблокованих: <code>Sift</code>; нотні пристрої <code>Weave</code>, <code>Tread</code> і <code>Revoice</code>; і семплери <code>Flint</code>, <code>Armory</code>, <code>Bench</code>, <code>Hammer</code> і <code>Filings</code>. ⚠ <strong>Усі 28 основних ефектів уже були зібрані</strong> — кожен із цих пристроїв був заблокований швом, а не чиїмось часом, ось чому закриття трьох швів зрушило дев'ять пристроїв.","changelog.16d4769379c4":"Додано — діліться тим, що створили (фаза 7, TASK-084 і TASK-084A)","changelog.dbcd3e927b1f":"⛔⛔ <strong>Налаштування пристрою вміщаються в один рядок, який можна вставити в чат.</strong> Ні файлу, ні завантаження, ні облікового запису — саме так спільнота насправді обмінюється звуками.","changelog.f0988a917537":"▶ <strong>Кожен рядок, що надходить, вважається ворожим</strong>, бо прийшов від незнайомця через вікно чату. Довжина перевіряється <strong>ще до будь-якого виділення пам'яті</strong>; невідомий пристрій відхиляється за назвою, а не вгадується; кожне значення перевіряється на діапазон власного елемента керування, і рядок за його межами <strong>відхиляється, а не обрізається</strong>: обрізання перетворює пошкоджений рядок на пристрій, який виглядає правильно, а звучить хибно, — збій, якого продюсер не здатен діагностувати. <code>NaN</code> розбирається як число й теж відхиляється: потрапивши у стан фільтра, він заглушив би доріжку до кінця сесії, і нічого на панелі не пояснило б чому.","changelog.94eaa1442544":"⛔ <strong>Нічого не застосовується, доки ви не прочитаєте, що зміниться.</strong> Панель перелічує елементи керування, що зрушать, — з якого значення й на яке, — через власний форматувальник DSP, тож попередній перегляд не може показати число, якому ручка потім суперечитиме, — і лише тоді пропонує застосувати зміни як <strong>один крок скасування</strong>. ⚠ Вставлення відбувається в текстове поле, а не через читання буфера обміну: <code>readText()</code> просить в операційної системи все, що ви скопіювали востаннє, а поле не просить нічого.","changelog.ac55cb626b91":"⚠ <strong>Рядок не використовує deflate</strong>, хоча ескіз у § F-18 це пропонував. Метою було менше 200 символів, а для всього переліку рядок без стиснення значно коротший за половину цього, тож стиснення купило б символи, яких ніхто не рахує, ціною двох залежностей у дереві, де перевірка ліцензій зупиняє збірку. Байт версії є, щоб майбутній пристрій, якому це знадобиться, міг його мати.","changelog.504a5ab9a3c1":"⛔⛔ <strong>А ЦІЛА СТІЙКА ЗБЕРІГАЄТЬСЯ ЯК ФАЙЛ.</strong> <em>«Чи можна зберігати групи VST3 з їхніми налаштуваннями як пресети — або групи вбудованих плагінів?»</em> — так, і те, й інше, по порядку, з елементами керування кожного пристрою, станом обходу й власним непрозорим станом його плагіна. Це <em>Audio Effect Rack</em> з Ableton і <em>mixer state</em> з FL, і ніщо цього не покривало: рядок-рецепт — це <strong>один</strong> пристрій, а вокальний ланцюжок із чотирьох узагалі не було як зберегти.","changelog.f81450b45e4f":"<strong>Файл, а не рядок, і ця відмінність несуча.</strong> Стан вбудованого пристрою — це жменька чисел. Стан плагіна в хості — непрозорий блоб виробника, і зазвичай це мегабайти; серіалізатор, що спробував би зробити його придатним для вставлення, або обрізав би його, або видав би щось, чого ніхто не зможе надіслати.","changelog.a3f286b4c94a":"⛔ <strong>Пресет, що називає плагін, якого у вас немає, УСЕ ОДНО ЗАВАНТАЖУЄТЬСЯ</strong> — зі збереженням його налаштувань, стану й позиції в ланцюжку, намальований як заглушка, що пропонує <em>Знайти…</em>. Відхилити весь пресет через один відсутній пристрій — саме так спільний пресет стає непотрібним.","changelog.9acecd496795":"⚠ <strong>Він записує те, чого не може пообіцяти.</strong> Пресет несе версію плагіна, з якою його збережено, і завантаження з іншою версією відновлює стан і <strong>каже про це</strong>: виробник може змінювати значення стану між випусками, а тихо завантажити зіпсований стан гірше, ніж попередити.","changelog.359fe5e52aef":"⛔ <strong>Пресет ніколи не несе значення затримки.</strong> Затримка — це те, що пристрій <em>повідомляє</em> під час завантаження; файл, який міг би її задавати, дозволив би пресету незнайомця розладнати кожну доріжку вашого проєкту, і ви почули б це так, ніби збився ваш власний таймінг.","changelog.c7548c290126":"Це <strong>той самий контейнер, що й <code>.oscillate</code></strong>, і так задумано: магічне число, відмова за версією, перевірка кількості фрагментів до резервування каталогу й перевірена арифметика на кожному зсуві — усе це там уже правильне, а друга копія всього цього якраз і була б тією, де помилилися б.","changelog.6dc3815f5a01":"Додано — набір перевірок для всього переліку (фаза 7, TASK-193)","changelog.27da05681148":"⛔⛔ <strong>Жоден вбудований пристрій не виділяє пам'ять під час обробки — і це виміряно, а не припущено.</strong> Кожен зібраний пристрій, на кожному крайньому значенні параметрів і з усіма елементами керування на максимумі водночас, проганяється через <strong>лічильний глобальний алокатор</strong>, який живе в наборі тестів аудіопотоку <code>oscillate-audio</code>, бо процес отримує рівно один, і він уже там. ⚠ Бачили, як перевірка падає на пристрої, навмисно зіпсованому так, щоб виділяти вісім float. ▶ Розділ 3 філософії збирання каже: жодного виділення пам'яті в аудіопотоці; досі це було правило, за яким стояв огляд коду, а не вимірювання.","changelog.c1dd75c564d7":"⛔⛔ <strong>Один набір, і він обходить реєстр, а не список, який хтось підтримує</strong>, — тож пристрій, доданий завтра, потрапляє в кожну перевірку, і нікому не треба пам'ятати, що його слід додати. Чотирнадцять перевірок: жодного виділення пам'яті на чотирьох розмірах блоку й на кожному крайньому значенні параметрів, оголошена затримка проти виміряної, тиша на вході — тиша на виході, детермінізм для кожного зерна, нотні пристрої, які повідомляють про переповнення, а не гублять акорд, жодних завислих нот після all-off, намальована крива проти звуку, структурна перевага й жодної записаної імпульсної характеристики ніде в дереві.","changelog.ef1f383d949f":"▶ <strong>Чотири з них стверджують ВІДСУТНІСТЬ, і кожна має пару — твердження про наявність</strong>, бо перевірка, що стверджує відсутність, тривіально проходить на пристрої, який нічого не робить. Спершу треба показати, що набір справді пройшов реальним переліком, змінив реальний сигнал, заповнив реальний буфер нот.","changelog.a1f70e07df67":"<strong>Три справжні дефекти, знайдені під час його написання:</strong>","changelog.9c3286495065":"⛔ <strong><code>Furnace</code> малював свій тоностек і пропускав два етапи власного аудіошляху</strong> — яскравий конденсатор паралельно регулятору підсилення й спад вихідного трансформатора — і <strong>розходився на 2.9 дБ на 4 кГц</strong> із тим, що робив насправді. Крива без етапу — це прикраса пристрою, а не його вимірювання. Виправлено, і тепер крива відстежує звук із точністю до десятої децибела.","changelog.fc2768b6fb8d":"⛔ <strong><code>Lantern</code> виглядав так, ніби ігнорує аранжування</strong>, але це не так: рендер перевірки тривав 8 192 семпли, а його затримка — 12 000, тож нічого ще не повернулося. Перевірка, що вимірює хвіст, має працювати довше за нього.","changelog.44daac3f8f13":"⛔ <strong>«Оголошена затримка — це там, де імпульс досягає піку» — хибне твердження</strong>, і два пристрої доводять це в протилежних напрямках. <code>Toll</code> оголошує нуль, а пік має на 1 332 — це резонатор, і його дзвін наростає після імпульсу, що пройшов наскрізь. Вікно <code>Strand</code> дзвенить за 517 семплів <em>до</em> свого піку. Обидва оголошення чесні; вимірювання — ні. Тепер перевірка вимірює, де відгук <strong>починається</strong> і де він <strong>досягає піку</strong>, і стверджує те, що може довести кожне: ніщо не може прийти пізніше за оголошене й ніщо не може досягти піку раніше.","changelog.9e568642d580":"⚠ <strong>Частотна характеристика — величина малого сигналу, і для двох пристроїв це довелося сказати вголос.</strong> <code>Furnace</code> відповідає −7.97 дБ на 80 Гц на тон −20 dBFS і −0.01 дБ на тихий, бо перший компресується. Вау й флатер <code>Oxide</code> рухають позицію читання, а це частотна модуляція: стабільний тон 4 кГц втрачає 3 дБ у бічні смуги, яких жодна амплітудна крива ніколи б не намалювала. Перевірка зупиняє модуляцію й вимірює тихим сигналом, і в обох місцях пояснює чому.","changelog.ae6713aae737":"Додано — пристрої, якими не міг би бути жоден плагін (фаза 7, AM-C)","changelog.ccec0b2bb36e":"⛔⛔ <strong>Три з них читають аранжування, і це не довший буфер.</strong>","changelog.525a54a16b01":"▶ Читати два такти <em>звуку</em> наперед — це затримка, і за неї платить кожен продюсер у сесії. Читати <em>структуру</em> аранжування на два такти наперед не коштує <strong>нічого</strong>: приспів на такті 33 незалежно від того, чи його вже хтось зіграв. Жоден формат плагінів не відкриває аранжування хоста, тому такі пристрої можуть існувати лише всередині DAW, яка їх і написала. Усі три оголошують <strong>нульову затримку</strong>, а їхня перевірка полягає в тому, що зміна структури без зміни жодного семпла змінює те, що вони роблять.","changelog.2d95b40d737e":"<strong><code>Waypoint</code> уже тримає приспів, коли той настає</strong>, а не реагує на нього на кілька мілісекунд пізніше.","changelog.61058866fd1f":"<strong><code>Guard</code> відкривається для удару, якого ще не сталося.</strong> Поріг так не може: поки рівень його досягне, транзієнт уже минув.","changelog.0a518a9dfc80":"<strong><code>Lantern</code> скидає затримку В ТАКТОВУ РИСКУ</strong>, тож хвіст доходить до кінця, а не обрізається. Обрізання — це клацання, а цей пристрій існує, щоб уникнути безладу, який дає ручне скидання.","changelog.3adaa073b4e9":"⛔ <strong>Ще три перекидаються однаково із зерна проєкту</strong>, тож заїкання, що звучало правильно на третьому проході, лишається й на сороковому, — а перекидання — це одна операція, яку можна скасувати, а не азартна гра. <code>Feint</code>, <code>Wear</code> і <code>Skywave</code>.","changelog.faf2b04e72fd":"<strong><code>Gild</code> дає вибрати гармоніки.</strong> Вейвшейпер дає ту суміш, яка випадає з його кривої; базис Чебишова відповідає саме тією гармонікою, яку попросили, тож друга й п'ята — окремі регулятори, що роблять окремі речі.","changelog.388e74d46c0c":"<strong><code>Toll</code> змушує будь-який звук дзвеніти, як ударений предмет</strong>, і керується власними транзієнтами входу, — тож малий барабан через трубу дзвенить, як труба, по якій ударили малим барабаном, а витримана нота її ледве збуджує.","changelog.72e4b3c8680a":"<strong><code>Vault</code> обчислює реверберацію з кімнати в метрах.</strong> Розміри визначають час приходу відбиттів і довжини ліній резервуара: перше відбиття сорокаметрової кімнати справді приходить учетверо пізніше, ніж трьохметрової.","changelog.3ab7f011c6f7":"<strong><code>Cleave</code> відокремлює удари від тону</strong>, питаючи про кожну точку спектра, чи вона гучна <em>зараз</em> і тиха за мить до й після — це удар, — чи гучна <em>тут</em> і тиха на бін вище й нижче — це нота. Йому не потрібен поріг і не треба нічого вчити: це твердження про форму звуку.","changelog.34f872d520d1":"<strong><code>Strand</code> перебудовує звук із часткових тонів, які в ньому знаходить</strong>, тож подих і шум смичка можна приглушити окремо від нот.","changelog.7af3df17572e":"⚠ <strong>Заяву «жоден плагін не міг би цього» перевірено заново щодо того, що випущено, а не щодо того, що було в специфікації</strong>, — саме цього вимагає перевірка фази 7, бо перебільшення в специфікації стає перебільшенням у маркетингу. ▶ <strong>Шість</strong> з одинадцяти на неї заслуговують: три читають структуру аранжування (<code>Waypoint</code>, <code>Guard</code>, <code>Lantern</code>), а три детерміновані від зерна проєкту (<code>Feint</code>, <code>Wear</code>, <code>Skywave</code>) — ні того, ні іншого не відкриває жоден формат плагінів. Інші п'ять — <code>Gild</code>, <code>Toll</code>, <code>Vault</code>, <code>Cleave</code>, <code>Strand</code> — це самобутній DSP, і їх описано вище за власними заслугами, без заяви, що їх не можна було б написати як плагіни. README казав «одинадцять», а тепер каже «шість».","changelog.a8c23b6590a7":"Додано — три барабанні голоси, змодельовані, а не засемпловані (фаза 7, SP-02)","changelog.b45e2a05e0f9":"<strong><code>Skin</code> — це вдарена мембрана, а не семпл.</strong> Його часткові тони — нулі функцій Бесселя: другий у 1.59 раза вищий за перший, а не вдвічі, і в цьому вся різниця між барабаном і нотою з висотою. Місце, куди влучає колотушка, визначає, які моди збуджуються, сила удару — як довго вона лишається в контакті, а струни малого барабана брязкають, лише коли пластик рухається достатньо, щоб їх підкинути. <strong>Бочка тримає висоту з точністю до цента впродовж чотирисекундного загасання.</strong>","changelog.e1820ecc0952":"<strong><code>Bronze</code> — це дисперсійна пластина.</strong> Шістдесят чотири часткові тони, що розходяться в міру підйому, — ось чому тарілка звучить суцільною пеленою, а струна — акордом. Педаль хай-хета справді його затискає: у закритому стані хвіст коротший більш ніж на двадцять децибелів, а рух триває стільки, скільки каже регулятор «Закриття».","changelog.da5d0b60ebad":"<strong><code>Sideband</code> — це чотириоператорний FM</strong> із вісьмома алгоритмами, з передискретизацією, а оператор зворотного зв'язку тримається нижче одиниці і в DSP, і на панелі: оператор, що модулює сам себе на одиниці, — це генератор шуму, який ніколи не повертається.","changelog.d99f1f1c0dab":"⛔ <strong>Ті самі параметри рендерять той самий удар</strong> — щоразу, на кожній машині. Кожен генератор отримує нове зерно, коли голос скидається, а не продовжує з того місця, де випадково опинився, тож зведення звучить так, як було почуто.","changelog.87dbbf51c469":"Додано — що відбувається з партією, перш ніж її зіграють (фаза 7, AM-D1)","changelog.66e2e630602a":"⛔⛔ <strong>Нотному пристрою тепер є де працювати</strong>, а досі не було.","changelog.0b00d82af6a6":"▶ <strong>Шістнадцять пристроїв були в переліку, але не мали шва, у якому працювати.</strong> Вбудований пристрій міг писати лише звук, тож арпеджіатор не мав як видати ноту; а код, що будував лінійку мікшера, викидав кожен нотний пристрій із ланцюжка — з коментарем, який про це казав. Бракувало механізму, а не написаних пристроїв, — і це вже вп'яте цей проєкт натрапляє на таку картину.","changelog.06268f644505":"<strong>Арпеджувати, гармонізувати, олюднювати, повторювати луною, виправляти й мутувати партію</strong> — у ланцюжку, перш ніж її почує інструмент. Одинадцять із шістнадцяти зібрано.","changelog.2308ba050970":"⛔ <strong>Ніщо тут не може залишити завислу ноту.</strong> Це вимога до кожного пристрою: коректор зсуває note-off так само, як зсунув її note-on, будівник акордів відпускає кожен голос, який озвучив, а власні ноти арпеджіатора зупиняються разом із транспортом.","changelog.f94d5f02304a":"⛔ <strong>Кожен пристрій із випадковістю перекидається однаково із зерна проєкту</strong>, тож зведення звучить так, як було почуто. <code>Scatter</code> бере висоту, велосіті й таймінг із трьох окремих потоків, тож перекидання одного лишає інші побайтово тими самими — продюсер може виправити таймінг партії, не втративши нот, які йому сподобалися.","changelog.b7a88dfc6644":"<strong>Нотний ланцюжок, якому забракло місця, каже про це</strong>, і лічильник зберігається. Арпеджіатор, що тихо загубив акорд, був би дефектом, знайденим через тиждень.","changelog.acc86def0061":"<strong><code>Temper</code> піднімає й зрізає ту саму частоту, і вони не взаємознищуються.</strong> У цьому весь сенс пасивного програмного еквалайзера, і саме в цьому помиляється кожна імітація, побудована на основі параметричного: підйом і зріз ділять котушку індуктивності, тож по 6 дБ кожного на 100 Гц лишають під собою <strong>+2.0 дБ</strong> і провал <strong>−1.4 дБ</strong> на 180 Гц, а не рівну лінію.","changelog.b3d85a912eee":"<strong><code>Strata</code> розділяє чотири смуги, які в сумі дають те, що зайшло.</strong> З точністю <strong>0.01 дБ</strong> на кожній ділянці кросовера, а для цього потрібні всепропускні корекції на смугах, що оминули кросовер, — без них багатосмуговий процесор дає гребінчастий ефект саме там, де він має працювати. Кожна смуга компресує донизу й піднімає вгору від <strong>одного</strong> детектора, тож дві половини не можуть розійтися.","changelog.33d3cfb69d0c":"<strong><code>Stance</code> побітово ідентичний, коли ви нічого від нього не просили.</strong> Не «досить близько» — на виході ті самі числа, що й на вході. Кожен етап пропускається, а не працює з одиничним підсиленням, бо фазообертач і кросовер — це всепропускні мережі, а всепропускний фільтр, залишений працювати, розмазує кожен транзієнт на доріжці заради регулятора, якого ніхто не торкався.","changelog.85c6c680dbe0":"<strong>Три ревербератори, один резервуар, і «дві секунди» означають дві секунди в усіх трьох.</strong> <code>Chamber</code>, <code>Foil</code> і <code>Coil</code> ділять шістнадцятилінійну мережу затримок зі зворотним зв'язком з ортогональною матрицею змішування, тож час загасання задає регулятор загасання й ніщо інше: виміряний RT60 потрапляє <strong>в межі 5 %</strong> від того, що показує панель, від 0.2 секунди до 12.","changelog.790ef72775e3":"<strong><code>Coil</code> капає, і крапання — це сам механізм, а не враження від нього.</strong> Пружина несе низькі частоти повільніше за високі, тож імпульс повертається як низхідний чирп; кожна пружина — це 120 дисперсійних всепропускних етапів, що дає 38 мс затримки на 500 Гц проти 7.6 мс на 4 кГц. Резервуар має один набір пружин і два звукознімачі — звідси його стерео, а не від того, що все проганяється двічі.","changelog.13fe8240a909":"<strong>Баси <code>Foil</code> не дзвенять довше за верхи</strong> — саме це відрізняє пластину від малої зали, і саме в цьому помиляється кожна емуляція пластини.","changelog.cbb8261f8b1b":"<strong>Повтори <code>Spool</code> щоразу стають глухішими й бруднішими</strong>, бо насичення й втрати в зазорі головки стоять усередині петлі зворотного зв'язку, а не на виході. Стрічка чи bucket brigade: смуга пропускання bucket-шляху опускається разом із його тактовою частотою, тож довга затримка — темна затримка, і саме такою є справжня bucket-brigade-схема, а не затримка з фільтром після неї.","changelog.3ed31dd895e1":"<strong><code>Comb</code> — справжній флейнджер із проходом через нуль.</strong> Сухий шлях теж затримується, тож модульований проходить крізь нього й виходить з іншого боку; у точці перетину обидва несуть ті самі семпли з точністю понад <strong>60 дБ</strong> — таке погашення недосяжне для флейнджера, який може лише наблизитися до нуля. ⚠ Ця суха затримка — справжня затримка, і її оголошено, тож перемикач не зсуває доріжку раніше.","changelog.bd48e1488259":"<strong><code>Sparks</code> транспонує без дрейфу</strong>, точніше ніж до тисячної частки цента в діапазоні ±24 півтони, а його вікна гранул у сумі дають одиницю за будь-якої щільності, а не лише на тому одному перекритті, де це випадково вдається вікнам Ганна.","changelog.f57ce8edbf1a":"<strong><code>Shoal</code> зберігає ширину при зведенні в моно.</strong> Розширення не зсуває моносуму анітрохи — на будь-якій ширині й будь-якій частоті, — бо сума й ширина будуються окремо, а не так, що ширина — це трюк із полярністю, який гаситься при зведенні в моно.","changelog.cee1b6a54d95":"<strong>Стрічка <code>Oxide</code> глухіша на 7½ ips, ніж на 15</strong>, і ще глухіша, коли головка зношується, — бо головка відтворення не може розрізнити довжину хвилі, коротшу за власний зазор, а це <code>|sin(x)/x|</code> і один рядок, а не крива, яку хтось намалював. Її головковий горб із тієї ж причини рухається зі швидкістю стрічки, і вона спотворює фронт, що наростає, інакше, ніж той, що спадає, — так поводиться магнітна петля, а вейвшейпер так не може.","changelog.1910ed335a88":"<strong><code>Furnace</code> піддається, а не просто стає квадратнішим.</strong> Його живлення просідає під струмом вихідних ламп, тож акорд тягне шини живлення вниз, і наступна нота тихіша, доки вони не відновляться: <strong>4 дБ компресії на 6 дБ понад кліпінг</strong>, і регулятор «Просідання» справді впливає на це число.","changelog.e79ee3f59a10":"<strong>У <code>Baffle</code> немає імпульсних характеристик, і це буквально.</strong> Резонансний динамік, пік розпаду дифузора, фазоінверторне налаштування, сходинка від краю панелі, мікрофон із відстанню й віссю і невелика кімната — кожне з цього коефіцієнт, а не файл. Дванадцятидюймовий динамік резонує на 75 Гц, п'ятнадцятидюймовий нижче, восьмидюймовий вище.","changelog.79387b24db13":"<strong>Вони звучать у застосунку, а не лише в тесті.</strong> Пристрій на доріжці будується разом із планом рендерингу, працює між сумою лінійки мікшера та її фейдером — там, де стоїть інсерт, — а затримка, яку він оголошує, — це те, до чого вирівнюються всі інші доріжки. ⛔ Є рівно одне місце, де можна сконструювати вбудований пристрій, і воно повертає затримку в тому самому виклику, тож одне не може розійтися з іншим.","changelog.3a625cdcb34b":"<strong>Панель, яку справді можна крутити.</strong> Одна оболонка для кожного пристрою, щоб вони читалися як родина, і одна панель, намальована з опису самого пристрою. ⛔ Панель ніколи не форматує число: вона отримує рядок, який зробив власний форматувальник DSP, тож показник не може розходитися з тим, що ви почуєте.","changelog.7e1fc34d1868":"<strong>Елементи керування, що поводяться як елементи керування.</strong> 270° ходу, коефіцієнт перетягування під руку, <code>Shift</code> для точного налаштування — який показує, яку десяткову цифру він дав, — зона захоплення, точна біля центру й груба по краю, фіксатори, що <strong>опираються, а не клацають</strong>, тож біполярний регулятор усе ще можна поставити на +0.3 дБ, <code>Alt</code>-клацання й подвійне клацання для скидання, коліщатко, повне керування з клавіатури й перетягування, яке продовжує відстежуватися, коли виходить за межі панелі.","changelog.5c54fb29c894":"<strong>Кожен пристрій каже, чого він вам коштує.</strong> Пристрій із затримкою показує її — у семплах і мілісекундах — на власній панелі.","changelog.8e0f56dd7bcb":"<strong>MIDI-кліп видає звук.</strong> Інструмент на доріжці отримує ноти, які містить аранжування, з точністю до семпла в межах блоку, а його вихід — це те, з чим працюють ланцюжок і фейдер лінійки мікшера. ⚠ До цього ноти доходили до графа й там зупинялися.","changelog.2e43c657f195":"Додано — Oscillate стерео від початку до кінця (фаза 7)","changelog.587ea2844a2a":"⛔ <strong>Кожен аудіошлях в Oscillate тепер несе два канали.</strong> Раніше ніс один, і це не було обмеженням, лише згаданим у коментарі:","changelog.be58cc9d5843":"<strong>Стереофайл грає в стерео.</strong> Стереоімпорт усереднювався в один канал потоком відтворення ще до того, як потрапляв у граф рендеру. Продюсер міг імпортувати стереозведення, дивитися на стереохвилеформу й слухати центральну суму — і ніщо ніде про це не казало.","changelog.ddf594435dd8":"<strong>Кожна лінійка мікшера має панораму, яка працює.</strong> Поканальної панорами в продукті не було взагалі: закон панорамування застосовувався один раз, на мастері.","changelog.8ac7863b5f5d":"⛔ <strong>Панорама і баланс — це два різні закони, і Oscillate використовує обидва.</strong> Моноджерело <em>розміщується</em> з постійною потужністю, тож під час панорамування його гучність не змінюється. Сигнал, який уже є стерео, <em>нахиляється</em> з одиничним підсиленням, тож шина, що передає його далі, його не послаблює. Застосовувати закон розміщення в кожній точці підсумовування — саме так мікс непомітно втрачає 3 дБ на кожній шині. Так уже сталося одного разу, і тепер про це свідчать два тести.","changelog.d0c94d7d1062":"<strong>Компенсація затримки — поканальна.</strong> Лінія затримки — це пам'ять; одна лінія на два канали вносила б історію кожного каналу у вихід іншого, а це та сама моносума, тільки з зайвими кроками.","changelog.1ff0289da7b2":"<strong>Файл, у якому каналів більше, ніж в Oscillate, зводиться чесно.</strong> Канали 1 і 2 — це пара; усе, що далі, додається до обох боків з рівною потужністю. Шестиканальний стем щось утрачає у двоканальному продукті, а втратити це рівномірно — єдина відповідь, яка не вигадує мікс, якого ніхто не робив.","changelog.430445e78834":"⚠ <strong>Чого не збудовано — кажемо прямо.</strong>","changelog.ed4cf4e242f9":"<strong>Шість пристроїв</strong>: чотири аудіоефекти, один інструмент і один, що грає на зовнішньому обладнанні. ⚠ <strong>Кожен базовий ефект і кожен нотний пристрій збудовано.</strong> Їх було двадцять один, доки не закрили стик семплів, потік нот, випередження (look-ahead), стик зайнятості між доріжками та стик MPE; решта заблокована тим, чого пристрій справді не може бачити, і кожен каже, чим саме.","changelog.38a8ee71a0b3":"<strong><code>Frequency Carve</code></strong> порівнює смуги цієї доріжки з <strong>аудіо кожної іншої доріжки</strong>. Стик зайнятості передає те, що інші доріжки <em>грають</em> — їхні ноти, — а не те, як вони <em>звучать</em>: публікація енергії смуг для кожної доріжки — інша річ, і її треба заповнювати після рендеру кожної доріжки, а не до рендеру будь-якої з них.","changelog.9d4c0bb1c873":"<strong><code>Reverse Reverb</code></strong> будує свій реверсний хвіст з <strong>аудіо, яке ще не зазвучало</strong>, а це означає робочий потік, що рендерить наступні чотири такти аранжування цієї доріжки в кільцевий буфер. Ніщо в графі не рендерить попереду курсора відтворення; випередження несе структуру, а не звук.","changelog.a1bd3c93ef36":"<strong><code>Chain Morph</code></strong> плавно переходить між <strong>двома повними ланцюжками ефектів</strong> на рівні коефіцієнтів. Пристрій тепер може містити <em>рушій</em> іншого пристрою — <code>Quiver</code> містить вісім, а <code>Muster</code> дванадцять, — але ланцюжку довільних пристроїв ніде зберігати свої елементи керування: параметри пристрою — це плаский <code>Vec&lt;f64&gt;</code>, і параметрам вкладеного ланцюжка довелося б жити всередині нього.","changelog.a8f92d184a0a":"<strong><code>Ember</code></strong> <em>«відтворює те, що ця доріжка щойно зіграла»</em>, тож йому потрібен власний <strong>вихід доріжки після фейдера</strong>, записаний у кільцевий буфер. Стик семплів передає пристрою файл; тут потрібен відвід із графа, а це форма шляху запису, а не шляху семплів.","changelog.84b441e09a4b":"<strong><code>Salvage</code></strong> <em>«збирає барабанну установку з ваших власних тек»</em>, тож йому потрібна бібліотека продюсера: він чекає на Провідник файлів, і саме у фазі 8 він зникне з цього списку.","changelog.21f63c13e3b3":"<strong><code>Outpost</code> грає на зовнішньому обладнанні</strong> через MIDI-порт з виміряним аудіоповерненням. ⛔ <strong>В Oscillate взагалі немає вводу-виводу через MIDI-порти</strong> — <code>oscillate_audio::midi</code> існує, і ніщо його не викликає, — тож блокує тут цілий шар, а не пристрій.","changelog.55b1e9f4ac42":"<strong><code>Rein</code> не має елемента керування <code>Pressure Depth</code></strong>, хоча § 2 його перелічує. Збережена нота <code>oscillate_project</code> містить висоту, велосіті, велосіті відпускання й канал; поліфонічний тиск не записується, тож цей елемент був би ручкою, за якою нічого немає. ⚠ <code>NoteMessage::Pressure</code> існує починаючи з <code>Press</code>, тож стик у DSP є — бракує збереженої ноти.","changelog.3b6bba40e92d":"<strong><code>Strand</code> транспонує, переміщуючи біни, а не фазовим вокодером</strong>, хоча специфікація вимагає фазово-неперервних осциляторів, — тож транспонований парціал потрапляє на центр найближчого біна й розмазується, а не звучить чисто. ⚠ Він працює на 1024 точках, хоча специфікація вимагає 4096. <code>Stft</code> тепер отримує довжину кадру під час створення — <code>Sift</code> і <code>Ply</code> обидва працюють на 4096, — тож це питання повторного вимірювання, а не обмеження, і його ще не зроблено.","changelog.00463fd5e001":"<strong>Нижня октава <code>Sift</code> опускається на 8.4 дБ із заданих 12</strong>, тоді як кожна смуга від 63 Гц до 16 кГц потрапляє в межі пів децибела. При кадрі на 4096 точок октава від 22 до 45 Гц — це три біни, а власне усереднення § 2 за 64 кадри триває 1.4 секунди — замало, щоб низ справжнього шумового фону встиг повторитися. Перевірка стверджує те, що відбувається насправді, і пояснює чому.","changelog.14f6fe586263":"<strong><code>Hone</code> і <code>Stack</code> беруть тональність зі своєї панелі</strong>, хоча специфікація пропонує як джерела ще й тональність проєкту та акордову доріжку. Обом для цього потрібен проєкт, тож жодне з цих джерел не пропонується — замість того щоб пропонуватися й нічого не робити.","changelog.57af5d8acf67":"<strong><code>Approach</code> будує свій філ із того, що утримується</strong>, хоча специфікація вимагає акорд наступної секції. Сама межа секції справжня — вона береться з випередження, яке рушій уже обчислює, — тож філ з'являється в правильному місці й має правильну форму.","changelog.cabbe8817e21":"<strong>Шипіння <code>Spool</code> і свист тактового генератора <code>Shoal</code> звучать лише тоді, коли через них щось проходить.</strong> Справжній апарат шипить, грає щось чи ні; а плагін, що шипить на тихій доріжці, продюсер прибирає, щойно вперше ввімкне соло на тихому фрагменті.","changelog.9fc40d6ef00e":"<strong><code>Foil</code> і <code>Coil</code> поводяться як пластина й пружина, але не є розв'язками фізичних рівнянь.</strong> Специфікація вимагає кількох тисяч резонаторів із дисперсійного рівняння тонкої пластини та трьох баків змодельованих каскадів. Збудовано ж спільний бак ревербератора, налаштований поводитися як кожен із них: дисперсія <code>Coil</code> — справжній механізм, а розміщення мод у <code>Foil</code> не претендує на відповідність закону пластини.","changelog.fd6445143eaf":"<strong>У <code>Strata</code> немає режиму лінійно-фазового кросовера</strong>, хоча специфікація вимагає такого на 4096 відводів і 2048 семплів затримки. Тож на панелі немає й перемикача Filter Mode — перемикач з однією робочою позицією гірший, ніж жодного. Критерій амплітуди виконано на шляху LR4; критерій фази ±0.5° належить режиму, якого тут немає, і дерево LR4 виконати його не може.","changelog.8fb3c0f5fe51":"<strong>Гістерезис <code>Oxide</code> — не розв'язок моделі Jiles-Atherton</strong>, а тонстек <code>Furnace</code> — не той вузловий розрахунок схеми, якого вимагає специфікація, — тож критерій ±0.3 дБ для тонстека не заявляється. Чим кожен із них <em>є</em>, написано в заголовку його модуля, поряд із тим, що справжнє: втрати на зазорі та поведінка залежно від швидкості стрічки в <code>Oxide</code> — це фізика, а дисперсія <code>Coil</code> — справжній механізм.","changelog.65207b679973":"<strong><code>Temper</code> моделює поведінку пасивного кола, а не розв'язує його.</strong> Взаємодію, яку шукає продюсер, виміряно за власними числами специфікації; вузловий простір станів четвертого порядку під нею — не сама схема, а каскад драйву — нелінійність із передискретизацією, а не ламповий каскад із власним живленням.","changelog.9e9b24e99407":"<strong><code>Whetstone</code> має чотири смуги й не має лінійно-фазового шляху</strong>, хоча специфікація вимагає дванадцяти смуг і обох режимів фази.","changelog.1f3f9ed46a23":"<strong>Аналізатор і графік приглушення підсилення — не ЖИВІ.</strong> Крива, яку застосовує пристрій, намальована й відкалібрована на справжній сітці частот і децибелів, і набір перевірок тримає її в межах десятої частки децибела від аудіо. Те, що поруч із нею, — приглушення підсилення й кореляція, — це <strong>значення спокою</strong> пристрою, зчитані з екземпляра, створеного лише для відповіді на це питання й одразу викинутого. Рухомому графіку потрібен відвід із власного екземпляра рушія, що пише в кільцевий буфер без блокувань, а цього не збудовано. ⚠ Про це сказано в заголовку модуля <code>panel.rs</code>, а не залишено комусь гадати, чому стрілка ніколи не рухається.","changelog.076bf92bab94":"<strong>Крива — це ФОРМА, а не розподіл підсилення.</strong> Де пристрій опускає й піднімає, намальовано й перевірено; наскільки він гучний загалом — ні, бо рівень малого сигналу лампового підсилювача — це три нахили тріода й петля зворотного зв'язку, і вкласти це в намальовану криву означало б написати нелінійну модель удруге там, де ніщо не прив'язує її до першої.","changelog.a830ff8ce227":"<strong>Стереопристрої, які були заблоковані, більше не заблоковані.</strong> <code>Stance</code>, <code>Chamber</code>, <code>Foil</code>, <code>Coil</code>, <code>Shoal</code> і <code>Vault</code> чекали на двоканальний граф рендерингу, а не на чийсь вільний час. Цей граф уже є, і <code>Stance</code> збудовано; решта п'ять тепер просто ще не написані, як і інші.","changelog.e173fc848dc8":"<strong>Пресет ланцюжка не можна кинути на доріжку з файлового менеджера</strong>, а бібліотеку стійок, для якої призначено цей формат (200 власних стійок), не написано. Збудовано формат, збереження, відновлення й попередження — меню просить файл через нативний діалог, а це єдиний шлях, якому ця програма будь-коли довірятиме.","changelog.0e86c6b10e81":"<strong>Рядок-рецепт — це один пристрій.</strong> Вставити такий рядок на <em>доріжку</em>, щоб створити пристрій, — це друга половина § F-18, і її не під'єднано: попередній перегляд каже, для якого пристрою цей рядок, і нічого не пропонує, а не додає те, чого продюсер не просив.","changelog.6070503f26bb":"Додано — хостинг плагінів (фаза 6)","changelog.4cdb78939a18":"<strong>Oscillate завантажує плагіни VST 3 і CLAP, які у вас уже є</strong>, кожен у <strong>власному процесі</strong>. ⛔ Плагін, що впав, робить сірим один пристрій — його назва лишається на місці, а поруч з'являється кнопка <em>Перезавантажити</em>; транспорт рухається далі, а проєкт лишається недоторканим.","changelog.f1ceb07e2c76":"⛔ <strong>Двійковий файл програми взагалі не може завантажити плагін.</strong> Завантажувачі сховані за Cargo-функцією, яку вмикає лише двійковий файл пісочниці, — тож процес, який ви запускаєте, не лінкує <code>dlopen</code> для <code>.vst3</code> чи <code>.clap</code> і не зміг би відкрити такий файл, навіть якби його попросили. Це властивість збірки, а не правило, якого хтось дотримується.","changelog.2cc3956eefdc":"⚠ Плагін у хості працює <strong>на один блок позаду</strong> — так працює кожен хост, що виносить плагіни в окремий процес, — і цей блок <strong>додається до затримки, яку повідомляє пристрій</strong>, тож компенсується затримка, яка справді існує, а не та, яку заявив плагін.","changelog.d17de61edfa2":"<strong>Сканування плагінів, на яке ніколи не доводиться чекати.</strong> Кожен плагін відкривається в одноразовому процесі з тайм-аутом, панель <strong>за назвою</strong> каже, який файл зараз перевіряється, а ви тим часом працюєте далі. Усе, що двічі вбило сканер, відкладається — <strong>видимо</strong>, з описом того, що сталося, і кнопкою <em>Спробувати знову</em>, — а не зникає мовчки з вашої колекції.","changelog.6b08669472c3":"<strong>Де шукати, вирішуєте ви.</strong> Стандартні теки самих форматів показано саме як такі: їх можна вимкнути, але не змінити, а до <strong>п'яти власних</strong> ви додаєте через стандартне вікно вибору операційної системи. ⛔ Обмеження назване прямо, разом із причиною: сканування запускає процес для кожного знайденого плагіна. Тека на диску, який ви від'єднали, показується як відсутня і <strong>зберігається</strong>.","changelog.cc7e387cb175":"<strong>Стійка пристроїв.</strong> Одна картка на пристрій, у порядку ланцюжка: що це (<code>STOCK</code>, <code>CLAP</code> чи <code>VST3</code>), його пресет і <strong>скільки затримки він вам коштує — у семплах і в мілісекундах</strong>. Жоден хост не показує цього як слід, а продюсерові, що записує вокал, треба знати, який пристрій коштує йому 40 мс.","changelog.3d1bb7f3c970":"<strong>Обхід залишає пристрій завантаженим і зберігає компенсацію його затримки</strong>, тож вимкнення одного пристрою не зсуває всі інші доріжки відносно нього. Саме в цьому різниця між обходом і видаленням, і саме її помічають.","changelog.cccfa4d11c12":"<strong>Видалення скасовується одним натисканням, і пристрій повертається з усім, що ви налаштували.</strong> Утратити годину налаштувань через хибний клік неприйнятно.","changelog.5d696b3bddc6":"<strong>Зміна порядку перетягуванням</strong>, а ланцюжок, у який пристрій ставити не можна, каже <em>чому</em> — «нотний пристрій має стояти перед інструментом», — а не відмовляє мовчки.","changelog.00a58d0258aa":"<strong>Компенсація затримки плагінів на весь граф.</strong> Кожна точка підсумовування вирівнює те, що до неї надходить, тож доріжка з лінійно-фазовим еквалайзером і доріжка без нічого звучать разом. ⛔ Доведено <strong>нульовим тестом</strong>: той самий сигнал крізь пристрій, що повідомляє затримку, і в обхід нього гасять один одного <strong>точно</strong> до тиші — а той самий тест без компенсації доводить, що тест справді щось вимірює.","changelog.97dfa8211a1f":"<strong>Плагін, якого немає на цій машині, стає іменованим замінником</strong>, що зберігає свій стан і автоматизацію та пропонує <em>Знайти…</em> — і <em>Знайти…</em> <strong>перевіряє</strong> файл, на який ви вказуєте, перш ніж прив'язати його, а не мовчки чіпляє ваші налаштування до іншого плагіна.","changelog.32a11990f9cc":"<strong>Заморозка і зведення на місці</strong> — навмисно два різні жести: заморозка звільняє процеси плагінів доріжки й повністю оборотна; зведення замінює кліпи й прибирає пристрої. ⛔ Заморозку, яка вже не відповідає тому, що на доріжці, <strong>розморожують</strong>, а не відтворюють — почути вчорашнє аудіо гірше, ніж не почути нічого.","changelog.b470dbf6260c":"<strong>Стенд перевірки відповідності.</strong> Двійковий файл пісочниці, що постачається, проганяється через справжній канал (pipe) на кожному запуску CI — він має відповісти, відхилити ворожий блок і не впасти та назвати плагін, якого немає, — а безкоштовні плагіни, закріплені за SHA256, завантажуються й описуються там, де вони є.","changelog.4e46ad2f60cf":"Правове — ліцензія VST 3, прочитана, а не вгадана (фаза 6)","changelog.f37a3bfa9028":"⛔ <strong>VST 3 SDK від Steinberg поширюється за ліцензією MIT</strong> починаючи з 3.8, і <a href=\"https://freallyproducts.com/freally-oscillate/legal/vst3-sdk.md\"><code>docs/legal/vst3-sdk.md</code></a> фіксує текст ліцензії зсередини закріпленої ревізії — а не з новинної статті. Безкоштовно, можна використовувати в пропрієтарному продукті, без реєстрації, і єдина умова — повідомлення про ліцензію.","changelog.744c22d64e93":"⛔ <strong>Торговельну марку розглянуто окремо, і від неї відмовлено.</strong> Логотип VST за MIT необов'язковий; Oscillate його не постачає, і «VST» немає в жодній назві продукту.","changelog.0bc06d4d7aba":"⛔ <strong>Тож у цьому репозиторії немає C++.</strong> Міст, який допускав план розвитку, не збудовано: Rust-прив'язки постачаються вже згенерованими, тож SDK не вендориться, а інструментарій C++ не додається ні до збірки, ні до жодного з трьох CI-раннерів.","changelog.5a58a9104716":"Додано — редактори (фаза 5)","changelog.ed12a161eacd":"<strong>Аранжування грає.</strong> План рендерингу читає кліпи проєкту: аудіокліп стрімиться зі свого файлу на своєму місці на стрічці часу з урахуванням зсуву вмісту, обох фейдів і свого підсилення та підсумовується у свою доріжку. ⛔ Семпли надходять із диска через кільцевий буфер, який заповнює робочий потік, — і ніколи через читання файлу в аудіопотоці.","changelog.34bc614e709e":"<strong>Piano roll.</strong> Ноти малюються, переміщуються, змінюють довжину, транспонуються й видаляються тими самими жестами, що й в аранжуванні; доріжка велосіті; доріжки контролерів, по яких малюють криву, де <strong>один помах — це одне натискання скасування</strong>; і лад проєкту, що згортає рядки поза тональністю.","changelog.fe21807f67ce":"<strong>Редактор аудіокліпів.</strong> Двічі клацніть аудіокліп — і він нарешті відкривається: власна хвильова форма у власному масштабі, <strong>аж до семпла</strong>: нижче роздільності кешу піків аранжування семпли для видимого на екрані вікна читаються безпосередньо з файлу.","changelog.63b986567a23":"<strong>Огинаюча підсилення кліпу</strong>, намальована поверх хвильової форми. ⛔ Третій елемент керування, окремий від фіксованого підсилення кліпу та від автоматизації доріжки — три речі, щонайменше дві з яких більшість DAW змішують, — тож можна приглушити одне слово у вокалі, не чіпаючи нічого іншого.","changelog.b554f646f97e":"<strong>Ручки фейдів і обидва краї</strong> — це власні операції аранжування, а не другий набір, який міг би з ними розходитися.","changelog.0c638649fa35":"<strong>Реверс, нормалізація, тиша на виділенні та видалення постійної складової.</strong> ⛔ Кожна з цих операцій <strong>недеструктивна</strong>: це поля кліпу в журналі скасування, а не перезапис файлу. Вашу бібліотеку семплів редагувати не нам.","changelog.abbe7944b38f":"Курсор відтворення над хвильовою формою під час відтворення та діапазон, який можна виділити перетягуванням і заглушити.","changelog.c377ccf80966":"<strong>Сім перетворень нот</strong>, кожне — одне натискання й одне натискання скасування: інверсія, реверс, розтягування, легато, квантування, олюднення й переміщення в лад.","changelog.4baac0375406":"⛔ <strong>Квантування має силу, а не перемикач.</strong> На половинній силі нота зсувається на пів шляху до сітки — так підтягують дубль, не вбиваючи виконання, заради якого його варто було зберегти. Свінг зсуває лише слабкі долі.","changelog.b6bb8b6037c9":"⛔ <strong>Олюднення відтворюване.</strong> Випадковість має зерно, і зерно — частина операції, тож та сама сесія, відкрита на іншій машині чи відтворена з власного журналу, дає ту саму музику.","changelog.1eb70df10591":"⚠ П'ять із них мають гарячу клавішу. Інверсія й розтягування — ні: їм потрібне число, а клавіша, яка його вгадувала б, швидко робила б не те.","changelog.8c457c75ee5d":"<strong>Одне правило вирішує, який редактор відкривається</strong>, і воно в одному місці: MIDI-кліп відкриває piano roll, аудіокліп — редактор хвильової форми, а MIDI-кліп на барабанній доріжці — барабанну сітку.","changelog.b620599ca4c1":"<strong>Барабанна сітка.</strong> Кліп на доріжці, яку ви позначили як барабанну установку, відкривається як сітка рядків, а не piano roll — один рядок на звук, з назвою, з велосіті у відтінку, глушінням для кожного рядка і <strong>групами чоку</strong>, щоб закритий хет зупиняв відкритий. ⛔ Бути барабанною установкою — властивість ДОРІЖКИ, бо саме це ви маєте на увазі, кажучи <em>«моя барабанна доріжка»</em>.","changelog.8f31cc77fb13":"<strong>Доріжки автоматизації для кожного параметра.</strong> Інструменти малювання, олівця, лінії й кривої; режими читання, запису, фіксації й дотику; ручка кривої на кожній точці. ⛔ Автоматизація <strong>точна до семпла</strong>: рушію повідомляють, де на стрічці часу лежить кожен відрізок блоку, тож крива проходить правильно навіть крізь точку циклу посеред буфера.","changelog.cf94d06807a3":"<strong>Ката — крива, яку можна назвати й використати знову.</strong> Ставте форму будь-де з власною величиною, зсувом і варіацією; змініть форму — і <strong>кожен відбиток піде за нею</strong>, бо відбиток — це посилання, а не копія. ⚠ Варіація має зерно, тож завтра сесія звучатиме так само.","changelog.06c1460a5f20":"<strong>Компінг із доріжками дублів.</strong> Записуйте поверх партії скільки завгодно разів: кожен дубль має власну доріжку, і ніщо не перезаписується. Проведіть по доріжках, щоб вибрати, який дубль де грає, а стики — це <strong>справжні кросфейди</strong>: обидва дублі читаються й змішуються з рівною потужністю, тож рівень не провалюється посередині кожного з'єднання.","changelog.aee6a60fece3":"<strong>Тіньові дублі.</strong> Дубль, який ви не вибрали, ніколи не видаляється. Він згортається в примарну доріжку й лишається у файлі, доки ви явно не видалите саме цей дубль.","changelog.b74811a88c81":"<strong>Розріз.</strong> Проведіть лезом по аранжуванню — і кожен кліп, який перетне штрих, розрізається в місці перетину, а <strong>кут штриха — це кросфейд</strong>: крутий штрих дає жорсткий розріз, пологий — довге змішування, а довжина в мілісекундах показується, поки ви малюєте. ⛔ Увесь штрих скасовується одним натисканням.","changelog.ff38926dc74b":"<strong>Перемотування сесії.</strong> Друга стрічка часу — не пісні, а сесії. Тягніть її й дивіться, як аранжування відбудовується назад. ⛔ <strong>Прокручування — це лише перегляд</strong>: нічого не змінюється, доки, відпустивши, ви не виберете одну з трьох запропонованих дій — повернутися в теперішнє, скасувати досюди або <strong>відгалузити</strong>, тобто зробити форк проєкту з того моменту й зберегти обидва.","changelog.23b8f03491d7":"<strong>Панелі, які можна винести на другий дисплей.</strong> Провідник файлів, Генератори, Редактор, Мікшер і Кімната відкриваються кожна у власному вікні з власним заголовком і рядком стану. ⛔ Кожне вікно показує ту саму сесію: правка в одному з'являється в усіх, доріжка, яку ви вибрали у відокремленому мікшері, вибрана й в аранжуванні, а подвійне клацання кліпу відкриває його в тому вікні, де зараз редактор. ⚠ Закриття відокремленої панелі повертає її на місце, а не знищує, а після перезапуску панелі завжди повертаються всередину програми — до вікна, відновленого на дисплеї, який ви від'єднали, не дістатися.","changelog.8076f4c7a582":"<strong>Кліп може повторюватися, заповнюючи власну довжину.</strong> Поле було у файлі ще з фази 3, а аранжування малювало позначки повтору з фази 4; тепер в обох редакторах є кнопка, і матеріал справді повторюється.","changelog.01bd16d5c3eb":"<strong>Знайти удари в дублі.</strong> Одне натискання позначає кожен транзієнт на хвильовій формі — там, де продюсер ріже, вирівнює за сіткою чи обрізає до першої ноти.","changelog.939938b1052f":"<strong>MIDI-кліпи плануються.</strong> Ноти патерна доходять до аудіопотоку вчасно, на свою долю, транспоновані розміщенням, у якому вони стоять. ⚠ На кінці потоку поки немає нічого, що їх озвучило б, — інструменти з'являться у фазі 7, — але планувальник уже є й перевірений, тож та фаза не з'ясує раптом, що він їй потрібен.","changelog.e12f1a9c473b":"<strong>Файл, записаний з іншою частотою дискретизації, ніж у сесії, тепер грає з правильною швидкістю.</strong> Семпл 44.1 кГц у сесії 48 кГц раніше звучав приблизно на півтора півтону вище й на 9 % коротше, і ніщо не пояснювало чому. ⛔ Перетворення — це віконний sinc-інтерполятор, що фільтрує до нижчої з двох частот Найквіста перед децимацією, тож ніщо не відбивається в чутний діапазон. ⚠ Редактор усе одно показує обидва числа: передискретизований файл — не рідний, і якщо ви ганяєтеся за останньою половиною децибела мастера, ви маєте право знати, які з ваших джерел перетворюються.","changelog.f8e6e5b55387":"Виправлено — ⛔⛔ ВЕСЬ ПЕРЕЛІК ПРИСТРОЇВ БУВ НЕДОСЯЖНИЙ (фаза 7)","changelog.7645fca08728":"<strong>П'ятдесят чотири пристрої, їхні панелі, криві, рядки-рецепти — усе збудовано, усе протестовано, і жодного з них у браузері.</strong> Продюсер не міг додати на доріжку жодного власного пристрою Oscillate.","changelog.1599669c8454":"▶ Браузер плагінів показує те, що <strong>сканер</strong> знайшов на диску, а вбудований пристрій вкомпільовано у двійковий файл, а не знайдено скануванням — <code>scan::describe_one</code> відмовляє такому за назвою. Ніщо ніколи не вносило перелік пристроїв у цей індекс, тож <code>device_add</code> відповідав <em>«жоден просканований плагін не має id hilt»</em> на кожен із сімдесяти п'яти, а список не показував жодного. ⚠ <strong>Усі інші перевірки були зелені</strong>, бо кожна з них питала, чи пристрій <em>працює</em>. Жодна не питала, чи може хтось до нього дістатися.","changelog.268e4269f385":"⛔ <strong>Уже вп'яте цей проєкт постачає цілий механізм, який ніщо не викликає</strong>, і вп'яте його знайшло те саме питання: <em>що продюсер насправді натиснув би?</em> Нові перевірки в <code>plugins::browser</code> ставлять саме його — кожен пристрій із переліку є в браузері, вбудований пристрій справді можна додати на доріжку, перелік іде першим, а результати сканування не губляться, — і всі три бачили червоними саме на цьому дефекті.","changelog.54f680c853bb":"⚠ <strong>Друга половина — в інтерфейсі.</strong> Значок формату був <code>format === 'vst3' ? 'VST3' : 'CLAP'</code> — вираз із двома гілками над типом із трьома варіантами, тож кожен власний пристрій Oscillate отримав би позначку <strong>CLAP</strong>, щойно потрапив би до списку. Тепер це таблиця відповідності, тож четвертий формат дасть помилку компіляції, а не потрапить у ту гілку, яка програє.","changelog.73c54b400c47":"⚠ <strong>А під ним — другий дефект досяжності: браузер не міг їх ШУКАТИ.</strong> § 1 каже прямо — <em>«пошуковий індекс за цим стовпцем не є необов'язковим; лише він робить виразну назву придатною, а постачання назв без нього робить увесь набір гіршим за безликі»</em>, — а фільтр читав лише назву й виробника. <code>Vise</code> — це компресор, і ніщо в слові цього не підказує. Тепер пристрій передає через стик, чим він є, і пошук на це дивиться, тож якщо набрати «compressor», він знайдеться.","changelog.9df0131b255e":"⚠ <strong>Кеш ніколи не містить переліку пристроїв.</strong> Це властивість збірки, а не машини: кеш, записаний однією версією й прочитаний іншою, воскресив би пристрої, яких більше немає, і браузер пропонував би пристрій, на який реєстр відповідає <code>None</code>.","changelog.51ab50580236":"Виправлено — три перевірки, що стежили не за тим (фаза 7)","changelog.3b4ddbdf23f0":"⛔⛔ <strong>Два типи Rust записували один файл TypeScript, і перевірка прив'язок цього не бачила.</strong> <code>oscillate_dsp::device::Domain</code> і <code>oscillate_project::track::Domain</code> обидва генерували <code>src/bindings/Domain.ts</code>, тож <strong>вигравав той крейт, чиї тести запускалися останніми</strong>, — робоче дерево мерехтіло, а перевірка повідомляла про розбіжність у дереві, якого ніхто не торкався. ⚠ <strong>Перше виправлення прибрало <code>export</code> одного крейта й нібито спрацювало</strong>, бо порядок випадково був на користь проєкту; дефект повернувся, щойно тест <code>oscillate-dsp</code> запустився останнім. ts-rs записує тип щоразу, коли до нього може дістатися щось експортоване, а експортований <code>DeviceSpec</code> містить <code>domain</code>. ▶ Тип DSP тепер у TypeScript зветься <code>DeviceDomain</code>, а <strong><code>check-bindings</code> відхиляє будь-які два експортовані типи, що потрапили б в один шлях</strong>, — і її бачили червоною саме на цьому дефекті. Згодом ця перевірка повідомила б про <em>відсутність</em> розбіжності в дереві, яке справді змінилося.","changelog.88e9c9b494b0":"⛔ <strong>Пресет ланцюжка записувався через <code>fs::write</code>.</strong> <code>SECURITY.md</code> стверджує, що Oscillate пише поряд із цільовим файлом з <code>O_EXCL</code> і перейменовує поверх нього — тож символьне посилання, підкинуте туди, де мав би бути файл, відхиляється, а не прописується наскрізь, — і це мало рівно одну реалізацію, усередині збереження проєкту. Другий записувач не мав нічого з цього. ▶ Тепер цією реалізацією є <code>io::write_atomic</code>, і обидва виклики проходять через неї.","changelog.786d25e6f7a0":"⚠ <strong>Перевірка локалей вважала правильно оголошену множину відсутнім ключем.</strong> i18next розв'язує <code>t('a.b', { count })</code> через <code>a.b_one</code> і <code>a.b_other</code> і ніколи через <code>a.b</code>. Тепер перевірка це розуміє і <strong>вимагає обидві форми</strong> — ключ лише з <code>_other</code> для кількості один показується як сам ключ, а це саме та помилка, яку вона має ловити, тільки її важче помітити.","changelog.36ca4917ed10":"Виправлено — ще до того, як усе це було випущено","changelog.c7dcd3ccbb44":"⚠ Кожну з цих проблем знайшов огляд на перевірці фази 5 або робота зі зібраною програмою, і кожна спершу була зеленою в наборі тестів.","changelog.4c94ae2428be":"<strong>Аранжування замовкало, щойно ви натискали Відтворити.</strong> Прохід, що оновлює автоматизацію під час руху транспорту, п'ятдесят разів на секунду замінював план рендерингу на такий, до якого не було прив'язано жодного кліпу.","changelog.151aee7757e6":"<strong>Панелі, винесені на другий дисплей, не бачили сесії.</strong> Кожне вікно — це окремий маленький браузер із власною копією всього, і ніщо не повідомляло інші вікна, коли щось змінювалося.","changelog.58bfb47479c3":"<strong>Відокремлення панелі могло підвісити програму</strong>, а новий проєкт відкривався у вікні, повному порожніх панелей.","changelog.87b86fb5cfb4":"<strong>Файл, що має більше двох каналів, заїкався</strong> і, якщо кліп був налаштований на повтор, міг зупинити все відтворення до кінця сесії.","changelog.665dfeb7d79e":"<strong>Автоматизація, намальована пізно в сесії, грала з неправильним рівнем</strong> і стрибала сходинками замість плавного переходу — правильно на самому початку пісні, неправильно скрізь далі.","changelog.fe41509c874e":"<strong>Поставлена Ката не звучала й не малювалася</strong>, хоча її зберігали й рахували.","changelog.f0c60af56408":"<strong>Ноти після довгої ноти не грали.</strong> Утримувана нота на початку такту блокувала все за нею, доки не закінчувалася.","changelog.313751e2faad":"<strong>Більшість стиків компу були жорсткими розрізами</strong>, а не кросфейдом, який ви задали.","changelog.e084958ed56f":"<strong>Маркери транзієнтів на обрізаному кліпі</strong> опинилися б не на своєму місці.","changelog.14f8ce6b8a19":"Додано — аранжування (фаза 4)","changelog.b6922d007ca3":"<strong>Вигляд аранжування.</strong> Стрічка часу, у якій можна працювати: лінійка з тактами й долями, сітка, що стежить за масштабом, кліпи, намальовані з власного вмісту, і заголовки доріжок збоку. Масштаб логарифмічний і прив'язаний до вказівника, тож такт, на який ви дивитеся, лишається там, куди ви дивитеся.","changelog.7cae614909e8":"<strong>Кліпи, намальовані з того, чим вони є насправді.</strong> Аудіокліп малює справжню хвильову форму з кешованого файлу піків; MIDI-кліп малює свої ноти на тих висотах, які в ньому є. ⛔ Кліп, вміст якого ще не надійшов, малює лише своє тіло — хвильова форма-заглушка була б брехнею про аудіо.","changelog.b6e510719661":"<strong>Переміщення, копіювання, обрізання, розділення, фейд, глушіння, цикл, перейменування й перефарбування</strong>, і <strong>кожна дія скасовується одним натисканням</strong>, скільки б кліпів вона не зачепила. Перетягування з <code>Alt</code> копіює. Обрізайте з будь-якого краю; матеріал рухається разом із краєм, а не ковзає під ним. Лезо розрізає всі вибрані кліпи одним штрихом.","changelog.a21fb8951d11":"<strong>Курсор відтворення.</strong> Блакитна лінія — єдиний колір, зарезервований для <em>теперішнього моменту</em>, — намальована з позиції, якої аудіопотік <strong>справді досяг</strong>, шістдесят разів на секунду. ⛔ Курсор ніколи не забігає наперед рушія: курсор, що передбачає, помиляється щоразу, коли буфер запізнюється, і створює враження, ніби аудіо заїкається, хоча це не так. Клацніть лінійку, щоб перемістити курсор, тягніть, щоб прокручувати.","changelog.0132a0a5cc57":"<strong>Стрічка часу, що росте.</strong> Лінійка подовжується, коли ви ставите вміст біля її кінця, а кінцевий маркер можна відтягнути далі вручну. ⛔ Межа — <strong>дві години</strong>, вона прямо названа на панелі інструментів і повідомляється, коли ви її досягаєте, — а не перетягування, яке мовчки нічого не робить.","changelog.261a9999d38c":"<strong>Групи доріжок.</strong> Перетягніть заголовок доріжки на групу — і доріжка згорнеться в неї. ⛔ Група — це справжня шина з власним фейдером і ланцюжком, тож її глушіння заглушує все всередині, — а не зручність для малювання.","changelog.e3f13607ab34":"<strong>Маркери, дужка циклу, темп і розмір</strong> — усе на стрічці часу, а не в діалозі. Перетягування по лінійці з <code>Alt</code> малює цикл.","changelog.67e7decaa422":"<strong>Прив'язка</strong>, зокрема <em>адаптивна</em> — сітка стежить за масштабом, тож це завжди найдрібніший поділ, який ви справді бачите.","changelog.7bdf979c3936":"<strong>200 доріжок × 2 000 кліпів.</strong> Виміряно, а не заявлено: екран проєкту на 400 000 кліпів обробляється за <strong>2.4 мс</strong> при кадрі в 16 мс.","changelog.a04b02adb5a0":"Додано — мікшер стає частиною проєкту","changelog.aa23b1e78aec":"<strong>Кожен елемент керування мікшера тепер — зміна, яку можна скасувати.</strong> Рух фейдера, глушіння, соло, підготовка до запису, вибір входу й перейменування потрапляють до журналу операцій, у файл і в журнал збоїв — бо доріжка є сутністю <strong>проєкту</strong>, а мікшер — її проєкцією. ⛔ До цього жоден елемент інтерфейсу взагалі не фіксував операцій: Скасувати й Повторити були постійно сірими, а пропозиція відновлення не могла з'явитися ніколи.","changelog.5800eedeca12":"<strong>Виберіть лінійку мікшера й натисніть <code>Delete</code></strong>, щоб прибрати цю доріжку й усе на ній — одне натискання скасування поверне все. Виділення переходить на наступну доріжку. ⛔ Мастер видалити не можна.","changelog.092073003d57":"<strong>Перетягуйте лінійки, щоб змінити їхній порядок</strong>, — і це скасовується одним натисканням. Порядок належить проєкту, тож мікшер, аранжування й збережений файл завжди збігаються.","changelog.c53e20e0fcf2":"<strong>Фейдер мастера зберігається.</strong> Це був єдиний елемент мікшера, який не можна було скасувати й який не записувався у файл: сесія, зведена на −3 дБ, наступного ранку відкривалася на одиничному рівні.","changelog.f754a89b56d9":"<strong>Двічі клацніть назву лінійки, щоб перейменувати доріжку.</strong>","changelog.71651e6922dd":"Додано — транспорт","changelog.151c030e6fd3":"<strong>Запис починається з натискання й зупиняється натисканням</strong>, а повторне натискання Запису його вимикає. ⛔ <strong>Відліку немає, доки ви його не ввімкнете</strong> в Налаштування → Запис, де можна вибрати 3–5 секунд або 1–4 такти.","changelog.13a415817735":"<strong>Відтворення, стоп, запис, підготовка до запису, вибір входу, глушіння й соло відповідають миттєво.</strong> Кожне натискання — один обмін із рушієм замість двох, і кнопка підтверджує натискання, поки відповідь рушія ще в дорозі. ⛔ Те, що вона <em>малює</em>, — це досі те, що опублікував рушій: підтверджується натискання, а не щось про аудіо.","changelog.4aa204616e75":"<strong>Транспорт переїхав із мікшера</strong> й тепер стоїть над аранжуванням, тож приховування панелі мікшера більше не ховає кнопку Відтворити.","changelog.6e24c576ac39":"<strong>Подвійне клацання файлу <code>.oscillate</code> відкриває його</strong>, незалежно від того, чи Oscillate уже запущено.","changelog.174b3ab19a0f":"**Рядок стану пояснював, <em>для чого</em> панель, лише над її заголовком.** На піксель нижче він повертався до типового речення. Тепер він показує те саме з будь-якого місця всередині області.","changelog.4b361ad48ca4":"<strong>Фейдер мікшера був схожий на квадрат.</strong> Його ковпачок мав той самий колір, що й лінійка за ним, тож у нижній половині елемент не мав краю. Тепер у нього є паз, ковпачок із рифленням і шкала, а контраст <strong>виміряно</strong> на кожному тлі в обох темах, а не підібрано на око.","changelog.3fe647a29dfd":"<strong>Нерухома миша вимикала клавіатуру.</strong> Коли підказки були на цілих панелях, миша, залишена будь-де у вікні, до кінця сесії переважала клавіатуру — і рядок стану був порожнім саме для тих, кому він потрібен найбільше. Тепер відповідає той жест, що був <em>останнім</em>.","changelog.d4042456dc28":"Додано — запис так, як продюсер справді працює (2026-08-26 і 27)","changelog.27cea337b5fa":"<strong>Готовий дубль стає кліпом на доріжці, підготовленій до запису.</strong> Раніше він записував <code>.wav</code>, повідомляв, де той лежить, і залишав стрічку часу порожньою.","changelog.a05ec14dab99":"<strong>Кожен дубль — окремий кліп</strong>, і два дублі поспіль обидва потрапляють на місце — тож матеріал для компінгу є, а не один дубль тихо замінює інший на диску.","changelog.063bae2b2031":"<strong>Новий дубль замінює те, що перекриває.</strong> Зробіть панч-ін поверх наявного дубля — і старе аудіо обривається там, де починається нове. ⛔ <strong>Нічого не знищується</strong>: витіснені кліпи обрізаються й розділяються, кожен семпл лишається у своєму вихідному файлі, а одне натискання Скасувати повертає все назад.","changelog.e3c8ed4616e6":"<strong>Хвильова форма малюється, поки ви співаєте</strong>, наростаючи під курсором відтворення — з піку, виміряного самим рушієм, тож те, що ви бачите, і рівень на вашій лінійці не можуть розходитися. Тихий дубль усе одно малює свій кліп у справжню довжину.","changelog.f76d7ffb3369":"<strong>Метроном видає звук.</strong> У нього було налаштування проєкту, операція й прапорець у рушії, але жодного шляху, що їх поєднував би, — клацання обчислювалися кожен блок і нічим не читалися. Тепер є голос, перемикач на панелі транспорту й відлік, який можна почути.","changelog.f3d9577ce851":"<strong>Відлік, який видно.</strong> Секунди, що лишилися до початку запису, показано там, де їх можна вловити краєм ока, і рахує їх аудіопотік, а не таймер на сторінці.","changelog.517bce56ac3a":"<strong>Аранжування каже, де курсор відтворення</strong>, — такт і доля, час, де закінчується доріжка, і межа у дві години. Раніше воно казало лише, якої довжини проєкт.","changelog.12429092771c":"<strong>Один вибір доріжки на мікшер і аранжування</strong>, тож запис не потрапить на доріжку, на яку ви не дивилися.","changelog.7a13f6667cf5":"<strong>Подвійний Стоп повертає курсор відтворення на початок.</strong>","changelog.a74f61c309b9":"<strong>Фейди не можуть перехрещуватися.</strong> Якщо протягнути фейд-ін за фейд-аут, він упирається в межу, яку залишає інший.","changelog.5635048c1c6c":"<strong>Назви доріжок обмежені за довжиною й читабельні.</strong> Заголовки аранжування дають назві власний рядок — шість кнопок по 24 пкс у заголовку на 196 пкс залишали їй близько десяти.","changelog.ae173857b667":"Додано — керування транспортом, до якого тягнеться продюсер (2026-08-27)","changelog.6434635375f9":"<strong>Метроном, за яким можна стежити.</strong> <code>M</code> <strong>між</strong> двома крапками, заливка перескакує з однієї на іншу на кожній долі, тож пара читається як рука диригента, а не як блимання лампочки. ⚠ Крапки завбільшки з кнопку Запис, і вони перемикаються різко, а не згасають: доля — це мить, а метроном, що плавно в неї входить, здається запізнілим, навіть коли клацання точно вчасно. ⚠ Малюється з долі, якої аудіопотік справді досяг: таймер на темпі за кілька секунд розходиться з рушієм, а метроном, що не збігається з тим, що ви чуєте, гірший, ніж жодного.","changelog.a2c66155342b":"<strong>Дужка циклу, з якою можна працювати.</strong> Вона вже є, коли відкривається проєкт, — з такту 1 по такт 5, вимкнена, — тож вам ніколи не доведеться з'ясовувати, як її створити. Перетягніть з'єднувач — і весь цикл зсунеться, зберігши довжину; перетягніть будь-яку ручку — і рухається лише той кінець. ⛔ <strong>Вони ніколи не можуть перехреститися</strong>: кожна впирається за один такт <em>розміру, чинного там, де вона стоїть</em>. Клацання з <code>Ctrl</code>/<code>Cmd</code> вмикає й вимикає цикл, і кожна з цих дій скасовується одним натисканням.","changelog.8f16d426462b":"<strong>Клацніть будь-де в аранжуванні, щоб поставити туди курсор відтворення</strong>, а не лише на 24-піксельній лінійці. ⚠ Перетягування — це й далі рамкове виділення: їх розрізняють за тим, чи рухався вказівник.","changelog.ae32226c7f3d":"<strong>Розмір можна редагувати</strong> — поряд із темпом, де йому й місце. Він був у моделі ще з фази 3, <code>bars.ts</code> його читав, лінійка його малювала, але ніщо в інтерфейсі не могло його змінити.","changelog.22ad9b3d722f":"Виправлено — стики, які знайшли три огляди (2026-08-27)","changelog.fa4907a02da4":"<strong>Пізніші правки жесту перевірялися на проєкті в тому стані, у якому він був до ранніших.</strong> А коли це виправили, обрізання лівого краю кліпу, що закінчувався на межі у дві години, відхилялося: проміжний стан виходив за кінець, хоча кінцевий — ні.","changelog.1bba613b10b9":"<strong>Сітка прив'язки ігнорувала кожну зміну розміру після першої.</strong> Сесія, що переходить на 6/8 у такті 33, прив'язувала решту аранжування до тактів 4/4 — і навіть правильну сітку відлічували від нульового тіку, а не від місця зміни розміру, тож кліпи падали між видимими тактовими рисками.","changelog.3a0c33b3e6b3":"<strong>Швидке прокручування могло залишити на стрічці часу такти, від яких ви вже відкрутили</strong>, і стверджувати, що завантажено ті, яких так і не завантажили.","changelog.8597dcaebff6":"<strong>Смуги рядків інвертувалися під час прокручування</strong>, а саме для того, щоб стежити за рядками, вони й існують.","changelog.3bb4cc884f29":"<strong>Скасоване перетягування висоти доріжки залишало заголовок неправильного розміру</strong> до кінця сесії.","changelog.0673ae95a689":"<strong>Журнал відновлення міг мовчки відкинути все після надто великого запису</strong> й повідомити про файл як про звичайне обрізання через збій.","changelog.c2949c578495":"<strong><code>.wav</code> з порожнім фрагментом <code>LIST</code>, <code>fact</code> або <code>PAD </code> перед <code>fmt </code> відхилявся як обрізаний</strong> — без хвильової форми, а кліп грав тишу.","changelog.6e0584e53a87":"<strong>Відповідь неправильної форми валила вікно</strong>, замість того щоб бути відхиленою.","changelog.3b546441830b":"<strong>Ціль для кидання файлів в аранжування</strong>, яка ніколи не могла працювати. Webview ніколи не бачить перетягування файлу — кидання обробляє Tauri, — а навіть якби бачив, шлях, наданий сторінкою, — саме те, чого цей продукт відмовляється приймати. ⚠ Імпорту аудіо це не стосується: він доступний через вікно вибору файлів. Справжнє кидання треба обробляти в Rust, і це рішення дизайну, а не виправлення помилки.","changelog.ae0e37ba6be2":"Виправлено — що знайшла перевірка фази, працюючи зі зібраною програмою","changelog.bbbc9059eb60":"⚠ Кожна з цих проблем проходила повний набір тестів і ламалася в руках продюсера. Їх знайшли, працюючи з <strong>релізним двійковим файлом</strong>, а не з попередньою збіркою, — саме для цього й існує ручний прохід перевірки.","changelog.84a878dc90df":"⛔ <strong>Правку в мікшері не бачили ні Скасування, ні позначка незбережених змін.</strong> Додавання доріжки ставило лінійку в стійку й більше нікуди не доходило — <code>File ▸ Undo</code> лишався сірим, позначка змін ніколи не засвічувалася, а заголовки доріжок в аранжуванні показували доріжки, що були раніше. <strong>Продюсерові, який провів сесію в мікшері й вийшов, ніхто не казав, що в нього є незбережена робота.</strong> Тепер кожна команда, що змінює проєкт, відповідає повним станом стику.","changelog.b91883d78df0":"⛔ <strong>Скасування кидало виняток і нічого не робило.</strong> <code>project_undo</code>, <code>project_open</code>, <code>project_new</code> і <code>project_save</code> відповідали голим підсумком, тоді як інтерфейс чекав повного стану стику, тож скасування мовчки ламалося в коді, що мав його застосувати. До того ж відкриття проєкту ніколи не перечитувало мікшер із доріжок нового проєкту.","changelog.ebd08c2bb97b":"⛔ <strong><code>File ▸ Undo</code> показував <code>Undo {{gesture}}</code>.</strong> Коли скасовувати нічого, меню малювало власний шаблон. Тепер є окрема мітка всіма вісімнадцятьма мовами — порожньої підстановки недостатньо: вона лишає зайву двокрапку в російській і відірвану частку в японській.","changelog.b0798ca992b8":"⛔ <strong>Кожен фейдер у мікшері малював шкалу без позначки одиничного рівня.</strong> Одиничний рівень порівнювався з фіксованою позицією шкали через рівність чисел із рухомою комою, а мікшер обчислює власну позицію з ходу фейдера, тож збігу не було ніколи. Тепер позначка малюється <strong>точно на</strong> одиничному рівні, а не на найближчій поділці, і це виправляє також фейдери, у яких одиничний рівень далеко від будь-якої поділки.","changelog.bca525a074d9":"<strong>Відлік доходив до рушія, лише якщо ви відкривали Налаштування.</strong> Його передавала панель, що малює вибір, тож після кожного запуску рушій відлічував нуль, доки ви не відвідували той екран.","changelog.5ce1635ae9eb":"<strong>Аранжування перемальовувалося шістдесят разів на секунду, навіть коли стояло</strong>, перебудовуючи кожен рядок доріжки заради позиції курсора, яку читали лише дві кнопки.","changelog.f3c36b3ce60a":"Виправлено — модель і те, що міг зробити ворожий файл","changelog.793366e43f5d":"⛔ <strong>Шлях до <code>.wav</code> у файлі проєкту відкривався без перевірки.</strong> <code>.oscillate</code> надходить завантаженням або від співавтора, а відредагований вручну файл міг вказати шлях на <strong>іншій машині</strong> — і Windows автоматично проходила б там автентифікацію, зливаючи облікові дані продюсера лише через те, що той відкрив файл. Тепер Oscillate ще до відкриття відхиляє будь-який шлях, що не є звичайним локальним файлом.","changelog.772fa7975871":"⛔ <strong>Команда імпорту приймала шлях до файлу з інтерфейсу.</strong> Тепер його беруть лише з нативного вікна вибору, як і кожен інший шлях у продукті, — а тест читає вихідний код, щоб так і лишалося.","changelog.62b162f4459b":"⛔ <strong>Видалення доріжки могло назавжди знищити її кліпи.</strong> Видалення, зібране поза звичайним жестом, не записувало способу повернути видалені кліпи, тож скасування відновлювало порожню доріжку. Тепер таке відхиляється.","changelog.ac5b9eebbbf8":"<strong>Видалення групи залишало доріжки всередині неї з посиланням на неї.</strong> І мікшер, і аранжування малювали групу, якої вже не було. Тепер її дочірні доріжки піднімаються до групи рівнем вище.","changelog.4ced12bd8446":"<strong>Запис, обірваний збоєм, імпортувався без ідентичності вмісту</strong> і з довжиною, взятою із заголовка, а не з того, що справді було у файлі. Тепер він відхиляється, а речення пояснює, що сталося.","changelog.82c6f3242320":"<strong>Проєкт міг сам вимкнути свою межу у дві години</strong> одним відредагованим полем.","changelog.6a9f69980c92":"<strong>Читач піків визначав розмір буфера за числом із файлу.</strong>","changelog.1e1652d0b1fc":"Додано — проєкт (фаза 3)","changelog.000b52ad8bce":"<strong>Один екземпляр Oscillate, а не кілька.</strong> Запуск Oscillate, коли він уже працює, виводить наявне вікно на передній план замість другого процесу. ⛔ Два Oscillate билися б за аудіопристрій, за <code>preferences.json</code> і за теку дублів — і перше з цього проявляється банером, який читається як несправність обладнання.","changelog.8289318a37f6":"<strong>Журнал операцій.</strong> Кожна зміна, яку робить продюсер, — це одна <code>Operation</code>, а скасування, повтор, співпраця, Перемотування сесії й реєстр авторства — чотири прочитання цього одного журналу. Складений жест — це <strong>одна</strong> операція: перетягування сорока нот скасовується одним натисканням, а не сорока.","changelog.4eb96d6377e1":"<strong>Необмежене скасування й повтор — для кожного автора окремо.</strong> <code>Ctrl</code>/<code>⌘</code>+<code>Z</code> скасовує <em>вашу</em> останню зміну й ніколи чужу — з першого коміту, ще до того, як з'явився хтось, із ким можна ділити сесію. 10 000 операцій займають <strong>5.8 МБ</strong>, а найповільніше окреме скасування триває <strong>7 мкс</strong> — при бюджетах 200 МБ і 16 мс.","changelog.bdc94205dc9c":"<strong>Патерни.</strong> Кліп <em>посилається</em> на свій вміст і ніколи ним не володіє — як для MIDI, так і для аудіо. Поставте чотиритактову барабанну партію тридцять два рази — і буде тридцять два кліпи й <strong>один</strong> патерн: змініть його один раз, і зміниться кожне розміщення. <em>Зробити унікальним</em> — явна дія, що робить його форк.","changelog.388422931fa2":"<strong>Файл <code>.oscillate</code>.</strong> Версійований контейнер: JSON-маніфест плюс двійкові фрагменти. ⛔ Кожна довжина перевіряється на межі, перш ніж дійде до алокатора, тож пошкоджений або ворожий файл <strong>завершується помилкою з причиною</strong> й ніколи не обриває процес. Тестується кожен префікс коректного файлу й кожна його однобайтова мутація.","changelog.d522a5cbcc8e":"<strong>Зберегти, Зберегти як, Відкрити та історія сесій, з якою можна щось робити.</strong> Недавні проєкти можна відкрити, <strong>показати у файловому менеджері</strong>, забути по одному або очистити — список є записом того, над чим ви працювали, тож і очищати його вам. Проєкт, файл якого перемістили, стає сірим і <strong>зберігає свій рядок</strong>, тож коли диск знову під'єднано, проєкт повертається.","changelog.260ee88cb364":"<strong>Сесія за замовчуванням.</strong> Збережіть аранжування, з якого завжди починаєте, — доріжки, назви, кольори, маршрутизацію, ланцюжки пристроїв, темп і розмір, — і <code>New Project</code> відкриє його. ⛔ Ніколи ваші кліпи й ніколи ваше аудіо. <em>Скинути до заводських налаштувань</em> повертає власну сесію Oscillate.","changelog.b5e407459915":"<strong>Відновлення після збою до самого моменту збою.</strong> Кожна операція записується в супровідний журнал у мить, коли відбувається, тож під час збою нічого робити не треба — робота вже на диску. ⛔ Відновлення <strong>пропонується</strong>, а не застосовується: ваш збережений проєкт не перезаписується, доки ви не скажете. Скільки роботи може коштувати вимкнення живлення, прямо сказано в меню «Файл», а не лише мається на увазі.","changelog.b31ad4e4a0db":"<strong>Файл із новішої версії Oscillate відмовляється відкриватися, називає обидві версії</strong> й пропонує режим лише для читання. ⛔ А поле, якого ця збірка не розуміє, переноситься крізь збереження, а не мовчки відкидається.","changelog.4f94248b72da":"<strong><code>Ctrl</code>/<code>⌘</code> + <code>N</code>, <code>O</code>, <code>S</code>, <code>Shift+S</code>, <code>Z</code> і <code>Shift+Z</code></strong> — усі можна перепризначити, і всі ігноруються, поки ви друкуєте в полі.","changelog.ee8c3606ce09":"Збереження ніколи не обрізає файл, який замінює. Новий проєкт записується поряд зі старим, синхронізується на диск і лише тоді перейменовується поверх нього — тож немає жодної миті, коли за цим шляхом лежить пів проєкту.","changelog.6ceed1e0814b":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-08-25\">2026-08-25</time></span>","changelog.f67bfa325008":"<strong>Оболонка і звук.</strong> Фази 1 і 2 разом — перший щабель, на якому Oscillate має власний вигляд <strong>і</strong> відкриває пристрій, тримає час, мікшує, вимірює рівні й записує. ⚠ Зібрано й перевірено, <strong>не опубліковано</strong> (правило статуту 5).","changelog.6b02e0d363a4":"Додано","changelog.5796e58a5bdd":"<strong>Вікно без рамки з власним заголовком</strong> і − □/❐ ✕. Область перетягування не охоплює кнопок, подвійне клацання розгортає вікно, а aero-snap і далі працює, бо перетягування передається власному циклу переміщення операційної системи. Позиція й розмір вікна запам'ятовуються для кожної машини — і <strong>ніколи не відновлюються на дисплеї, який більше не під'єднано</strong>.","changelog.f9b314697ae1":"<strong>Система панелей</strong>: Провідник файлів, Генератори, Редактор, Мікшер і Кімната — кожну показує й ховає кнопка-зображення, яка <em>і є</em> станом області, на <code>Ctrl/⌘+1…5</code>.","changelog.a9109db1e242":"<strong>Дванадцять гліфів панелей</strong>, намальованих власноруч на сітці 24 × 24 у <code>currentColor</code>, і перевірка, яка рендерить кожен із них у 16 пкс і падає, якщо будь-які два мають однаковий силует.","changelog.69e7b7c3ab85":"<strong>Каркас розмітки</strong> — сітка з дизайну, роздільники, якими можна керувати з клавіатури, і області, що згортаються в задокументованому порядку, коли вікно звужується; кнопка області, яка не вміщається, вимкнена й пояснює чому.","changelog.147bb006862f":"<strong>Пропорційна зміна розміру</strong>: один коефіцієнт масштабу, обчислений в одному місці, причому шрифт масштабується повільніше за геометрію; перевірено на восьми ширинах від 1280 до 3840 на мертві поля й замалі цілі для натискання.","changelog.ac2529873765":"<strong>Три стани теми — системна, світла й темна, — що запам'ятовуються для кожної машини</strong>, а зміна теми відбувається тим самим розрізом.","changelog.015a610ef72a":"<strong>Розріз</strong>: одна діагональна шторка вздовж однієї осі, яку використовують кожне модальне вікно, кожна панель і зміна теми. За <code>prefers-reduced-motion</code> це інший шлях, а не коротший, і шар шторки взагалі не монтується.","changelog.d1b1a8561adc":"<strong>Модальне вікно Налаштувань</strong> з усіма десятьма розділами, <code>Esc</code>, пасткою фокусу, застосуванням наживо й збереженням для кожної машини. Розділи, за якими ще немає підсистеми, так і кажуть, а не малюють елементи керування, що нічого не змінюють.","changelog.9b7d9224e453":"<strong>Таблиця гарячих клавіш, які можна перепризначити</strong>, — одна таблиця, яку читають обробники й яка рендериться в Налаштуваннях, а конфлікти відхиляються з назвою.","changelog.01315f761e95":"<strong>Шість базових елементів керування</strong> — Knob, Fader, Meter, Toggle, Selector і NumberField, — що мають один спільний жест, із балістикою індикаторів, яка є чистою функцією й протестована кадр за кадром.","changelog.297b0ff97ebe":"<strong>Заставка</strong>: Oscillate стрибає, лезо б'є, і розріз змітає її, відкриваючи аранжування. Будь-яка клавіша чи клацання її пропускає, вона ніколи не подовжує холодний старт, а 2 МБ графіки зменшуються під час збирання.","changelog.1aac2bdb22c4":"<strong>Угода під час першого запуску</strong>, що рендериться з самого <code>EULA.md</code> і фіксується разом із хешем цього тексту, тож після істотної зміни угода запитає знову. До прийняття нічого не працює — зокрема й жодна гаряча клавіша.","changelog.4413c389097a":"<strong>Звіти про помилки й збої.</strong> Паніка Rust записує звіт, перш ніж процес завершиться; збій рендеру записує звіт і <strong>не зупиняє відтворення</strong>. Звіти локальні, показуються повністю, обмежені двадцятьма найновішими, а кожен абсолютний шлях і адреса з них вирізаються. ⛔ Ніщо ніколи не надсилається автоматично, а <em>відкрити заповнений звіт</em> передає URL вашому браузеру, а не робить запит сама.","changelog.ed49327ae78a":"Перевірка <code>bindings</code> — це справжня перевірка розбіжностей, а не тест, що перезаписує те, що перевіряє: вона робить знімок, регенерує й порівнює, і падає, коли експорт не дає взагалі нічого.","changelog.38d32c539046":"Перевірки Playwright вибирають тести за <strong>проєктом</strong>, а не за назвами файлів специфікацій — нова специфікація раніше запускалася локально й ніколи в CI.","changelog.3f0c0f6da683":"Анімація маски розрізу йшла в неправильний бік, тож кожне модальне вікно, кожна область і заставка згасали до <strong>повної невидимості</strong> приблизно за 260 мс після появи, лишаючись клікабельними. Знайдено на око; тепер це закріплено перевіркою ключових кадрів і тестами, що порівнюють справжні пікселі.","changelog.666c4c2ea362":"Налаштування, змінене менш ніж за 250 мс до виходу, губилося, бо запис відкладається, а на виході його ніщо не скидало на диск.","changelog.034ca2037612":"Змінено — заставка й значок, за рішенням власника (2026-08-25)","changelog.7f6a52a11899":"⛔ <strong>Заставка тепер — окреме прозоре вікно.</strong> Вона була накладкою всередині програми, а це означало дві речі, яких їй ніколи не уникнути: вона не могла бути більшою за вікно програми — 960×600 логічних пікселів на дисплеї 2560×1600 з масштабом 150 % — і за вирізаною фігурою завжди було <em>щось</em> намальоване. Тепер це <code>splash.html</code>, окрема сторінка в окремому повноекранному вікні <strong>без жодного кольору тла</strong>, яке Rust створює й розмірює за монітором, на якому воно відкривається. Те, що оточує Oscillate, — ваш робочий стіл.","changelog.eccd1dd3e489":"Пакет заставки — це <strong>0.7 кБ JavaScript і 1 кБ CSS</strong>, повністю окремо від 189 кБ програми. Це перше, що декодується під час холодного старту.","changelog.405302c0a35a":"<strong>Стрибок — це стрибок.</strong> Фігура з'являється з-під нижнього краю, злітає до вершини й падає назад — безперервно наближаючись до вас в обох половинах, масштаб 0.13 → 2.0, і закінчує далеко за краями екрана. Ключові кадри — це вибірки з двох плавних кривих, а не пози, розставлені вручну.","changelog.c8138b18399e":"⚠ <strong>Вікно програми лишається прихованим, доки заставка не передасть керування</strong>, а Rust запускає сторожовий таймер, тож сторінка, яка так і не відповіла, не може залишити запущений процес зовсім без вікна.","changelog.c72349087278":"⛔ <strong>Значок програми знову намальований, а не сфотографований.</strong> Один день значком у збірці була фігура із заставки, вирізана з власної маски; у 16 пкс фотографія на весь зріст — це каша. Тепер це <strong>катана крізь розсічене кільце</strong>, згенерована з токенів дизайну арифметикою: кільце — це <em>четверо продюсерів, одна сесія</em>, меч — Oscillate, на власній осі продукту −22°.","changelog.480ac8d3405f":"Змінено — тривалість і поведінка заставки","changelog.2ef806b69680":"⛔ <strong>Вона обов'язкова, і її не можна пропустити, як у FL Studio.</strong> Ні кнопки пропуску, ні реакції на будь-яку клавішу. Вона відтворює весь стрибок, удар і розріз під час кожного запуску, доки ви не вимкнете її в <strong>Налаштування → Оформлення</strong>, а цей перемикач враховується лише після того, як заставка хоча б раз пройшла повністю на цій машині, — тож файл налаштувань, скопійований з іншої машини, не може пропустити заставку, якої ця ще ніколи не показувала.","changelog.ddddf34a2c57":"⚠ <strong>Це навмисно скасовує два правила § F-21</strong>: <em>«можна пропустити будь-коли»</em> і <em>«ніколи не подовжує холодний старт»</em>. Тепер вона коштує близько двох секунд. Залишилася <strong>верхня межа</strong> — обов'язкова не означає безмежна, і тест досі стверджує, що вона закінчується.","changelog.40d388966a63":"⚠ <strong>Стара поведінка була гіршою, ніж здавалося.</strong> Послідовність переходила до удару, щойно програма була готова, а програма готова майже одразу — тож на будь-якій реальній машині стрибок відтворювався приблизно на п'яту частину, а меч так і не опускався.","changelog.b3f010a5d099":"<strong>Фігура значно більша й справді стрибає на вас</strong> — абсолютно відцентрована, а не флекс-нащадок, що відбирає стовпчик у логотипа, — вона зростає в 2.7× за стрибок і закінчує майже на всю висоту.","changelog.5e796ac2c528":"<strong>Заставка темна в обох темах.</strong> На світлій машині це була маленька фігура на білому полі; власний рядок продукту — <em>темна студія з одним лезом світла</em>. Це єдина поверхня, що не стежить за темою, і <code>splash.contrast.test.ts</code> натомість перевіряє її власні кольори.","changelog.be115dfca1d9":"<strong>Графіка генерується в повній роздільності</strong> (1531 пкс заввишки при 2×), бо тепер вона показується настільки великою, що старий ресурс на 1280 пкс розмивався б.","changelog.4806942da19f":"⛔ <strong>Заставка більше не з'являється шторкою, лише зникає нею.</strong> Це перша поверхня на екрані, за якою немає нічого, з чого її можна відкрити, а маскування на вході означало, що каркас програми просвічував <em>крізь</em> неї впродовж розрізу — спалах того самого інтерфейсу, який вона має представити, під час кожного запуску.","changelog.917a1f65a62b":"<strong>Знайдено власними оглядами перевірки фази й виправлено тут:</strong>","changelog.f3f677980569":"⛔ <strong>Звіт про збій залишав дані машини неочищеними.</strong> Частина на Rust очищала їх по дорозі на диск, але діалог сам знову склеював сиру помилку — тож копія, яку користувач міг покласти в буфер обміну, завантажити чи вставити в <strong>публічний issue на GitHub</strong>, була саме тією, яку ніхто не очищав, під банером, що обіцяв: шляхів до файлів тут немає. Тепер звіт один: складений і очищений один раз, у Rust, і саме цей текст показується й лише його можна надіслати. Якщо немає бекенду для очищення, кнопки надсилання не пропонуються взагалі.","changelog.7ddebee8ab10":"⛔ <strong>Вихід із розгорнутого вікна знищував його справжній розмір.</strong> Збережений прямокутник був розгорнутим, тож відновлення з розгорнутого стану під час наступного запуску повертало той самий розмір, а налаштований розмір пропадав назавжди.","changelog.b22c92d59e1d":"⛔ <strong>Два процеси, що записують <code>preferences.json</code>, могли стерти половину одне одного.</strong> Під час закриття скидання інтерфейсу й збереження геометрії в Rust спрацьовують разом; той, хто записував другим, вигравав увесь файл, і губилася або позиція вікна, або остання чверть секунди теми, розмітки й прийняття угоди. Тепер обидва записи зливаються, тож порядок більше не важить.","changelog.9355bc11339a":"⛔ <strong>Мінімальний розмір вікна було оголошено в логічних пікселях</strong>, тоді як усі інші використання тих самих констант — фізичні. При масштабі 150 % перше вікно відкривалося на весь екран і звисало за край, а не стояло по центру, а точки згортання нижче 1280 ніколи не могли спрацювати.","changelog.a0e64e3152ba":"⛔ <strong>Адреса учасника в кінці речення чи з портом не вирізалася</strong> — токен захоплював крапку, тож розпадався на п'ять частин замість чотирьох, і перевірка, ламаючись, пропускала адресу. IPv6 не вирізалася взагалі ніколи.","changelog.73fe3e54392a":"⛔ <strong>Два звіти про збої в одну й ту саму секунду перезаписували один одного</strong> — у функції, правило якої: ніколи не просити користувача відтворити збій, перш ніж зібрати файл.","changelog.fd305290022c":"⛔ <strong>Блокування перекомпонування було прапорцем, а не лічильником</strong>, тож перший відпущений вказівник знімав утримання, яким ще володіло інше перетягування, — вікно перекомпоновувалося під рукою, що досі тягнула, а це саме та помилка, яку забороняє § F-35.","changelog.f97e1805f598":"Гаряча клавіша, перепризначена на <code>+</code>, ніколи не могла спрацювати: роздільник комбінації і її клавіша — той самий символ, тож клавіша розбиралася як порожня. Вона зберігалася, показувалася й нічого не робила.","changelog.1818dd50dc97":"Картка відхиленої угоди не мала пастки фокусу, тож користувач клавіатури міг вийти клавішею Tab крізь непрозоре затінення й натиснути кнопки заголовка.","changelog.affbfc927387":"Правило збереженої локалі в <code>initialLocale</code> було недосяжним кодом; справжнє рішення обходило його перевірку й передавало до i18next мову, якої Oscillate не постачає. До того ж вибір мови в нижньому колонтитулі ніколи не зберігався.","changelog.9e060fae8ad3":"Фокус повертався лише тоді, коли модальне вікно лишалося змонтованим, а два з трьох натомість демонтуються.","changelog.c3a66b9ba90c":"⛔ <strong>Розгорнуте вікно ніколи не відкривалося знову розгорнутим.</strong> Windows дає розгорнутому вікну невидиму рамку зміни розміру, що звисає на ~11 пкс за кожен край, тож збережене <code>y</code> дорівнює <code>-11</code> — а захист відновлення вимагав, щоб на екрані була <em>вся</em> 64-піксельна смуга заголовка. Тому кожне колись збережене розгорнуте вікно визнавалося непридатним і мовчки замінялося типовим вікном по центру. Знайдено, зібравши релізний двійковий файл і запустивши його.","changelog.303430e5157f":"<strong>Перевірки, що не могли впасти, тепер справжні:</strong>","changelog.b0bcf47ad11e":"Перевірка розбіжностей <code>bindings</code> ніколи не очищала теку перед регенерацією, а ts-rs лише записує, — тож її гілки «застаріла прив'язка» й «не згенеровано взагалі нічого» обидві були недосяжні. Перевірено, підкинувши осиротілу прив'язку й побачивши, як перевірка стає червоною.","changelog.80822e6bc052":"Чотири e2e-твердження перевірялися на стані, що був істинним ще до натискання клавіші, яке вони тестували, а <code>dismissSplash</code> шукав заставку, яка ще не змонтувалася, — і накладка ковтала наступне клацання в кожному тесті, що відкривав програму.","changelog.977117c0a2a3":"Додано — аудіорушій (фаза 2)","changelog.e7b90e4f7a6c":"<strong>Аудіорушій реального часу</strong>, що відкриває пристрій і рендерить блоки <strong>без алокацій, без блокувань і без системних викликів у колбеку</strong>, — і це забезпечує лічильний глобальний алокатор, увімкнений довкола колбека, а не перегляд коду.","changelog.e61632d46641":"<strong>Граф рендерингу без блокувань</strong>, що передається аудіопотоку атомарною заміною вказівника, а відпрацьований план звільняється в потоці інтерфейсу. Аудіопотік ніколи нічого не звільняє й ніколи не чекає.","changelog.ad0918e4e397":"<strong>Транспорт</strong>: відтворення, стоп, запис, переміщення курсора, цикл, карта темпу, карта розміру, метроном і відлік — усе в субтіках із фіксованою комою (960 PPQ × 65 536), тож годинна сесія не дрейфує.","changelog.c3381e2b7634":"<strong>Мікшер</strong>: канали, фейдер, панорама з постійною потужністю (−3.01 дБ у центрі), глушіння, соло, посили, групи й мастер, упорядковані топологічним сортуванням за зв'язками і з батьками, і з посилами.","changelog.3c007269b511":"<strong>Вимірювання в спільний банк</strong>, що читається через власну URI-схему, а не JSON IPC, — фіксоване двійкове компонування, тож шістдесят читань на секунду не потребують розбору.","changelog.b0b53fddf264":"<strong>Запис аудіо</strong>: підготовка до запису, вибір входу, моніторинг (<strong>типово вимкнений</strong>), відлік і панч — окремий потік запису пише прямо на диск через кільцевий буфер без блокувань. Заголовок WAV записується <strong>до</strong> першого семпла, а дубль, заголовок якого так і не виправили, можна відновити з розміру файлу.","changelog.57a6593bdb89":"<strong>MIDI-вхід</strong> із пакуванням і розпакуванням без утрат через чергу без блокувань.","changelog.ae5e6e02af07":"<strong>Обробка гарячого під'єднання пристроїв і зміни частоти дискретизації</strong> — від'єднайте інтерфейс, і транспорт зупиниться, лінійка назве пристрій, а проєкт лишиться недоторканим; <em>Відновити</em> відкриває його знову.","changelog.e435ef5b747d":"Виправлено — що знайшов огляд перевірки фази 2","changelog.54faffc42107":"⛔ <strong>Три з цих частин були повністю збудовані й повністю покриті модульними тестами — і зовсім не працювали в програмі, що постачалася.</strong> Вони перелічені саме в цьому дусі: тести покривали частини й ніколи — стик між ними.","changelog.5bba3d0973a6":"⛔ <strong>Запис ніколи не працював поза тестами.</strong> Робочий колбек не передавав відводу для запису — кожна частина шляху існувала, і ніщо її не викликало.","changelog.bf141689a01d":"⛔ <strong>Кожен індикатор рівня доріжки був мертвий.</strong> Слот індикатора лінійки призначався лише мастеру, а банк мав розмір на два канали незалежно від кількості доріжок.","changelog.d4e9a63a6aad":"⛔ <strong>У запакованій збірці жоден індикатор не міг рухатися.</strong> Знімок віддається з іншого походження (origin), ніж сторінка, і не мав <code>Access-Control-Allow-Origin</code>. CSP уже дозволяла схему — <strong>CSP — це не CORS</strong>, а сервер розробки цього ніколи не показує.","changelog.e27afc804d21":"⛔ <strong>Будь-який цикл, що починався не з такту 1, стрибав на початок проєкту.</strong> Перехід віднімав значення в <em>тіках</em> від позиції в <em>субтіках</em>. ⚠ Кожен наявний тест циклу використовував такт 1, де зламана арифметика випадково правильна.","changelog.afe43c0d4e2a":"<strong>Перехід циклу посеред блоку повторно відтворював початок входу</strong>, бо кожен відрізок просував зріз виходу, але не зріз входу, — заїкання на кожному повторі під час моніторингу.","changelog.ea0d9ab4ca81":"<strong>Переміщення курсора, що надходило разом із записом, з'їдало відлік.</strong> Одна звичайна кнопка («записати з початку виділення») надсилає обидва в межах одного проміжку між блоками.","changelog.212a1425d0de":"⛔ **Натискання <em>Стоп</em> могло заморозити вікно.** Дубль закривався в потоці інтерфейсу, чекаючи на потік запису, який міг бути заблокований на диску, що завис, — а Oscillate малює власний заголовок, тож не було системного обрамлення вікна, на яке можна було б покластися.","changelog.5601b4005190":"<strong>Пристрій, що відмовив на першому блоці, перевідкривався в щільному циклі</strong>, без паузи й без обмеження; а помилку, що виникала під час відкриття потоку, могло бути проковтнуто, і програма мовчала, повідомляючи про справний пристрій.","changelog.6ce4996c40aa":"<strong>Правки мікшера, зроблені під час відкриття пристрою, губилися</strong> на шляху до аудіо, тож фейдер, зсунутий під час перепідключення, показував одне значення, а звучав інакше.","changelog.8008bbcdc222":"<strong>Метроном міг переповнитися й панікувати всередині аудіоколбека</strong> під час переміщення курсора біля кінця діапазону.","changelog.12e2665533c9":"Виправлено — що знайшов огляд виправлень","changelog.108a22259133":"⛔ <strong>Другий огляд, обмежений комітом із виправленнями, а не самими помилками.</strong> Він знайшов ще шість дефектів, <strong>два серйозні, і один із них створило саме виправлення.</strong> Записано тут, бо це і є аргумент на користь самого існування цього проходу.","changelog.198888ba7d98":"⛔ <strong>Нескінченний цикл в аудіоколбеку.</strong> Коли <code>span_end</code> і <code>first</code> метронома зробили насичувальними, забули про власний крок циклу. У релізній збірці він переповнювався й крутився ~10¹¹ ітерацій — <strong>гірше за паніку, яку він замінив.</strong>","changelog.3805b261f86a":"⛔ **Одне натискання <em>Відновити</em> коштувало двох і могло назавжди припаркувати потік пристрою.** Два цикли споживали той самий прапорець перевідкриття, тож натискання впродовж відкриття пристрою, яке триває від пів секунди до двох, руйнувало щойно відкритий пристрій.","changelog.7e57ef4b8c08":"<strong>Дубль ніколи не міг завершитися</strong>, якщо транспорт усе ще рухався: потік запису читав свій прапорець зупинки лише на порожньому зливанні, а аудіопотік знову й знову наповнював кільцевий буфер. Тепер хвіст зливання обмежено.","changelog.2c2d115a8222":"<strong>Лінійці за межами банку індикаторів видавався слот, якого не існує</strong>, — дефект мертвого індикатора, що повертався на більшому номері каналу. Тепер вона не отримує індикатора взагалі — і це чесно, — а не індикатор, застиглий на −∞.","changelog.1b65e543046f":"<strong>Знімок індикаторів передавав усі 1 024 слоти шістдесят разів на секунду</strong> — 16 КБ на кадр для сесії з двома лінійками. Тепер він передає лише канали, через які справді пройшов семпл.","changelog.cab3bd8a9f1a":"<strong>Кількість утрачених семплів читалася до зливання</strong>, тож пропускала саме ті втрати, які спричиняє повільний диск.","changelog.fb88cf8c59c9":"⚠ <strong>Два тести не могли впасти</strong>, а це гірше, ніж не мати їх зовсім, — обидва написані на цій перевірці, обидва тепер виправлені: тест метронома, вхід якого ніколи не потрапляв у цикл, який він тестував, і тест індикатора для кожної лінійки з однією доріжкою, де мастер просочувався в слот через закон панорами й проходив саме на тій поведінці, яку тест мав відхиляти.","changelog.6c6912c7b7c5":"Виправлено — на що натрапив огляд безпеки","changelog.3bc132875a67":"⚠ <strong><code>/security-review</code> не знайшов жодної вразливості рівня HIGH чи MEDIUM.</strong> Окремо він схвалив заголовок CORS схеми індикаторів: <code>register_uri_scheme_protocol</code> — це перехоплення у webview, а не сокет, тож адреса недосяжна ззовні машини. А те, що він знайшов мимохідь, було гіршим за те, що він шукав.","changelog.e6bf7c677991":"⛔ <strong>Дубль міг бути мовчки обрізаний.</strong> Файли дублів отримували назви за настінним годинником під коментарем, що стверджував про монотонний лічильник, а потік запису використовував <code>File::create</code>, який обрізає файл. ⚠ Це лишалося прихованим, доки закриття дубля не перенесли з потоку інтерфейсу, — після чого новий дубль міг перезаписати той, що ще записувався. Тепер це <code>create_new</code>, справжня послідовність у межах сесії та захист, що не дає почати, поки попередній дубль ще закривається.","changelog.b135c10bd85f":"<strong><code>Access-Control-Allow-Origin</code> — це список дозволених, а не <code>*</code></strong>, — як посилення захисту, а не тому, що це можна було використати.","changelog.c8f633bba310":"Змінено — аудіо у Windows, за рішенням власника (2026-08-25)","changelog.a2460f3b52b6":"⛔ <strong>ASIO вилучено з продукту.</strong> У жовтні 2025 Steinberg запровадила подвійне ліцензування SDK (GPLv3 або пізніша, <strong>або</strong> безкоштовна пропрієтарна угода). ⛔ <strong>Варіант GPLv3 відхилено</strong>: він поставив би власний код Oscillate під копілефт, а GPL <strong>прямо дозволяє іншим продавати</strong> те, що вони отримують. Пропрієтарний варіант — безкоштовний, один підпис, закритий код дозволено — відхилено, щоб не підписувати контракт заради можливості, яку вже дає WASAPI. ⚠ <strong>Він лишається доступним і оборотним; ніщо в коді не залежить від цього вибору.</strong>","changelog.9b112e158a81":"<strong>Низька затримка у Windows — це ексклюзивний режим WASAPI + <code>IAudioClient3</code></strong>, ціль — <code>v0.4.0</code>. ⚠ <strong>Шляху до ASIO через MIT/Apache немає</strong> — кожна обгортка має дозвільну ліцензію, але компілюється із заголовками Steinberg, а ліцензія обгортки не може надати прав на код Steinberg.","changelog.894975a8d218":"<strong>Мінімальна підтримувана версія — Windows 10 1607+</strong>, якої вже вимагають <code>IAudioClient3</code> і WebView2. ⛔ <strong>Windows 11 не потрібна й не повинна стати обов'язковою.</strong>","changelog.f376443b92b4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.0.1</span><time class=\"release__date\" datetime=\"2026-08-24\">2026-08-24</time></span>","changelog.9f343f82939c":"<strong>Фундамент, репозиторій і хребет CI.</strong> Порожнє вікно, яке збирається, запускається й захищене кожною перевіркою, на яку цей проєкт будь-коли покладатиметься, — написаними ще до того, як з'явилося щось варте захисту, бо перевірку, додану пізніше, доводиться протягувати крізь усе, що збудували без неї.","changelog.b9f3e0e185fd":"⚠ <strong>Тег, а не реліз. Завантажень немає й не буде до <code>v1.0.0</code>.</strong> Інсталятори цього щабля зібрали, встановили, запустили й хешували, а потім <strong>залишили в себе, а не опублікували</strong>.","changelog.1c8b846c2976":"Репозиторій, ліцензія «Усі права захищено», EULA і <code>.gitignore</code>, що тримає приватні планувальні документи поза репозиторієм <strong>з першого коміту</strong>.","changelog.26c9317c192c":"Робочий простір Cargo з тринадцяти членів — кожен крейт, якого вимагає архітектура, і кожен — заглушка, що компілюється, — та оболонка Tauri 2.","changelog.0ad7dd57c2b3":"Інтерфейс на React 19 / Vite / TypeScript / Tailwind 4 і токени дизайну Oscillate: обидві теми, причому світла палітра названа рівно один раз.","changelog.b58ef9a54add":"Усі 18 каталогів локалей, вбудовані, а не завантажувані, — англійська перша у виборі мови, решта 17 за абеткою.","changelog.de27cfddc011":"<strong>П'ятнадцять перевірок</strong> і <code>npm run ci:local</code>, щоб запускати їх так, як це робить CI: форматування, лінтинг, типи, модульні тести, clippy під <code>-D warnings</code>, список дозволених ліцензій, згенеровані подяки, перевірка назв продукту, перевірка «без ШІ, телеметрії й HTTP», Playwright і прохід 18 × 2 по темах і мовах.","changelog.014c5ad1e881":"GitHub Actions на Windows, macOS і Linux, де кожна дія закріплена за SHA коміту, а кожен завантажений виконуваний файл звіряється з SHA256.","changelog.6b279b513071":"<code>THIRD-PARTY-NOTICES.md</code> і дані подяк у програмі — обидва згенеровані з реального графа залежностей, тож жоден не може розійтися з тим, що насправді злінковано."};
